(function () {
  const POS_KEY = (id) => "lenny-video-pos-" + id;

  function has(modId) {
    return !!(window.LENNY_VIDEOS && window.LENNY_VIDEOS[modId]);
  }

  function fmt(t) {
    if (!isFinite(t) || t < 0) t = 0;
    const m = Math.floor(t / 60);
    const s = Math.floor(t % 60);
    return m + ":" + String(s).padStart(2, "0");
  }

  function build() {
    if (document.getElementById("lv")) return;
    const el = document.createElement("div");
    el.id = "lv";
    el.className = "lv";
    el.innerHTML = `
      <div class="lv-stage" id="lv-stage">
        <video class="lv-video" id="lv-video" playsinline preload="auto"></video>
      </div>

      <div class="lv-scrim lv-scrim-top"></div>
      <div class="lv-scrim lv-scrim-bottom"></div>

      <div class="lv-top">
        <button class="lv-close" id="lv-close" title="Quitter (Échap)">
          <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><polyline points="11,3 5,9 11,15"/></svg>
          <span>Retour</span>
        </button>
        <div class="lv-head">
          <div class="lv-eyebrow"><span class="L">L</span> · VIDÉO<span class="lv-dot"></span><span id="lv-modlabel">Module</span></div>
          <div class="lv-title" id="lv-title">…</div>
        </div>
      </div>

      <button class="lv-bigplay" id="lv-bigplay" aria-label="Lecture">
        <svg viewBox="0 0 28 28" fill="currentColor"><path d="M7 4 L23 14 L7 24 Z"/></svg>
      </button>

      <div class="lv-loading-overlay" id="lv-loading" aria-live="polite">
        <div class="lv-spinner" aria-hidden="true"></div>
        <div class="lv-loading-tx">Préparation de la vidéo… <span id="lv-loadpct">0 %</span></div>
        <div class="lv-loading-sub">Le téléchargement complet rend l'avance et le retour instantanés.</div>
      </div>

      <div class="lv-controls" id="lv-controls">
        <div class="lv-bar" id="lv-bar">
          <div class="lv-bar-buffered" id="lv-buffered"></div>
          <div class="lv-bar-fill" id="lv-fill"></div>
          <div class="lv-bar-knob" id="lv-knob"></div>
        </div>
        <div class="lv-ctl-row">
          <div class="lv-ctl-left">
            <button class="lv-ic" id="lv-play" aria-label="Lecture / Pause">
              <svg class="ic-play" viewBox="0 0 20 20" fill="currentColor"><path d="M5 3 L16 10 L5 17 Z"/></svg>
              <svg class="ic-pause" viewBox="0 0 20 20" fill="currentColor"><rect x="4.5" y="3.5" width="4" height="13" rx="1"/><rect x="11.5" y="3.5" width="4" height="13" rx="1"/></svg>
            </button>
            <button class="lv-ic" id="lv-back10" aria-label="Reculer de 10 s" title="−10 s">
              <svg viewBox="0 0 22 22" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5 A6.5 6.5 0 1 0 17.2 9.2"/><polyline points="11,2 8,5 11,8"/></svg>
              <span class="lv-ic-n">10</span>
            </button>
            <button class="lv-ic" id="lv-fwd10" aria-label="Avancer de 10 s" title="+10 s">
              <svg viewBox="0 0 22 22" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M11 5 A6.5 6.5 0 1 1 4.8 9.2"/><polyline points="11,2 14,5 11,8"/></svg>
              <span class="lv-ic-n">10</span>
            </button>
            <button class="lv-ic" id="lv-mute" aria-label="Couper le son">
              <svg class="ic-vol" viewBox="0 0 22 22" fill="currentColor"><path d="M4 8 H7 L11 4 V18 L7 14 H4 Z"/><path d="M14 7 a5 5 0 0 1 0 8" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/><path d="M16.5 5 a8 8 0 0 1 0 12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>
              <svg class="ic-mute" viewBox="0 0 22 22" fill="currentColor"><path d="M4 8 H7 L11 4 V18 L7 14 H4 Z"/><line x1="14" y1="8" x2="19" y2="14" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/><line x1="19" y1="8" x2="14" y2="14" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg>
            </button>
            <div class="lv-time"><span id="lv-cur">0:00</span> <span class="lv-time-sep">/</span> <span id="lv-dur">0:00</span></div>
          </div>
          <div class="lv-ctl-right">
            <div class="lv-now" id="lv-now">…</div>
            <button class="lv-ic lv-speed" id="lv-speed" aria-label="Vitesse de lecture" title="Vitesse de lecture"><span id="lv-speed-tx">1×</span></button>
            <button class="lv-ic" id="lv-full" aria-label="Plein écran">
              <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><polyline points="3,7 3,3 7,3"/><polyline points="13,3 17,3 17,7"/><polyline points="17,13 17,17 13,17"/><polyline points="7,17 3,17 3,13"/></svg>
            </button>
          </div>
        </div>
      </div>
    `;
    document.body.appendChild(el);
    wire();
  }

  const S = { modId: null, video: null, hideTimer: null, dragging: false, rate: 1, blobUrl: null, seekFull: false, loadToken: 0 };

  const SPEEDS = [1, 1.25, 1.5, 1.75, 2];
  const RATE_KEY = "lenny-video-rate";
  function applyRate(r) {
    S.rate = r;
    if (S.video) S.video.playbackRate = r;
    const tx = document.getElementById("lv-speed-tx");
    if (tx) tx.textContent = (Number.isInteger(r) ? r : r) + "\u00d7";
    const btn = document.getElementById("lv-speed");
    if (btn) btn.classList.toggle("active", r !== 1);
    try { localStorage.setItem(RATE_KEY, String(r)); } catch (e) {}
  }
  function cycleSpeed() {
    const i = SPEEDS.indexOf(S.rate);
    applyRate(SPEEDS[(i + 1) % SPEEDS.length]);
    pokeControls();
  }

  // Seek robuste. Quand le fichier complet est chargé (Blob), la vidéo est
  // entièrement navigable et on ne borne qu'aux extrémités. Sinon (lecture en
  // streaming sur un hôte sans support des requêtes Range), on borne la cible à
  // la zone réellement téléchargée (buffered) — sinon le navigateur retombe à 0.
  function safeSeek(target) {
    const v = S.video;
    if (!v || !isFinite(v.duration)) return;
    let t = Math.max(0, Math.min(v.duration, target));
    if (!S.seekFull) {
      const bf = v.buffered;
      if (bf && bf.length) {
        const end = bf.end(bf.length - 1);
        if (t > end - 0.3) t = Math.max(0, end - 0.3);
      } else {
        t = 0;
      }
    }
    try { v.currentTime = t; } catch (e) {}
  }

  function wire() {
    const v = document.getElementById("lv-video");
    S.video = v;
    const el = document.getElementById("lv");

    document.getElementById("lv-close").addEventListener("click", close);
    document.getElementById("lv-play").addEventListener("click", togglePlay);
    document.getElementById("lv-bigplay").addEventListener("click", togglePlay);
    document.getElementById("lv-stage").addEventListener("click", (e) => {
      if (e.target === v || e.target.id === "lv-stage") togglePlay();
    });
    document.getElementById("lv-back10").addEventListener("click", () => { safeSeek(v.currentTime - 10); pokeControls(); });
    document.getElementById("lv-fwd10").addEventListener("click", () => { safeSeek(v.currentTime + 10); pokeControls(); });
    document.getElementById("lv-mute").addEventListener("click", () => { v.muted = !v.muted; reflectMute(); pokeControls(); });
    document.getElementById("lv-speed").addEventListener("click", cycleSpeed);
    document.getElementById("lv-full").addEventListener("click", toggleFull);

    // progress bar
    const bar = document.getElementById("lv-bar");
    const seekTo = (clientX) => {
      const r = bar.getBoundingClientRect();
      const p = Math.min(1, Math.max(0, (clientX - r.left) / r.width));
      if (isFinite(v.duration)) safeSeek(p * v.duration);
      paintBar();
    };
    bar.addEventListener("pointerdown", (e) => { S.dragging = true; bar.setPointerCapture(e.pointerId); seekTo(e.clientX); });
    bar.addEventListener("pointermove", (e) => { if (S.dragging) seekTo(e.clientX); });
    bar.addEventListener("pointerup", () => { S.dragging = false; });

    // garde la barre navigable : suit l'avancement du téléchargement
    v.addEventListener("canplay", paintBuffered);
    v.addEventListener("loadeddata", paintBuffered);

    // video events
    v.addEventListener("timeupdate", () => { paintBar(); savePos(); });
    v.addEventListener("progress", paintBuffered);
    v.addEventListener("loadedmetadata", () => { document.getElementById("lv-dur").textContent = fmt(v.duration); paintBar(); });
    v.addEventListener("play", () => { reflectPlay(); pokeControls(); });
    v.addEventListener("pause", () => { reflectPlay(); showControls(); });
    v.addEventListener("ended", () => { reflectPlay(); showControls(); clearPos(); });

    // auto-hide controls on idle while playing
    el.addEventListener("mousemove", pokeControls);
    el.addEventListener("touchstart", pokeControls, { passive: true });

    // keyboard
    document.addEventListener("keydown", (e) => {
      if (!el.classList.contains("open")) return;
      switch (e.key) {
        case "Escape": e.preventDefault(); close(); break;
        case " ": case "k": e.preventDefault(); togglePlay(); break;
        case "ArrowLeft": e.preventDefault(); safeSeek(v.currentTime - 5); pokeControls(); break;
        case "ArrowRight": e.preventDefault(); safeSeek(v.currentTime + 5); pokeControls(); break;
        case "m": e.preventDefault(); v.muted = !v.muted; reflectMute(); break;
        case "f": e.preventDefault(); toggleFull(); break;
        case ">": case ".": e.preventDefault(); { const i = SPEEDS.indexOf(S.rate); applyRate(SPEEDS[Math.min(SPEEDS.length - 1, i + 1)]); pokeControls(); } break;
        case "<": case ",": e.preventDefault(); { const i = SPEEDS.indexOf(S.rate); applyRate(SPEEDS[Math.max(0, i - 1)]); pokeControls(); } break;
      }
    });
  }

  function paintBar() {
    const v = S.video;
    const p = isFinite(v.duration) && v.duration ? (v.currentTime / v.duration) * 100 : 0;
    document.getElementById("lv-fill").style.width = p + "%";
    document.getElementById("lv-knob").style.left = p + "%";
    document.getElementById("lv-cur").textContent = fmt(v.currentTime);
  }
  function paintBuffered() {
    const v = S.video;
    if (!v.buffered || !v.buffered.length || !isFinite(v.duration)) return;
    const end = v.buffered.end(v.buffered.length - 1);
    document.getElementById("lv-buffered").style.width = (end / v.duration * 100) + "%";
  }
  function reflectPlay() {
    const playing = !S.video.paused && !S.video.ended;
    document.getElementById("lv").classList.toggle("playing", playing);
  }
  function reflectMute() {
    document.getElementById("lv").classList.toggle("muted", S.video.muted);
  }
  function togglePlay() {
    const v = S.video;
    if (v.paused) v.play().catch(() => {}); else v.pause();
  }
  function toggleFull() {
    const el = document.getElementById("lv");
    const v = S.video;
    const fsEl = document.fullscreenElement || document.webkitFullscreenElement;
    if (fsEl) {
      (document.exitFullscreen || document.webkitExitFullscreen || function () {}).call(document);
      return;
    }
    const req = el.requestFullscreen || el.webkitRequestFullscreen;
    if (req) {
      let p;
      try { p = req.call(el); } catch (e) { p = null; }
      // Repli iOS Safari : plein écran natif de l'élément <video>
      if (p && p.catch) p.catch(() => { if (v && v.webkitEnterFullscreen) { try { v.webkitEnterFullscreen(); } catch (e) {} } });
    } else if (v && v.webkitEnterFullscreen) {
      try { v.webkitEnterFullscreen(); } catch (e) {}
    }
  }

  function showControls() {
    document.getElementById("lv").classList.add("show-ctl");
    if (S.hideTimer) { clearTimeout(S.hideTimer); S.hideTimer = null; }
  }
  function pokeControls() {
    showControls();
    if (S.video.paused) return;
    S.hideTimer = setTimeout(() => {
      document.getElementById("lv").classList.remove("show-ctl");
    }, 2600);
  }

  function savePos() {
    if (!S.modId || !isFinite(S.video.duration)) return;
    try { localStorage.setItem(POS_KEY(S.modId), String(S.video.currentTime)); } catch (e) {}
  }
  function clearPos() {
    if (!S.modId) return;
    try { localStorage.removeItem(POS_KEY(S.modId)); } catch (e) {}
  }
  function readPos(modId) {
    try { const v = parseFloat(localStorage.getItem(POS_KEY(modId))); return isFinite(v) ? v : 0; } catch (e) { return 0; }
  }

  function setLoadProgress(p) {
    const el = document.getElementById("lv-loadpct");
    if (el) el.textContent = (p == null ? "" : Math.round(p * 100) + "\u00a0%");
  }

  // Télécharge le fichier en suivant la progression (renvoie un Blob).
  async function fetchWithProgress(url, onProgress) {
    const resp = await fetch(url);
    if (!resp.ok) throw new Error("HTTP " + resp.status);
    const total = +(resp.headers.get("content-length") || 0);
    if (!resp.body || !total || !resp.body.getReader) {
      onProgress && onProgress(null);
      return await resp.blob();
    }
    const reader = resp.body.getReader();
    const chunks = [];
    let received = 0;
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
      received += value.length;
      onProgress && onProgress(received / total);
    }
    return new Blob(chunks, { type: resp.headers.get("content-type") || "video/mp4" });
  }

  // Charge la vidéo : on récupère d'abord le fichier complet (Blob) pour une
  // navigation 100 % fiable, même si l'hôte ne gère pas les requêtes Range.
  function loadVideo(meta, modId) {
    const v = S.video;
    const el = document.getElementById("lv");
    const token = ++S.loadToken;

    if (S.blobUrl) { try { URL.revokeObjectURL(S.blobUrl); } catch (e) {} S.blobUrl = null; }
    S.seekFull = false;
    el.classList.add("lv-loading");
    setLoadProgress(0);

    const resume = readPos(modId);
    const startPlayback = (seekable) => {
      if (token !== S.loadToken) return;
      el.classList.remove("lv-loading");
      v.addEventListener("loadedmetadata", function once() {
        v.removeEventListener("loadedmetadata", once);
        v.playbackRate = S.rate;
        if (seekable && resume > 2 && resume < v.duration - 5) { try { v.currentTime = resume; } catch (e) {} }
        v.play().catch(() => { /* autoplay bloqué — le gros bouton lecture reste */ });
      });
      v.load();
    };

    fetchWithProgress(meta.src, (p) => { if (token === S.loadToken) setLoadProgress(p); })
      .then((blob) => {
        if (token !== S.loadToken) return;            // l'utilisateur a changé / fermé
        S.blobUrl = URL.createObjectURL(blob);
        S.seekFull = true;                            // navigation totale débloquée
        v.src = S.blobUrl;
        startPlayback(true);
      })
      .catch(() => {
        if (token !== S.loadToken) return;
        // repli : lecture en streaming (avance limitée à la zone téléchargée)
        S.seekFull = false;
        v.src = meta.src;
        startPlayback(false);
      });
  }

  function open(modId) {
    const meta = window.LENNY_VIDEOS && window.LENNY_VIDEOS[modId];
    if (!meta) return;
    build();
    S.modId = modId;
    const mods = (typeof LENNY_MODULES !== "undefined") ? LENNY_MODULES : (window.LENNY_MODULES || []);
    const mod = mods.find(m => m.id === modId) || {};

    document.getElementById("lv-title").textContent = meta.title;
    document.getElementById("lv-now").textContent = meta.title;
    document.getElementById("lv-modlabel").textContent = (mod.tag ? mod.tag + " · " : "") + (mod.short || (meta.kicker || "").replace(/^vid[ée]o\s*·\s*/i, ""));

    const v = S.video;
    if (meta.poster) v.poster = meta.poster;
    v.muted = false; reflectMute();
    // restaure la vitesse choisie (les navigateurs la réinitialisent au changement de src)
    try { const r = parseFloat(localStorage.getItem(RATE_KEY)); applyRate(SPEEDS.includes(r) ? r : 1); } catch (e) { applyRate(1); }

    const el = document.getElementById("lv");
    el.classList.add("open");
    document.body.style.overflow = "hidden";

    loadVideo(meta, modId);
    showControls();
  }

  function close() {
    const el = document.getElementById("lv");
    if (!el) return;
    savePos();
    S.loadToken++;                       // annule un téléchargement en cours
    try { S.video.pause(); } catch (e) {}
    const fsEl = document.fullscreenElement || document.webkitFullscreenElement;
    if (fsEl) { try { (document.exitFullscreen || document.webkitExitFullscreen).call(document); } catch (e) {} }
    el.classList.remove("open", "lv-loading");
    document.body.style.overflow = "";
    // free the buffer
    setTimeout(() => {
      if (!el.classList.contains("open")) {
        S.video.removeAttribute("src"); S.video.load();
        if (S.blobUrl) { try { URL.revokeObjectURL(S.blobUrl); } catch (e) {} S.blobUrl = null; }
        S.seekFull = false;
      }
    }, 400);
    if (window.LennySplash) window.LennySplash(900);
  }

  window.LennyVideo = { open, close, has };
})();

;
/* ===== lenny-api.js ===== */
/* ============================================
   LENNY — Couche de données enfichable
   • Par défaut : persistance locale (localStorage) → tout marche hors-ligne.
   • Si window.LENNY_API_BASE est défini (ex: "https://api.monsite.fr"),
     bascule automatiquement sur le backend FastAPI + MongoDB.
   Toutes les méthodes renvoient des Promises.
   Dépend de : MODULES, window.QUIZ / window.STUDY (pour la liste des matières)
   ============================================ */
window.LennyAPI = (function () {
  const DAY = 86400000;
  const base = () => (window.LENNY_API_BASE || "").replace(/\/$/, "");
  const remote = () => !!base();

  // —— identité utilisateur (liée au portail d'accès / code élève) ——
  function auth() { return window.LennyAuth || null; }
  function userId() {
    try {
      const a = auth();
      if (a && a.code) return "u_" + a.code;
      const fromGate = localStorage.getItem("lenny-access-code");
      if (fromGate) return "u_" + fromGate;
      let u = localStorage.getItem("lenny-uid");
      if (!u) { u = "u_" + Math.random().toString(36).slice(2, 10); localStorage.setItem("lenny-uid", u); }
      return u;
    } catch (e) { return "u_anon"; }
  }
  function userName() {
    const a = auth();
    if (a && a.name) return a.name;
    return "Élève";
  }
  function isAdmin() { const a = auth(); return !!(a && a.isAdmin); }

  // Libellé lisible d'un identifiant de contenu (course-m11 → « Financement · Cours »)
  function labelFor(courseId) {
    const mods = window.MODULES || [];
    const m = (id) => (mods.find(x => x.id === id) || {}).short || id;
    if (courseId === "quiz-general") return { label: "Quiz général", type: "quiz" };
    if (courseId.indexOf("course-") === 0) return { label: m(courseId.slice(7)) + " · Cours", type: "course" };
    if (courseId.indexOf("quiz-") === 0) return { label: m(courseId.slice(5)) + " · Quiz", type: "quiz" };
    return { label: courseId, type: "autre" };
  }

  // —— util local storage ——
  function read(key, fallback) {
    try { const v = JSON.parse(localStorage.getItem(key)); return v == null ? fallback : v; }
    catch (e) { return fallback; }
  }
  function write(key, val) { try { localStorage.setItem(key, JSON.stringify(val)); } catch (e) {} }

  // Hash déterministe → compteurs de base « communauté » crédibles en local
  function hash(str) {
    let h = 2166136261;
    for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
    return (h >>> 0);
  }
  function seedCounts(courseId) {
    const h = hash(courseId);
    return { up: 6 + (h % 34), down: (h >> 5) % 6 }; // up 6..39, down 0..5
  }

  /* ============================================================
     1) AVIS (pouce vert / pouce rouge)
     ============================================================ */
  // Tous les votes, nominatifs : [{ courseId, userId, name, vote, date }]
  const VOTES_KEY = "lenny-feedback-all-v1";

  function readVotes() { return read(VOTES_KEY, []); }
  function writeVotes(v) { write(VOTES_KEY, v); }

  async function sendFeedback(courseId, vote) {
    // vote ∈ 'up' | 'down' | null (null = annulation). Re-clic même pouce = annulation.
    const me = userId();
    const votes = readVotes();
    const idx = votes.findIndex(v => v.courseId === courseId && v.userId === me);
    const prev = idx >= 0 ? votes[idx].vote : null;
    const next = (prev === vote) ? null : vote;
    if (next) {
      const entry = { courseId, userId: me, name: userName(), vote: next, date: new Date().toISOString() };
      if (idx >= 0) votes[idx] = entry; else votes.push(entry);
    } else if (idx >= 0) {
      votes.splice(idx, 1);
    }
    writeVotes(votes);

    if (remote()) {
      try {
        await fetch(base() + "/api/feedback", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ course_id: courseId, vote: next, user_id: me, user_name: userName(), date: new Date().toISOString() }),
        });
      } catch (e) { /* on garde l'état local même si le réseau échoue */ }
    }
    return getFeedback(courseId);
  }

  async function getFeedback(courseId) {
    const me = userId();
    if (remote()) {
      try {
        const r = await fetch(base() + "/api/feedback/" + encodeURIComponent(courseId) + "?user_id=" + encodeURIComponent(me));
        if (r.ok) { const d = await r.json(); return { up: d.up || 0, down: d.down || 0, mine: d.mine ?? null }; }
      } catch (e) {}
    }
    const votes = readVotes().filter(v => v.courseId === courseId);
    const up = votes.filter(v => v.vote === "up").length;
    const down = votes.filter(v => v.vote === "down").length;
    const mineEntry = votes.find(v => v.userId === me);
    return { up, down, mine: mineEntry ? mineEntry.vote : null };
  }

  // —— Tableau de bord formateur : tous les avis, par contenu, nominatifs ——
  async function getFeedbackAdmin() {
    if (remote()) {
      try {
        const r = await fetch(base() + "/api/feedback/admin?user_id=" + encodeURIComponent(userId()));
        if (r.ok) {
          const d = await r.json();
          (d.rows || []).forEach(row => {
            if (!row.label) { const m = labelFor(row.courseId); row.label = m.label; row.type = m.type; }
          });
          return d;
        }
      } catch (e) {}
    }
    const votes = readVotes();
    const byCourse = {};
    votes.forEach(v => {
      (byCourse[v.courseId] = byCourse[v.courseId] || []).push(v);
    });
    const rows = Object.keys(byCourse).map(courseId => {
      const list = byCourse[courseId];
      const up = list.filter(v => v.vote === "up").length;
      const down = list.filter(v => v.vote === "down").length;
      const total = up + down;
      const meta = labelFor(courseId);
      return {
        courseId, label: meta.label, type: meta.type,
        up, down, total,
        satisfaction: total ? Math.round((up / total) * 100) : null,
        voters: list
          .map(v => ({ name: v.name, vote: v.vote, date: v.date }))
          .sort((a, b) => (a.date < b.date ? 1 : -1)),
      };
    });
    return { rows };
  }

  /* ============================================================
     2) HISTORIQUE DES QUIZ (horodaté) → alimente le radar
     ============================================================ */
  const HIST_KEY = "lenny-quiz-history-v1";  // [{ moduleId, correct, total, ts }]

  async function recordQuizResult(res) {
    // res = { moduleId, correct, total }
    const entry = {
      moduleId: res.moduleId || "general",
      correct: res.correct | 0,
      total: Math.max(1, res.total | 0),
      ts: Date.now(),
    };
    const hist = read(HIST_KEY, []);
    hist.push(entry);
    // Plafond large (5000 résultats) : sert au vrai suivi de progression,
    // mais ne doit jamais grandir sans fin et saturer le quota du navigateur.
    write(HIST_KEY, hist.slice(-5000));

    if (remote()) {
      const mod = (window.MODULES || []).find(m => m.id === entry.moduleId);
      try {
        await fetch(base() + "/api/quiz-result", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ...entry, subject: mod ? mod.short : entry.moduleId, user_id: userId(), date: new Date(entry.ts).toISOString() }),
        });
      } catch (e) {}
    }
    return entry;
  }

  // Matières = modules qui possèdent réellement des questions de quiz
  function subjects() {
    const mods = window.MODULES || [];
    return mods.filter(m => {
      const qs = (window.QUIZ && window.QUIZ[m.id]) || (window.STUDY && window.STUDY[m.id] && window.STUDY[m.id].quiz) || [];
      return qs.length > 0;
    }).map(m => ({ id: m.id, label: m.short, color: m.color }));
  }

  function scoreFor(hist, moduleId, start, end) {
    let c = 0, t = 0, n = 0;
    hist.forEach(h => {
      if (h.moduleId === moduleId && h.ts >= start && h.ts < end) { c += h.correct; t += h.total; n++; }
    });
    return { score: t ? Math.round((c / t) * 100) : 0, evaluated: n > 0, sessions: n };
  }

  async function getRadar(period) {
    const p = parseInt(period, 10) || 14;
    if (remote()) {
      try {
        const r = await fetch(base() + "/api/stats/radar?period=" + p + "&user_id=" + encodeURIComponent(userId()));
        if (r.ok) return await r.json();
      } catch (e) {}
    }
    const hist = read(HIST_KEY, []);
    const now = Date.now();
    const curStart = now - p * DAY;
    const prevStart = now - 2 * p * DAY;
    const subs = subjects();
    const current = [], previous = [];
    subs.forEach(s => {
      const cur = scoreFor(hist, s.id, curStart, now + 1);
      const prv = scoreFor(hist, s.id, prevStart, curStart);
      current.push({ id: s.id, subject: s.label, score: cur.score, evaluated: cur.evaluated });
      previous.push({ id: s.id, subject: s.label, score: prv.score, evaluated: prv.evaluated });
    });
    return { period: p, subjects: subs, current, previous };
  }

  /* ============================================================
     Mode démo retiré. Aucune donnée factice n'est amorcée :
     le radar et la progression partent de zéro et ne se remplissent
     qu'avec les vrais résultats de quiz terminés.
     ============================================================ */

  // Nettoyage des avis factices présents (votants de démo, userId préfixé "u_seed_")
  function purgeDemoVotes() {
    const votes = readVotes();
    if (!votes.length) return;
    const real = votes.filter(v => !String(v.userId || "").startsWith("u_seed_"));
    if (real.length !== votes.length) writeVotes(real);
  }

  // Remise à zéro unique du taux d'évolution : on efface l'historique amorcé
  // par l'ancien mode démo (une seule fois) pour repartir d'une ardoise vierge.
  // Les vrais quiz terminés après ce passage s'accumulent normalement.
  function resetEvolutionOnce() {
    if (read("lenny-evolution-reset-v2", false)) return;
    try { localStorage.removeItem(HIST_KEY); } catch (e) {}
    try { localStorage.removeItem("lenny-seeded-v1"); } catch (e) {}
    try { localStorage.removeItem("lenny-votes-seeded-v1"); } catch (e) {}
    write("lenny-evolution-reset-v2", true);
  }
  function seedAll() { resetEvolutionOnce(); purgeDemoVotes(); }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => setTimeout(seedAll, 0));
  } else { setTimeout(seedAll, 0); }

  return { sendFeedback, getFeedback, getFeedbackAdmin, recordQuizResult, getRadar, subjects, userId, userName, isAdmin, labelFor, remote };
})();

;
/* ===== lenny-feedback.js ===== */
/* ============================================
   LENNY — Avis 👍 / 👎 (pouce vert / pouce rouge)
   Usage : LennyFeedback.mount(targetEl, courseId, { label })
   Dépend de : LennyAPI
   ============================================ */
window.LennyFeedback = (function () {

  const UP_SVG = '<svg viewBox="0 0 20 20" fill="currentColor" aria-hidden="true"><path d="M7.5 8.6 11 1.8c.9 0 1.9.7 1.9 2 0 .9-.5 2.3-.8 3.1h3.7c1 0 1.8.8 1.8 1.8 0 .3-.1.6-.2.8.4.3.7.8.7 1.4 0 .5-.2.9-.5 1.2.2.3.3.6.3 1 0 .6-.3 1.1-.8 1.4.1.2.1.4.1.6 0 1-.8 1.8-1.8 1.8H9.2c-1 0-1.9-.3-2.7-.8V8.9c.4-.1.7-.2 1-.3ZM3 9h2.2v8.2H3A.9.9 0 0 1 2 16.3V9.9A.9.9 0 0 1 3 9Z"/></svg>';
  const DN_SVG = '<svg viewBox="0 0 20 20" fill="currentColor" aria-hidden="true" style="transform:rotate(180deg)"><path d="M7.5 8.6 11 1.8c.9 0 1.9.7 1.9 2 0 .9-.5 2.3-.8 3.1h3.7c1 0 1.8.8 1.8 1.8 0 .3-.1.6-.2.8.4.3.7.8.7 1.4 0 .5-.2.9-.5 1.2.2.3.3.6.3 1 0 .6-.3 1.1-.8 1.4.1.2.1.4.1.6 0 1-.8 1.8-1.8 1.8H9.2c-1 0-1.9-.3-2.7-.8V8.9c.4-.1.7-.2 1-.3ZM3 9h2.2v8.2H3A.9.9 0 0 1 2 16.3V9.9A.9.9 0 0 1 3 9Z"/></svg>';

  function mount(target, courseId, opts) {
    opts = opts || {};
    if (!target || !courseId) return;
    // évite les doublons si on remonte le même widget
    const existing = target.querySelector(":scope > .lfb[data-course='" + cssEsc(courseId) + "']");
    if (existing) existing.remove();

    const el = document.createElement("div");
    el.className = "lfb";
    el.dataset.course = courseId;
    el.innerHTML = `
      <span class="lfb-label">${opts.label || "Ce contenu vous a-t-il été utile ?"}</span>
      <div class="lfb-btns">
        <button class="lfb-btn lfb-up" data-vote="up" aria-pressed="false" title="Pertinent">
          <span class="lfb-ic">${UP_SVG}</span><span class="lfb-n" data-up>—</span>
        </button>
        <button class="lfb-btn lfb-down" data-vote="down" aria-pressed="false" title="À améliorer">
          <span class="lfb-ic">${DN_SVG}</span><span class="lfb-n" data-down>—</span>
        </button>
      </div>
      <span class="lfb-thanks" hidden>Merci pour votre retour</span>
    `;
    target.appendChild(el);

    const upBtn = el.querySelector(".lfb-up");
    const dnBtn = el.querySelector(".lfb-down");
    const upN = el.querySelector("[data-up]");
    const dnN = el.querySelector("[data-down]");
    const thanks = el.querySelector(".lfb-thanks");

    function paint(state) {
      upN.textContent = state.up;
      dnN.textContent = state.down;
      upBtn.classList.toggle("active", state.mine === "up");
      dnBtn.classList.toggle("active", state.mine === "down");
      upBtn.setAttribute("aria-pressed", String(state.mine === "up"));
      dnBtn.setAttribute("aria-pressed", String(state.mine === "down"));
      thanks.hidden = !state.mine;
    }

    let busy = false;
    async function vote(v) {
      if (busy) return; busy = true;
      const btn = v === "up" ? upBtn : dnBtn;
      btn.classList.add("pop");
      setTimeout(() => btn.classList.remove("pop"), 280);
      try { paint(await LennyAPI.sendFeedback(courseId, v)); }
      finally { busy = false; }
    }
    upBtn.addEventListener("click", () => vote("up"));
    dnBtn.addEventListener("click", () => vote("down"));

    LennyAPI.getFeedback(courseId).then(paint);
    return el;
  }

  function cssEsc(s) { return String(s).replace(/['"\\]/g, "\\$&"); }

  return { mount };
})();

;
