function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function reviseLink(modId) {
  // Used as href fallback; click is intercepted to open the in-page detail modal
  return `#${modId}`;
}

