/* ---------- variation hebdomadaire du classement ---------- */
// Numéro de semaine ISO (stable du lundi au dimanche, change chaque semaine).
function isoWeek(d = new Date()) {
  const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const day = t.getUTCDay() || 7;
  t.setUTCDate(t.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
  const wk = Math.ceil(((t - yearStart) / 86400000 + 1) / 7);
  return t.getUTCFullYear() * 53 + wk;
}
function seededShuffle(arr, seed) {
  const a = [...arr];
  let s = seed % 2147483647; if (s <= 0) s += 2147483646;
  const rnd = () => (s = (s * 16807) % 2147483647) / 2147483647;
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}
// Pour chaque position de cette semaine, écart de rang vs la semaine précédente.
function weeklyDeltas(ids) {
  const lastWeek = seededShuffle(ids, isoWeek() - 1);
  return ids.map((id, i) => {
    const lastRank = lastWeek.indexOf(id);
    return lastRank < 0 ? null : lastRank - i; // >0 monte, <0 descend, 0 stable
  });
}
function deltaBadge(delta) {
  if (delta === null || delta === undefined) return `<span class="rank-delta new" title="Nouvelle entrée">NEW</span>`;
  if (delta === 0) return `<span class="rank-delta flat" title="Stable">=</span>`;
  const up = delta > 0;
  return `<span class="rank-delta ${up ? "up" : "down"}" title="${up ? "En hausse" : "En baisse"} de ${Math.abs(delta)}">
    <svg viewBox="0 0 8 8" fill="currentColor">${up ? '<path d="M4 1 L7 6 H1 Z"/>' : '<path d="M4 7 L1 2 H7 Z"/>'}</svg>${Math.abs(delta)}</span>`;
}

function cardHtml(mod, opts = {}) {
  const { progress, rank, delta } = opts;
  const hasVideo = !!(window.LENNY_VIDEOS && window.LENNY_VIDEOS[mod.id]);
  const videoFlag = hasVideo
    ? `<span class="card-video-flag"><svg viewBox="0 0 10 10" fill="currentColor"><path d="M2 1 L9 5 L2 9 Z"/></svg>Vidéo</span>` : "";
  const videoBtn = hasVideo
    ? `<span class="cbtn video" title="Voir la vidéo" data-video="${mod.id}"><svg viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.3"><rect x="1.4" y="3" width="11.2" height="8" rx="1.3"/><path d="M5.8 5.4 L9 7 L5.8 8.6 Z" fill="currentColor" stroke="none"/></svg></span>` : "";
  return `
    <a class="card ${rank ? "top10" : ""}" href="${reviseLink(mod.id)}" data-mod="${mod.id}">
      ${rank ? `<span class="rank">${rank}</span>${delta !== undefined ? deltaBadge(delta) : ""}<div class="top-art art-${mod.color}${MOD_PHOTOS[mod.id] ? " has-photo" : ""}">${videoFlag}${cardPhotoLayers(mod)}${cardArtHtml(mod)}</div>` : `
      <div class="card-art art-${mod.color}${MOD_PHOTOS[mod.id] ? " has-photo" : ""}">
        ${videoFlag}
        ${cardPhotoLayers(mod)}
        ${cardArtHtml(mod)}
        <div class="art-title-top">${escapeHtml(mod.title)}</div>
        <span class="card-num">${mod.num}</span>
      </div>`}
      ${progress != null ? `<div class="progress"><i style="width:${progress}%"></i></div>` : ""}
      <div class="card-overlay">
        <div class="card-overlay-title">${escapeHtml(mod.title)}</div>
        <div class="card-overlay-meta">
          <span>${mod.season}</span>
          <span>·</span>
          <span>${mod.time} min</span>
        </div>
        <div class="card-overlay-actions">
          <span class="cbtn play" title="Réviser">
            <svg viewBox="0 0 12 12" fill="currentColor"><path d="M3 1.5 L10 6 L3 10.5 Z"/></svg>
          </span>
          ${videoBtn}
          <span class="cbtn add" title="Ajouter à Ma Liste" data-add="${mod.id}">
            <svg class="ic-plus" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><line x1="6" y1="2" x2="6" y2="10"/><line x1="2" y1="6" x2="10" y2="6"/></svg>
            <svg class="ic-check" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><polyline points="2.5,6.5 5,9 9.5,3.5"/></svg>
          </span>
          <span class="cbtn" title="Plus d'infos">
            <svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.4"><polyline points="3,4.5 6,7.5 9,4.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </span>
        </div>
      </div>
    </a>
  `;
}

function lawCardHtml(law) {
  return `
    <a class="card" href="${reviseLink(law.id)}" data-mod="${law.id}">
      <div class="card-art art-${law.color}">
        <span class="badge"><span class="L">L</span> · LOI</span>
        <div style="position:absolute;left:14px;top:42%;font-family:'Inter';font-weight:900;font-size:34px;letter-spacing:-.02em;color:rgba(255,255,255,.92);line-height:.9">${escapeHtml(law.num)}</div>
        <div class="art-sub">${escapeHtml(law.year)}</div>
        <div class="art-title">${escapeHtml(law.title)}</div>
        <span class="card-num">·</span>
      </div>
      <div class="card-overlay">
        <div class="card-overlay-title">${escapeHtml(law.title)}</div>
        <div class="card-overlay-meta">
          <span class="ok">${escapeHtml(law.year)}</span>
          <span>·</span>
          <span>Réglementation</span>
        </div>
        <div style="font-size:11.5px;color:rgba(255,255,255,.7);line-height:1.4">${escapeHtml(law.desc)}</div>
      </div>
    </a>
  `;
}

// ============================================
// Ma Liste (persisted in localStorage)
// ============================================
const MYLIST_KEY = "lenny-mylist-v1";

function getMyList() {
  try {
    const v = JSON.parse(localStorage.getItem(MYLIST_KEY) || "[]");
    return Array.isArray(v) ? v.filter(id => LENNY_MODULES.find(m => m.id === id)) : [];
  } catch (e) { return []; }
}
function setMyList(ids) {
  try { localStorage.setItem(MYLIST_KEY, JSON.stringify(ids)); } catch (e) {}
}
function isInMyList(id) { return getMyList().includes(id); }

function toggleMyList(id) {
  const list = getMyList();
  const i = list.indexOf(id);
  if (i === -1) list.push(id); else list.splice(i, 1);
  setMyList(list);
  renderMyList();
  syncAddButtons();
  return i === -1; // true if added
}

function renderMyList() {
  const section = document.getElementById("mylist");
  const row = document.getElementById("row-mylist");
  const meta = document.getElementById("mylist-meta");
  if (!section || !row) return;
  const ids = getMyList();
  const byId = (id) => LENNY_MODULES.find(m => m.id === id);
  if (ids.length === 0) {
    section.hidden = true;
    row.innerHTML = "";
    return;
  }
  section.hidden = false;
  // Ensure the row is fully revealed even if it was display:none when the
  // scroll-reveal observer ran (otherwise it stays stuck at opacity:0).
  section.classList.add("reveal", "in");
  row.innerHTML = ids.map(id => cardHtml(byId(id))).join("");
  if (meta) meta.textContent = ids.length + (ids.length > 1 ? " fiches" : " fiche");
  syncAddButtons();
}

// Reflect membership on every "+" button (plus ↔ check)
function syncAddButtons() {
  document.querySelectorAll(".cbtn.add[data-add]").forEach(btn => {
    const id = btn.getAttribute("data-add");
    const inList = isInMyList(id);
    btn.classList.toggle("added", inList);
    btn.setAttribute("title", inList ? "Retirer de Ma Liste" : "Ajouter à Ma Liste");
  });
}

// Public API (used by the detail modal)
window.LennyList = {
  has: isInMyList,
  toggle: toggleMyList,
  render: renderMyList,
  sync: syncAddButtons,
};

// ============================================
// Boot
// ============================================
function lennyInit() {
  // Hide boot splash
  setTimeout(() => {
    const boot = document.getElementById("boot");
    if (boot) {
      boot.classList.add("hide");
      setTimeout(() => boot.remove(), 700);
    }
  }, 650);

  // Build rows
  const trending  = ["mdroit","mprop","mvert","murba","mville","m11","m2","m8","m6","m4","m3","m5","m6b","m1","syn"];
  const originals = ["m1","mdroit","mprop","mvert","murba","mville","m2","m3","m4"];
  const top10     = ["m11","mdroit","mprop","mvert","murba","mville","m6","m8","m2","m3"];
  const continueR = [ { id: "m11", p: 64 }, { id: "m6", p: 38 }, { id: "m8", p: 80 }, { id: "m2", p: 22 } ];

  const byId = (id) => LENNY_MODULES.find(m => m.id === id);

  const rowTrending = document.getElementById("row-trending");
  if (rowTrending) rowTrending.innerHTML = trending.map(id => cardHtml(byId(id))).join("");

  const rowOriginals = document.getElementById("row-originals");
  if (rowOriginals) rowOriginals.innerHTML = originals.map(id => cardHtml(byId(id))).join("");

  const rowTop10 = document.getElementById("row-top10");
  if (rowTop10) {
    const ids = top10.slice(0, 10);
    const deltas = weeklyDeltas(ids);
    rowTop10.innerHTML = ids.map((id, i) => cardHtml(byId(id), { rank: i + 1, delta: deltas[i] })).join("");
  }

  const rowContinue = document.getElementById("row-continue");
  if (rowContinue) rowContinue.innerHTML = continueR.map(({ id, p }) => cardHtml(byId(id), { progress: p })).join("");

  const rowLaws = document.getElementById("row-laws");
  if (rowLaws) rowLaws.innerHTML = LAWS.map(lawCardHtml).join("");

  const droitIds = ["mdsources","mddeonto","mdjustice","mdfamille","mdpreuve","mdcontrats","mdroit","mprop"];
  const rowDroit = document.getElementById("row-droit");
  if (rowDroit) rowDroit.innerHTML = droitIds.map(id => cardHtml(byId(id))).join("");

  // Build "Ma Liste" + reflect membership on all + buttons
  renderMyList();
  syncAddButtons();

  // Nav scroll behavior
  const nav = document.querySelector(".nav");
  const onScroll = () => {
    if (window.scrollY > 50) nav.classList.add("scrolled");
    else nav.classList.remove("scrolled");
  };
  window.addEventListener("scroll", onScroll, { passive: true });

  // Reveal on scroll
  const io = new IntersectionObserver((entries) => {
    entries.forEach((e) => {
      if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
    });
  }, { threshold: .05, rootMargin: "0px 0px -80px 0px" });
  document.querySelectorAll(".row").forEach(el => { el.classList.add("reveal"); io.observe(el); });

  // Parallax hero background
  const heroBg = document.querySelector(".hero-bg");
  if (heroBg) {
    window.addEventListener("scroll", () => {
      const y = window.scrollY;
      if (y < window.innerHeight) {
        heroBg.style.transform = `translateY(${y * 0.25}px)`;
        heroBg.style.opacity = String(1 - Math.min(1, y / (window.innerHeight * 0.9)));
      }
    }, { passive: true });
  }

  // Hero "Réviser" → launch the cinematic player (Module 11)
  document.querySelectorAll("[data-open-m11]").forEach(b => {
    b.addEventListener("click", (e) => {
      e.preventDefault();
      // The first Réviser button (with id) launches the player, "Plus d'infos" opens the modal
      if (b.id === "hero-revise") {
        window.LennyPlayer && window.LennyPlayer.open("m11");
      } else {
        window.LennyDetail && window.LennyDetail.open("m11");
      }
    });
  });

  // (Le bouton "Quiz général" est câblé par lenny-router.js → LennyQuiz.open)

  // Intercept all card clicks → open detail modal (clicking the play btn in overlay → player)
  document.addEventListener("click", (e) => {
    // Card overlay "+" button → toggle Ma Liste (must run before card/play handlers)
    const addBtn = e.target.closest(".cbtn.add[data-add]");
    if (addBtn) {
      e.preventDefault(); e.stopPropagation();
      const id = addBtn.getAttribute("data-add");
      const added = toggleMyList(id);
      addBtn.classList.add("pop");
      setTimeout(() => addBtn.classList.remove("pop"), 260);
      return;
    }

    // Card overlay video button → launch the video player directly
    const videoBtn = e.target.closest(".card-overlay-actions .cbtn.video[data-video]");
    if (videoBtn) {
      e.preventDefault(); e.stopPropagation();
      const id = videoBtn.getAttribute("data-video");
      if (id && window.LennyVideo && window.LennyVideo.has && window.LennyVideo.has(id)) {
        window.LennyVideo.open(id);
      }
      return;
    }

    // Card overlay play button → launch lesson directly
    const playBtn = e.target.closest(".card-overlay-actions .cbtn.play");
    if (playBtn) {
      const c = playBtn.closest(".card[data-mod]");
      const id = c?.getAttribute("data-mod");
      if (id && LENNY_MODULES.find(m => m.id === id)) {
        e.preventDefault(); e.stopPropagation();
        window.LennyLesson && window.LennyLesson.open(id);
        return;
      }
    }

    const card = e.target.closest(".card[data-mod]");
    if (card) {
      const id = card.getAttribute("data-mod");
      if (id && LENNY_MODULES.find(m => m.id === id)) {
        e.preventDefault();
        window.LennyDetail && window.LennyDetail.open(id);
        return;
      }
    }
    const link = e.target.closest("[data-open-mod]");
    if (link) {
      const id = link.getAttribute("data-open-mod");
      if (id && LENNY_MODULES.find(m => m.id === id)) {
        e.preventDefault();
        window.LennyDetail && window.LennyDetail.open(id);
      }
    }
  });

  // Navigation is owned by lenny-router.js (view switching + active state).
}

// Run init now if DOM is already ready, else wait
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", lennyInit);
} else {
  lennyInit();
}

;
/* ===== lenny-detail.js ===== */
/* ============================================
   LENNY — Module detail overlay (Netflix-style title page)
   Depends on: LENNY_MODULES (lenny-app.js), STUDY (study-data.js),
               MEMOS (memos-data.js), QUIZ (quiz-data.js)
   ============================================ */

(function () {
  const STATE = { modId: null, tab: "fiches", cardIdx: 0, flipped: false, quizIdx: 0, quizAns: null, quizScore: 0, quizDone: false, quizAnswers: [], quizQs: [] };

  // Mélange l'ordre des questions ET des réponses — nouvelle distribution à chaque session
  function shuffleArr(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }
  function prepQuiz(modId) {
    const src = (window.QUIZ || {})[modId] || (window.STUDY || {})[modId]?.quiz || [];
    return shuffleArr(src).map(q => {
      if (!q || !Array.isArray(q.c) || typeof q.r !== "number") return q;
      const order = shuffleArr(q.c.map((_, i) => i));
      return { ...q, c: order.map(i => q.c[i]), r: order.indexOf(q.r) };
    });
  }

  // ===== Build DOM =====
  function ensureModal() {
    if (document.getElementById("ld-modal")) return;
    const modal = document.createElement("div");
    modal.id = "ld-modal";
    modal.className = "ld-modal";
    modal.innerHTML = `
      <div class="ld-backdrop" data-close="1"></div>
      <div class="ld-sheet" role="dialog" aria-modal="true">
        <button class="ld-close" data-close="1" aria-label="Fermer">
          <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round">
            <line x1="4" y1="4" x2="14" y2="14"/><line x1="14" y1="4" x2="4" y2="14"/>
          </svg>
        </button>
        <div class="ld-hero">
          <div class="ld-hero-bg"></div>
          <div class="ld-hero-content">
            <div class="ld-tag"><span class="L">L</span> · ORIGINAL</div>
            <h2 class="ld-title"></h2>
            <div class="ld-stats"></div>
            <div class="ld-quote"></div>
            <p class="ld-desc"></p>
            <div class="ld-actions">
              <button class="ld-btn ld-btn-primary" data-action="start">
                <svg viewBox="0 0 18 18" fill="currentColor"><path d="M4 2 L15 9 L4 16 Z"/></svg>
                Démarrer la fiche
              </button>
              <button class="ld-btn ld-btn-video" data-action="video" hidden>
                <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"><rect x="2.4" y="4" width="13.2" height="10" rx="1.6"/><path d="M7.6 7 L11.4 9 L7.6 11 Z" fill="currentColor" stroke="none"/></svg>
                Voir la vidéo
              </button>
              <button class="ld-btn ld-btn-secondary" data-action="quiz">
                <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M9 2 a7 7 0 1 1 0 14 a7 7 0 0 1 0 -14 Z M9 6.5 v3.5 M9 12.5 v.5" stroke-linecap="round"/></svg>
                Quiz
              </button>
              <button class="ld-btn ld-btn-circle ld-add" data-action="mylist" title="Ajouter à Ma Liste" aria-label="Ajouter à Ma Liste">
                <svg class="ic-plus" viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><line x1="9" y1="3" x2="9" y2="15"/><line x1="3" y1="9" x2="15" y2="9"/></svg>
                <svg class="ic-check" viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><polyline points="3.5,9.5 7.5,13.5 14.5,5.5"/></svg>
              </button>
            </div>
          </div>
        </div>
        <div class="ld-body">
          <div class="ld-tabs" role="tablist">
            <button class="ld-tab active" data-tab="essentiel">Essentiel</button>
            <button class="ld-tab"        data-tab="fiches">Fiches</button>
            <button class="ld-tab"        data-tab="memos">Mémos & Formules</button>
            <button class="ld-tab"        data-tab="quiz">Quiz</button>
            <button class="ld-tab"        data-tab="about">À propos</button>
          </div>
          <div class="ld-panel" data-panel></div>
        </div>
      </div>
    `;
    document.body.appendChild(modal);

    // Bind close
    modal.addEventListener("click", (e) => {
      if (e.target.closest("[data-close]")) close();
    });
    // Bind tabs
    modal.querySelectorAll(".ld-tab").forEach(t => {
      t.addEventListener("click", () => {
        STATE.tab = t.dataset.tab;
        modal.querySelectorAll(".ld-tab").forEach(x => x.classList.toggle("active", x === t));
        renderPanel();
      });
    });
    // Bind hero actions
    modal.querySelector("[data-action='start']").addEventListener("click", () => {
      // Close detail and launch the lesson (continuation — no splash)
      close(true);
      setTimeout(() => {
        window.LennyLesson && window.LennyLesson.open(STATE.modId);
      }, 200);
    });
    modal.querySelector("[data-action='video']").addEventListener("click", () => {
      close(true);
      setTimeout(() => { window.LennyVideo && window.LennyVideo.open(STATE.modId); }, 200);
    });
    modal.querySelector("[data-action='quiz']").addEventListener("click", () => {
      STATE.tab = "quiz"; STATE.quizIdx = 0; STATE.quizAns = null; STATE.quizScore = 0; STATE.quizDone = false; STATE.quizAnswers = []; STATE.quizRecorded = false;
      STATE.quizQs = prepQuiz(STATE.modId);
      modal.querySelectorAll(".ld-tab").forEach(x => x.classList.toggle("active", x.dataset.tab === "quiz"));
      renderPanel();
      document.querySelector(".ld-body").scrollIntoView({ behavior: "smooth" });
    });
    // Ma Liste toggle
    const addBtn = modal.querySelector("[data-action='mylist']");
    if (addBtn) addBtn.addEventListener("click", () => {
      if (!window.LennyList) return;
      window.LennyList.toggle(STATE.modId);
      reflectAddState();
      addBtn.classList.add("pop");
      setTimeout(() => addBtn.classList.remove("pop"), 260);
    });

    // ESC to close
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && modal.classList.contains("open")) close();
    });
  }

  function open(modId) {
    ensureModal();
    STATE.modId = modId;
    STATE.tab = "essentiel";
    STATE.cardIdx = 0; STATE.flipped = false;
    STATE.quizIdx = 0; STATE.quizAns = null; STATE.quizScore = 0; STATE.quizDone = false; STATE.quizAnswers = []; STATE.quizRecorded = false;
    STATE.quizQs = prepQuiz(modId);

    const mod = LENNY_MODULES.find(m => m.id === modId);
    if (!mod) return;

    const modal = document.getElementById("ld-modal");
    modal.classList.add("open");
    document.body.style.overflow = "hidden";

    // Fill hero
    modal.querySelector(".ld-title").textContent = mod.title;
    modal.querySelector(".ld-quote").textContent = mod.quote;
    modal.querySelector(".ld-desc").textContent = mod.desc;
    const heroBg = modal.querySelector(".ld-hero-bg");
    heroBg.className = "ld-hero-bg art-" + mod.color;
    heroBg.style.backgroundImage = "";
    const photoClass = window.modPhotoClass && window.modPhotoClass(modId);
    if (photoClass) {
      heroBg.classList.add("has-photo", photoClass);
    }

    const stats = modal.querySelector(".ld-stats");
    const study = (window.STUDY || {})[modId] || {};
    const quizCount = ((window.QUIZ || {})[modId] || []).length;
    const fcCount = (study.cards || []).length;
    stats.innerHTML = `
      <span class="ld-pill">${mod.season}</span>
      <span class="ld-pill">${mod.time} min</span>
      <span class="ld-pill" style="background:rgba(229,9,20,.18);border-color:rgba(229,9,20,.35);color:#ffb3b6">BTS PI</span>
      <span class="ld-pill">${fcCount} fiches</span>
      <span class="ld-pill">${quizCount} questions</span>
    `;

    // Reset tab UI
    modal.querySelectorAll(".ld-tab").forEach(x => x.classList.toggle("active", x.dataset.tab === "essentiel"));
    // Bouton "Voir la vidéo" — visible seulement si une vidéo est rattachée
    const vbtn = modal.querySelector("[data-action='video']");
    if (vbtn) {
      const meta = window.LENNY_VIDEOS && window.LENNY_VIDEOS[modId];
      vbtn.hidden = !meta;
    }
    reflectAddState();
    renderPanel();
  }

  // Reflect Ma Liste membership on the detail "+" button
  function reflectAddState() {
    const modal = document.getElementById("ld-modal");
    if (!modal) return;
    const btn = modal.querySelector("[data-action='mylist']");
    if (!btn) return;
    const inList = window.LennyList && window.LennyList.has(STATE.modId);
    btn.classList.toggle("added", !!inList);
    const label = inList ? "Retirer de Ma Liste" : "Ajouter à Ma Liste";
    btn.setAttribute("title", label);
    btn.setAttribute("aria-label", label);
  }

  function close(skipSplash) {
    const modal = document.getElementById("ld-modal");
    if (!modal) return;
    modal.classList.remove("open");
    document.body.style.overflow = "";
    if (!skipSplash && window.LennySplash) window.LennySplash(1000);
  }

  function renderPanel() {
    const panel = document.querySelector("[data-panel]");
    if (!panel) return;
    const modId = STATE.modId;
    panel.innerHTML = "";
    if (STATE.tab === "essentiel") panel.appendChild(renderEssentiel(modId));
    if (STATE.tab === "fiches") panel.appendChild(renderFiches(modId));
    if (STATE.tab === "memos")  panel.appendChild(renderMemos(modId));
    if (STATE.tab === "quiz")   panel.appendChild(renderQuiz(modId));
    if (STATE.tab === "about")  panel.appendChild(renderAbout(modId));
  }

  // ===== Essentiel (à-retenir + frise des lois) =====
  function renderEssentiel(modId) {
    const mod = LENNY_MODULES.find(m => m.id === modId) || {};
    const data = (window.ESSENTIALS || {})[modId] || {};
    const retenir = data.retenir || [];
    const timeline = data.timeline || [];
    const study = (window.STUDY || {})[modId] || {};
    const fcCount = (study.cards || []).length;
    const quizCount = ((window.QUIZ || {})[modId] || []).length;
    const memo = (window.MEMOS || []).find(m => m.mod === modId);
    const memoCount = memo ? (memo.cards || []).length : 0;

    const wrap = document.createElement("div");
    wrap.className = "ld-ess";
    wrap.style.setProperty("--ess", "var(--" + (mod.color || "red") + ", var(--red))");

    const numbers = [
      { n: fcCount, l: "fiches" },
      { n: quizCount, l: "questions" },
      { n: memoCount, l: "mémos" },
      { n: mod.time || "—", l: "minutes" },
    ];

    if (!retenir.length && !timeline.length) {
      wrap.innerHTML = `<div class="ld-empty">L'essentiel arrive bientôt pour ce module.</div>`;
      return wrap;
    }

    const icon = (i) => {
      const paths = [
        '<path d="M3 10 L9 4 L15 10" /><path d="M5 9 V15 H13 V9"/>',
        '<circle cx="9" cy="9" r="6"/><path d="M9 5 v4 l3 2"/>',
        '<path d="M4 3 h7 l3 3 v9 H4 Z"/><path d="M6.5 8 h5 M6.5 11 h5"/>',
        '<path d="M3 9 h12 M9 3 v12"/>',
      ];
      return `<svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${paths[i % paths.length]}</svg>`;
    };

    wrap.innerHTML = `
      <div class="ld-ess-numbers">
        ${numbers.map(x => `<div class="ld-ess-num"><span class="v">${x.n}</span><span class="l">${x.l}</span></div>`).join("")}
      </div>
      <div class="ld-ess-section">
        <h3 class="ld-ess-h">À retenir</h3>
        <div class="ld-ess-grid">
          ${retenir.map((r, i) => `
            <div class="ld-ess-card" style="animation-delay:${i * 70}ms">
              <div class="ld-ess-card-ic">${icon(i)}</div>
              <div class="ld-ess-card-body">
                <div class="ld-ess-card-k">${escapeHtml(r.k)}</div>
                <div class="ld-ess-card-v">${escapeHtml(r.v)}</div>
              </div>
            </div>`).join("")}
        </div>
      </div>
      ${timeline.length ? `
      <div class="ld-ess-section">
        <h3 class="ld-ess-h">Frise chronologique des lois</h3>
        <div class="ld-frise">
          ${timeline.map((t, i) => `
            <div class="ld-frise-row" style="animation-delay:${i * 80}ms">
              <div class="ld-frise-year">${escapeHtml(t.y)}</div>
              <div class="ld-frise-track"><span class="ld-frise-dot"></span></div>
              <div class="ld-frise-label">${escapeHtml(t.t)}</div>
            </div>`).join("")}
        </div>
      </div>` : ""}
    `;
    // Avis sur le cours
    if (window.LennyFeedback) {
      const fbSlot = document.createElement("div");
      wrap.appendChild(fbSlot);
      window.LennyFeedback.mount(fbSlot, "course-" + modId, { label: "Ce cours vous a-t-il été utile ?" });
    }
    return wrap;
  }

  // ===== Fiches (flashcards) =====
  function renderFiches(modId) {
    const study = (window.STUDY || {})[modId] || {};
    const cards = study.cards || [];
    const wrap = document.createElement("div");
    wrap.className = "ld-fiches";
    if (!cards.length) {
      wrap.innerHTML = `<div class="ld-empty">Pas encore de fiches pour ce module.</div>`;
      return wrap;
    }
    const cur = cards[STATE.cardIdx];
    wrap.innerHTML = `
      <div class="ld-fiches-head">
        <div class="ld-eyebrow">Épisode ${STATE.cardIdx + 1}/${cards.length}</div>
        <div class="ld-fiches-progress">
          ${cards.map((_, i) => `<i class="${i === STATE.cardIdx ? "on" : (i < STATE.cardIdx ? "done" : "")}"></i>`).join("")}
        </div>
      </div>
      <div class="ld-card ${STATE.flipped ? "flipped" : ""}" data-flip>
        <div class="ld-card-inner">
          <div class="ld-card-face front">
            <div class="ld-card-eyebrow">Question</div>
            <div class="ld-card-text">${escapeHtml(cur.q)}</div>
            <div class="ld-card-hint">Cliquer pour révéler la réponse</div>
          </div>
          <div class="ld-card-face back">
            <div class="ld-card-eyebrow">Réponse</div>
            <div class="ld-card-text">${escapeHtml(cur.a)}</div>
            ${cur.ex ? `<div class="ld-card-ex"><span class="ld-card-ex-tag">Exemple</span>${escapeHtml(cur.ex)}</div>` : ""}
            <div class="ld-card-hint">Cliquer pour revenir à la question</div>
          </div>
        </div>
      </div>
      <div class="ld-fiches-nav">
        <button class="ld-nav-btn" data-nav="prev" ${STATE.cardIdx === 0 ? "disabled" : ""}>
          <svg viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><polyline points="9,2 4,7 9,12"/></svg>
          Précédent
        </button>
        <div class="ld-fiches-actions">
          <button class="ld-nav-btn ghost" data-nav="hard">Je ne savais pas</button>
          <button class="ld-nav-btn ok"   data-nav="easy">Je savais ✓</button>
        </div>
        <button class="ld-nav-btn" data-nav="next" ${STATE.cardIdx === cards.length - 1 ? "disabled" : ""}>
          Suivant
          <svg viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><polyline points="5,2 10,7 5,12"/></svg>
        </button>
      </div>
    `;
    wrap.querySelector("[data-flip]").addEventListener("click", () => { STATE.flipped = !STATE.flipped; renderPanel(); });
    wrap.querySelectorAll("[data-nav]").forEach(b => {
      b.addEventListener("click", (e) => {
        e.stopPropagation();
        const a = b.dataset.nav;
        if (a === "prev" && STATE.cardIdx > 0) { STATE.cardIdx--; STATE.flipped = false; }
        else if ((a === "next" || a === "easy" || a === "hard") && STATE.cardIdx < cards.length - 1) { STATE.cardIdx++; STATE.flipped = false; }
        renderPanel();
      });
    });
    return wrap;
  }

  // ===== Mémos =====
  function renderMemos(modId) {
    const memo = (window.MEMOS || []).find(m => m.mod === modId);
    const wrap = document.createElement("div");
    wrap.className = "ld-memos";
    if (!memo) {
      wrap.innerHTML = `<div class="ld-empty">Pas de mémo pour ce module.</div>`;
      return wrap;
    }
    wrap.innerHTML = memo.cards.map((card, i) => `
      <div class="ld-memo ld-memo-${card.type}" style="animation-delay:${i * 60}ms">
        <div class="ld-memo-type">${card.type}</div>
        <h4 class="ld-memo-h">${escapeHtml(card.h)}</h4>
        <ul class="ld-memo-list">
          ${card.items.map(it => `<li>${escapeHtml(it)}</li>`).join("")}
        </ul>
      </div>
    `).join("");
    return wrap;
  }

  // ===== Quiz =====
  function renderQuiz(modId) {
    let qs = STATE.quizQs;
    if (!qs || !qs.length) { qs = STATE.quizQs = prepQuiz(modId); }
    const wrap = document.createElement("div");
    wrap.className = "ld-quiz";
    if (!qs.length) {
      wrap.innerHTML = `<div class="ld-empty">Quiz à venir pour ce module.</div>`;
      return wrap;
    }
    if (STATE.quizDone) {
      const correctDone = STATE.quizAnswers.reduce((n, a, i) => n + (a != null && qs[i] && a === qs[i].r ? 1 : 0), 0);
      const pct = Math.round(correctDone / qs.length * 100);
      wrap.innerHTML = `
        <div class="ld-quiz-result">
          <div class="ld-quiz-result-pct ${pct >= 70 ? "ok" : (pct >= 40 ? "mid" : "bad")}">${pct}%</div>
          <div class="ld-quiz-result-line">${correctDone} / ${qs.length} bonnes réponses</div>
          <div class="ld-quiz-result-sub">${pct >= 70 ? "Très bien — fiche bien maîtrisée." : pct >= 40 ? "Pas mal — un dernier passage en fiche s'impose." : "Il faut revoir les fiches avant d'enchaîner."}</div>
          <div class="ld-quiz-result-actions">
            <button class="ld-btn ld-btn-primary" data-restart>Recommencer</button>
            <button class="ld-btn ld-btn-secondary" data-goFiches>Revoir les fiches</button>
          </div>
          <div id="ld-quiz-feedback"></div>
        </div>
      `;
      // Historique horodaté (radar) — une seule fois par session terminée
      if (!STATE.quizRecorded && window.LennyAPI) {
        STATE.quizRecorded = true;
        LennyAPI.recordQuizResult({ moduleId: STATE.modId, correct: correctDone, total: qs.length });
      }
      if (window.LennyFeedback) {
        const fs = wrap.querySelector("#ld-quiz-feedback");
        if (fs) window.LennyFeedback.mount(fs, "quiz-" + STATE.modId, { label: "Ce quiz était-il pertinent ?" });
      }
      wrap.querySelector("[data-restart]").addEventListener("click", () => {
        STATE.quizIdx = 0; STATE.quizAns = null; STATE.quizScore = 0; STATE.quizDone = false; STATE.quizAnswers = []; STATE.quizRecorded = false;
        STATE.quizQs = prepQuiz(STATE.modId);
        renderPanel();
      });
      wrap.querySelector("[data-goFiches]").addEventListener("click", () => {
        STATE.tab = "fiches";
        document.querySelectorAll(".ld-tab").forEach(x => x.classList.toggle("active", x.dataset.tab === "fiches"));
        renderPanel();
      });
      return wrap;
    }
    const q = qs[STATE.quizIdx];
    const picked = STATE.quizAnswers[STATE.quizIdx];
    const answered = picked != null;
    const correctSoFar = STATE.quizAnswers.reduce((n, a, i) => n + (a != null && qs[i] && a === qs[i].r ? 1 : 0), 0);
    wrap.innerHTML = `
      <div class="ld-quiz-head">
        <div class="ld-eyebrow">Question ${STATE.quizIdx + 1}/${qs.length}</div>
        <div class="ld-fiches-progress">
          ${qs.map((_, i) => `<i class="${i === STATE.quizIdx ? "on" : (STATE.quizAnswers[i] != null ? "done" : "")}"></i>`).join("")}
        </div>
      </div>
      <div class="ld-quiz-q">${escapeHtml(q.q)}</div>
      <div class="ld-quiz-choices">
        ${q.c.map((ch, i) => {
          let cls = "";
          if (answered) {
            if (i === q.r) cls = "right";
            else if (i === picked) cls = "wrong";
          }
          return `<button class="ld-quiz-choice ${cls}" data-pick="${i}" ${answered ? "disabled" : ""}>
            <span class="ld-quiz-letter">${String.fromCharCode(65 + i)}</span>
            <span class="ld-quiz-text">${escapeHtml(ch)}</span>
          </button>`;
        }).join("")}
      </div>
      ${answered && q.e ? `<div class="ld-quiz-expl">
        <div class="ld-quiz-expl-h">${picked === q.r ? "✓ Exact" : "✗ Pas tout à fait"}</div>
        <div>${escapeHtml(q.e)}</div>
      </div>` : ""}
      <div class="ld-quiz-foot">
        <button class="ld-btn ld-btn-secondary ld-quiz-prev" data-prev ${STATE.quizIdx === 0 ? "disabled" : ""}>← Précédent</button>
        <div class="ld-quiz-score">Score : <strong>${correctSoFar}</strong> / ${qs.length}</div>
        ${answered ? `<button class="ld-btn ld-btn-primary" data-next>${STATE.quizIdx === qs.length - 1 ? "Voir le résultat" : "Question suivante →"}</button>` : `<span class="ld-quiz-foot-spacer"></span>`}
      </div>
    `;
    wrap.querySelectorAll("[data-pick]").forEach(b => {
      b.addEventListener("click", () => {
        if (STATE.quizAnswers[STATE.quizIdx] != null) return;
        const i = parseInt(b.dataset.pick, 10);
        STATE.quizAnswers[STATE.quizIdx] = i;
        renderPanel();
      });
    });
    const prevBtn = wrap.querySelector("[data-prev]");
    if (prevBtn) prevBtn.addEventListener("click", () => {
      if (STATE.quizIdx > 0) { STATE.quizIdx--; renderPanel(); }
    });
    const nextBtn = wrap.querySelector("[data-next]");
    if (nextBtn) nextBtn.addEventListener("click", () => {
      if (STATE.quizIdx === qs.length - 1) { STATE.quizDone = true; }
      else { STATE.quizIdx++; }
      renderPanel();
    });
    return wrap;
  }

  // ===== About =====
  function renderAbout(modId) {
    const mod = LENNY_MODULES.find(m => m.id === modId);
    const wrap = document.createElement("div");
    wrap.className = "ld-about";
    wrap.innerHTML = `
      <div class="ld-about-grid">
        <div class="ld-about-l">
          <h3 style="font-size:18px;margin-bottom:12px">À propos de ${escapeHtml(mod.title)}</h3>
          <p style="color:rgba(255,255,255,.78);line-height:1.6;font-size:14.5px">${escapeHtml(mod.desc)}</p>
          <h3 style="font-size:14px;margin-top:24px;margin-bottom:8px;color:rgba(255,255,255,.55);letter-spacing:.06em;text-transform:uppercase;font-weight:600">Casting</h3>
          <p style="color:rgba(255,255,255,.78);line-height:1.6;font-size:14.5px">
            <strong>Format :</strong> Fiche de révision BTS PI<br>
            <strong>Saison :</strong> ${mod.season}<br>
            <strong>Durée :</strong> ${mod.time} min<br>
            <strong>Difficulté :</strong> ${mod.pct >= 92 ? "Tout public" : mod.pct >= 85 ? "Intermédiaire" : "Confirmé"}
          </p>
        </div>
        <div class="ld-about-r">
          <h3 style="font-size:14px;margin-bottom:12px;color:rgba(255,255,255,.55);letter-spacing:.06em;text-transform:uppercase;font-weight:600">Vous aimerez aussi</h3>
          <div class="ld-similar"></div>
        </div>
      </div>
    `;
    const similar = wrap.querySelector(".ld-similar");
    const others = LENNY_MODULES.filter(m => m.id !== modId).slice(0, 4);
    others.forEach(m => {
      const card = document.createElement("button");
      card.className = "ld-similar-card art-" + m.color;
      card.innerHTML = `
        <div class="ld-similar-meta">
          <span class="ld-similar-tag"><span class="L">L</span> · ORIGINAL</span>
          <span style="font-size:11px;color:rgba(255,255,255,.55);font-family:'IBM Plex Mono',monospace">${m.num}</span>
        </div>
        <div class="ld-similar-title">${escapeHtml(m.title)}</div>
        <div class="ld-similar-foot">
          <span style="font-size:11px;color:rgba(255,255,255,.5)">${m.time} min</span>
        </div>
      `;
      card.addEventListener("click", () => open(m.id));
      similar.appendChild(card);
    });
    return wrap;
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  }

  // Expose
  window.LennyDetail = { open, close };
})();

;
/* ===== lenny-player.js ===== */
/* ============================================
   LENNY — Mini Diaporama (manual slideshow, no timer)
   One slide per deep-dive chapter, rich layout with all sections.
   Depends on: LENNY_MODULES (lenny-app.js), DEEPDIVE (deep-dive-data.js)
   ============================================ */

(function () {
  const COLOR_MAP = {
    m1:   ["#c95636", "#8a3520"],
    m2:   ["#2f5d7a", "#1a3550"],
    m3:   ["#3d6b48", "#1a3d28"],
    m4:   ["#b58430", "#7a5520"],
    m5:   ["#7a3a51", "#4a1f33"],
    m6:   ["#c95636", "#8a3520"],
    m6b:  ["#8a3520", "#4a1a10"],
    m8:   ["#2f5d7a", "#1a3550"],
    m11:  ["#3d6b48", "#2a5a36"],
    mdroit: ["#574a86", "#2e2752"],
    mprop: ["#5a4a7a", "#322648"],
    mdsources: ["#2f5d7a", "#1a3550"],
    mddeonto: ["#7a3a51", "#4a1f33"],
    mdjustice: ["#8a3520", "#4a1a10"],
    mdfamille: ["#c95636", "#8a3520"],
    mdpreuve: ["#b58430", "#7a5520"],
    mdcontrats: ["#3d6b48", "#1a3d28"],
    mvert: ["#3f6b4a", "#1f3d29"],
    murba: ["#3f6585", "#21384d"],
    mville: ["#2f7d72", "#173f39"],
    mperso: ["#3f6b4a", "#1f3d29"],
    msyn: ["#b58430", "#7a5520"]
  };

  const S = { modId: null, mod: null, scenes: [], idx: 0, bingeQueue: [], bingeTimer: null, auto: false, autoTimer: null, speed: 1 };

  // ----- lecture auto + vitesse + plein écran -----
  const SPEED_KEY = "lenny-player-speed";
  const AUTO_SPEEDS = [1, 1.5, 2];
  function restoreSpeed() {
    try { const r = parseFloat(localStorage.getItem(SPEED_KEY)); return AUTO_SPEEDS.includes(r) ? r : 1; } catch (e) { return 1; }
  }
  function reflectSpeed() {
    const tx = document.getElementById("lp-speed-tx");
    if (tx) tx.textContent = S.speed + "\u00d7";
    const btn = document.getElementById("lp-speed");
    if (btn) btn.classList.toggle("active", S.speed !== 1);
  }
  function cycleAutoSpeed() {
    S.speed = AUTO_SPEEDS[(AUTO_SPEEDS.indexOf(S.speed) + 1) % AUTO_SPEEDS.length];
    try { localStorage.setItem(SPEED_KEY, String(S.speed)); } catch (e) {}
    reflectSpeed();
    if (S.auto) scheduleAuto(); // réapplique le rythme immédiatement
  }
  function clearAuto() { if (S.autoTimer) { clearTimeout(S.autoTimer); S.autoTimer = null; } }
  function scheduleAuto() {
    clearAuto();
    if (!S.auto) return;
    // stop net à la dernière diapo
    if (S.idx >= S.scenes.length - 1) { setAuto(false); return; }
    const slot = document.getElementById("lp-scene");
    const len = slot ? (slot.textContent || "").trim().length : 400;
    // temps de lecture estimé, borné, ajusté par la vitesse
    let ms = Math.min(26000, Math.max(5000, 3500 + len * 20)) / S.speed;
    S.autoTimer = setTimeout(() => { if (S.auto) next(); }, ms);
  }
  function setAuto(on) {
    S.auto = !!on;
    const btn = document.getElementById("lp-auto");
    if (btn) btn.classList.toggle("on", S.auto);
    const el = document.getElementById("lp");
    if (el) el.classList.toggle("lp-autoplaying", S.auto);
    if (S.auto) {
      // si on est déjà à la fin, on repart du début
      if (S.idx >= S.scenes.length - 1) { S.idx = 0; renderScene("left"); }
      else scheduleAuto();
    } else {
      clearAuto();
    }
  }
  function reflectFull() {
    const fsEl = document.fullscreenElement || document.webkitFullscreenElement;
    const el = document.getElementById("lp");
    if (el) el.classList.toggle("lp-fs", !!fsEl);
  }
  function toggleFull() {
    const el = document.getElementById("lp");
    if (!el) return;
    const fsEl = document.fullscreenElement || document.webkitFullscreenElement;
    if (fsEl) {
      try { (document.exitFullscreen || document.webkitExitFullscreen).call(document); } catch (e) {}
      return;
    }
    const req = el.requestFullscreen || el.webkitRequestFullscreen;
    if (req) { try { const p = req.call(el); if (p && p.catch) p.catch(() => {}); } catch (e) {} }
  }

  // ----- Build slides -----
  // Pour les modules sans DEEP-DIVE rédigé, on reconstruit des chapitres riches
  // à partir de l'Essentiel (à-retenir + frise), des fiches et des mémos.
  function buildFallbackChapters(modId, mod) {
    const out = [];
    const ess = (window.ESSENTIALS || {})[modId] || {};
    const retenir = ess.retenir || [];
    const timeline = ess.timeline || [];
    const cards = (window.STUDY || {})[modId]?.cards || [];
    const memo = (window.MEMOS || []).find(m => m.mod === modId);

    if (retenir.length) {
      out.push({
        title: "L'essentiel à retenir",
        lede: mod.quote || mod.desc || "Les points clés du module.",
        sections: retenir.map(r => ({ h: r.k, b: r.v })),
        linked: []
      });
    }
    if (timeline.length) {
      out.push({
        title: "Repères & dates clés",
        lede: "La chronologie et les références à mémoriser.",
        sections: timeline.map(t => ({ h: t.y, b: t.t })),
        linked: []
      });
    }
    if (cards.length) {
      out.push({
        title: "Les fiches",
        lede: "Toutes les fiches du module, question par question.",
        sections: cards.map(c => ({ h: c.q, b: c.a })),
        linked: []
      });
    }
    if (memo && memo.cards && memo.cards.length) {
      out.push({
        title: "Mémo express",
        lede: "Formules, sigles et règles d'or à garder en tête.",
        sections: memo.cards.map(c => ({ h: c.h, list: c.items || [] })),
        linked: []
      });
    }
    if (!out.length) {
      out.push({ title: mod.title, lede: mod.desc || "", sections: [], linked: [] });
    }
    return out;
  }

  function buildScenes(modId, mod) {
    // Chapitres = deep-dive rédigé si présent, sinon repli (essentiel + fiches + mémos)
    let chapters = Object.values(window.DEEPDIVE || {}).filter(d => d.mod === modId);
    if (chapters.length === 0) chapters = buildFallbackChapters(modId, mod);

    const scenes = [];
    scenes.push({ type: "cover", mod, dds: chapters });

    chapters.forEach((dd, i) => {
      scenes.push({
        type: "chapter",
        idx: i + 1, total: chapters.length,
        title: dd.title, lede: dd.lede,
        sections: dd.sections || [], linked: dd.linked || []
      });
    });

    scenes.push({ type: "outro", mod, total: chapters.length });
    return scenes;
  }

  // ----- DOM -----
  function build() {
    if (document.getElementById("lp")) return;
    const el = document.createElement("div");
    el.id = "lp";
    el.className = "lp";
    el.innerHTML = `
      <div class="lp-photo" id="lp-photo"></div>
      <div class="lp-bg"></div>
      <div class="lp-particles" id="lp-particles"></div>
      <div class="lp-grain"></div>
      <div class="lp-watermark" id="lp-watermark">€</div>
      <div class="lp-vignette"></div>

      <div class="lp-top">
        <button class="lp-close" id="lp-close" title="Quitter (Échap)">
          <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><line x1="4" y1="4" x2="14" y2="14"/><line x1="14" y1="4" x2="4" y2="14"/></svg>
        </button>
        <div class="lp-binge-badge" id="lp-binge-badge" title="Marathon en cours">
          <svg viewBox="0 0 12 12" fill="currentColor"><path d="M6.5 1 L3 7 H5.5 L4.5 11 L8.5 5 H6 L6.5 1 Z"/></svg>
          BINGE
        </div>
        <div class="lp-progress" id="lp-progress"></div>
        <div class="lp-counter">
          <div class="lp-counter-num" id="lp-counter-num"><span>01</span></div>
          <div class="lp-counter-total" id="lp-counter-total">/ 10</div>
        </div>
        <div class="lp-tools">
          <button class="lp-tool" id="lp-auto" title="Lecture auto (P)" aria-label="Lecture automatique">
            <svg class="ic-play" viewBox="0 0 18 18" fill="currentColor"><path d="M5 3 L15 9 L5 15 Z"/></svg>
            <svg class="ic-pause" viewBox="0 0 18 18" fill="currentColor"><rect x="4" y="3" width="3.4" height="12" rx="1"/><rect x="10.6" y="3" width="3.4" height="12" rx="1"/></svg>
          </button>
          <button class="lp-tool lp-tool-speed" id="lp-speed" title="Vitesse de défilement" aria-label="Vitesse de défilement"><span id="lp-speed-tx">1×</span></button>
          <button class="lp-tool" id="lp-full" title="Plein écran (F)" aria-label="Plein écran">
            <svg class="ic-fs" viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><polyline points="3,6.5 3,3 6.5,3"/><polyline points="11.5,3 15,3 15,6.5"/><polyline points="15,11.5 15,15 11.5,15"/><polyline points="6.5,15 3,15 3,11.5"/></svg>
            <svg class="ic-fs-exit" viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><polyline points="6.5,3 6.5,6.5 3,6.5"/><polyline points="15,6.5 11.5,6.5 11.5,3"/><polyline points="11.5,15 11.5,11.5 15,11.5"/><polyline points="3,11.5 6.5,11.5 6.5,15"/></svg>
          </button>
        </div>
      </div>

      <div class="lp-stage">
        <div class="lp-eyebrow" id="lp-eyebrow">
          <span class="L">L</span> · FICHE DE RÉVISION
          <span class="dot"></span>
          <span id="lp-modlabel">Module · …</span>
        </div>
        <div class="lp-scene" id="lp-scene"></div>
      </div>

      <button class="lp-nav lp-nav-prev" id="lp-prev" aria-label="Précédent">
        <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="11,3 5,9 11,15"/></svg>
      </button>
      <button class="lp-nav lp-nav-next" id="lp-next" aria-label="Suivant">
        <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="7,3 13,9 7,15"/></svg>
      </button>

      <div class="lp-bottom">
        <div class="lp-module">
          <div class="lp-module-tag" id="lp-tag">Diapo 01</div>
          <div class="lp-module-title" id="lp-title">…</div>
        </div>
        <div class="lp-hint">
          <span class="lp-key">←</span><span class="lp-key">→</span> naviguer
          <span class="dot"></span>
          <span class="lp-key">Échap</span> quitter
        </div>
      </div>
    `;
    document.body.appendChild(el);

    document.getElementById("lp-close").addEventListener("click", close);
    document.getElementById("lp-prev").addEventListener("click", prev);
    document.getElementById("lp-next").addEventListener("click", next);
    document.getElementById("lp-auto").addEventListener("click", () => setAuto(!S.auto));
    document.getElementById("lp-speed").addEventListener("click", cycleAutoSpeed);
    document.getElementById("lp-full").addEventListener("click", toggleFull);
    document.addEventListener("fullscreenchange", reflectFull);
    document.addEventListener("webkitfullscreenchange", reflectFull);

    document.addEventListener("keydown", (e) => {
      if (!el.classList.contains("open")) return;
      if (e.key === "Escape") { e.preventDefault(); close(); }
      else if (e.key === "ArrowRight" || e.key === " " || e.key === "PageDown") { e.preventDefault(); next(); }
      else if (e.key === "ArrowLeft" || e.key === "PageUp") { e.preventDefault(); prev(); }
      else if (e.key === "Home") { e.preventDefault(); S.idx = 0; renderScene("left"); }
      else if (e.key === "End") { e.preventDefault(); S.idx = S.scenes.length - 1; renderScene("right"); }
      else if (e.key === "f" || e.key === "F") { e.preventDefault(); toggleFull(); }
      else if (e.key === "p" || e.key === "P") { e.preventDefault(); setAuto(!S.auto); }
    });

    // Particles
    const pc = document.getElementById("lp-particles");
    for (let i = 0; i < 22; i++) {
      const p = document.createElement("div");
      p.className = "lp-particle" + (i % 4 === 0 ? " lg" : "");
      p.style.left = (Math.random() * 100) + "%";
      p.style.bottom = (-10 - Math.random() * 50) + "px";
      p.style.setProperty("--d", (16 + Math.random() * 18) + "s");
      p.style.setProperty("--mx", (Math.random() * 80 - 40) + "px");
      p.style.setProperty("--o", (.25 + Math.random() * .5));
      p.style.animationDelay = (-Math.random() * 18) + "s";
      pc.appendChild(p);
    }
  }

  // ----- helpers -----
  function pad(n) { return String(n).padStart(2, "0"); }
  function escapeHtml(s) { return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c])); }
  function bumpCounter() {
    document.getElementById("lp-counter-num").innerHTML = `<span>${pad(S.idx + 1)}</span>`;
  }

  // ----- open/close -----
  function open(modId, opts = {}) {
    build();
    const mod = LENNY_MODULES.find(m => m.id === modId);
    if (!mod) return;
    const scenes = buildScenes(modId, mod);
    if (scenes.length <= 2) {
      // No content for this module — skip ahead if in binge mode
      if (S.bingeQueue && S.bingeQueue.length) {
        const nextId = S.bingeQueue.shift();
        return open(nextId, { bingeContinue: true });
      }
      alert("Pas encore de cours rédigé pour ce module.");
      return;
    }
    if (!opts.bingeContinue) {
      // Fresh open — wipe binge unless caller set it
      if (opts.bingeQueue) S.bingeQueue = [...opts.bingeQueue];
      else S.bingeQueue = [];
    }
    if (S.bingeTimer) { clearTimeout(S.bingeTimer); S.bingeTimer = null; }
    S.modId = modId; S.mod = mod; S.scenes = scenes; S.idx = 0;

    const [c1, c2] = COLOR_MAP[modId] || ["#3d6b48", "#2a5a36"];
    document.documentElement.style.setProperty("--lp-glow", c1);
    document.documentElement.style.setProperty("--lp-glow-2", c2);

    // Blurred module photo behind the glow
    const lpPhoto = document.getElementById("lp-photo");
    if (lpPhoto) {
      const photoClass = window.modPhotoClass && window.modPhotoClass(modId);
      lpPhoto.className = "lp-photo" + (photoClass ? " on " + photoClass : "");
    }

    document.getElementById("lp-modlabel").textContent = `${mod.tag} · ${mod.short}`;
    document.getElementById("lp-counter-total").textContent = `/ ${pad(scenes.length)}`;
    document.getElementById("lp-watermark").textContent = mod.symbol || "·";

    // Binge badge
    const bingeBadge = document.getElementById("lp-binge-badge");
    if (bingeBadge) bingeBadge.classList.toggle("on", S.bingeQueue.length > 0);

    // progress segments — clickable for jump
    const prog = document.getElementById("lp-progress");
    prog.innerHTML = scenes.map((_, i) => `<i class="lp-seg" data-jump="${i}" title="Diapo ${i + 1}"></i>`).join("");
    prog.querySelectorAll(".lp-seg").forEach(s => {
      s.addEventListener("click", () => {
        const j = parseInt(s.dataset.jump, 10);
        const dir = j > S.idx ? "right" : "left";
        S.idx = j; renderScene(dir);
      });
    });

    document.getElementById("lp").classList.add("open");
    document.body.style.overflow = "hidden";
    S.speed = restoreSpeed(); reflectSpeed();
    setAuto(false);
    renderScene("right");
  }

  function openBinge(queue) {
    const q = [...queue];
    const first = q.shift();
    open(first, { bingeQueue: q });
  }

  function close(skipSplash = false) {
    if (S.bingeTimer) { clearTimeout(S.bingeTimer); S.bingeTimer = null; }
    clearAuto(); S.auto = false;
    const fsEl = document.fullscreenElement || document.webkitFullscreenElement;
    if (fsEl) { try { (document.exitFullscreen || document.webkitExitFullscreen).call(document); } catch (e) {} }
    S.bingeQueue = [];
    const el = document.getElementById("lp");
    if (el) el.classList.remove("open", "lp-autoplaying");
    document.body.style.overflow = "";
    if (!skipSplash && window.LennySplash) window.LennySplash(1100);
  }

  // ----- render -----
  function renderScene(direction = "right") {
    const scene = S.scenes[S.idx];
    if (!scene) return;

    const slot = document.getElementById("lp-scene");
    slot.classList.remove("enter-from-right", "enter-from-left");
    void slot.offsetWidth;
    slot.classList.add(direction === "right" ? "enter-from-right" : "enter-from-left");
    slot.setAttribute("data-type", scene.type);
    slot.scrollTop = 0;

    let html = "";
    if (scene.type === "cover") {
      const m = scene.mod;
      html = `
        <div class="lp-cover">
          <div class="lp-cover-l">
            <div class="lp-chapter-eye"><span class="L">L</span> · ORIGINAL · ${escapeHtml(m.tag)}</div>
            <h1 class="lp-h-xl">${escapeHtml(m.title)}</h1>
            <div class="lp-lede">${escapeHtml(m.quote || m.desc)}</div>
            <div class="lp-cover-meta">
              <div class="lp-meta-pill"><strong>${scene.dds.length}</strong> chapitres</div>
              <div class="lp-meta-pill"><strong>${m.time}</strong> min</div>
              <div class="lp-meta-pill lp-meta-red">BTS PI · ${escapeHtml(m.season)}</div>
            </div>
          </div>
          <div class="lp-cover-r">
            <div class="lp-toc-eye">Sommaire</div>
            <ol class="lp-toc">
              ${scene.dds.map((dd, i) => `
                <li class="lp-toc-item" data-jump="${i + 1}" style="animation-delay:${300 + i * 80}ms">
                  <span class="lp-toc-num">${pad(i + 1)}</span>
                  <span class="lp-toc-body">
                    <span class="lp-toc-title">${escapeHtml(dd.title)}</span>
                    <span class="lp-toc-lede">${escapeHtml(dd.lede)}</span>
                  </span>
                  <span class="lp-toc-arrow">→</span>
                </li>
              `).join("")}
            </ol>
          </div>
        </div>
      `;
    } else if (scene.type === "chapter") {
      const useGrid = scene.sections.length >= 4;
      html = `
        <div class="lp-chap">
          <aside class="lp-chap-l">
            <div class="lp-lede">${escapeHtml(scene.lede || "")}</div>

            ${scene.linked.length ? `
              <div class="lp-chap-links">
                <div class="lp-chap-links-h">Concepts liés</div>
                <div class="lp-chap-pills">
                  ${scene.linked.map(slug => {
                    const lk = (window.DEEPDIVE || {})[slug];
                    return lk ? `<button class="lp-pill" data-jump-slug="${escapeHtml(slug)}">${escapeHtml(lk.title)}</button>` : "";
                  }).join("")}
                </div>
              </div>
            ` : ""}

            <div class="lp-chap-tip">
              <span class="lp-tip-mark">★</span>
              <span>${escapeHtml(quickTip(scene))}</span>
            </div>
          </aside>

          <main class="lp-chap-r${useGrid ? " cols-2" : ""}">
            ${scene.sections.map((sec, i) => {
              const isList = sec.list && sec.list.length;
              return `
              <section class="lp-sec${isList ? " wide" : ""}" style="animation-delay:${180 + i * 90}ms">
                <h3 class="lp-sec-h">
                  <span class="lp-sec-i">${pad(i + 1)}</span>
                  ${escapeHtml(sec.h)}
                </h3>
                ${sec.b ? `<p class="lp-sec-b">${escapeHtml(sec.b)}</p>` : ""}
                ${isList ? `
                  <ul class="lp-sec-list">
                    ${sec.list.map(it => `<li>${escapeHtml(it)}</li>`).join("")}
                  </ul>
                ` : ""}
              </section>
            `;}).join("")}
          </main>
        </div>
      `;
    } else if (scene.type === "outro") {
      const m = scene.mod;
      const nextId = S.bingeQueue[0];
      const nextMod = nextId ? LENNY_MODULES.find(m => m.id === nextId) : null;
      html = `
        <div class="lp-outro-inner">
          <div class="lp-outro-mark" aria-label="LENNY">
            <span class="brand-letter">L</span><span class="brand-letter">E</span><span class="brand-letter">N</span><span class="brand-letter">N</span><span class="brand-letter">Y</span>
          </div>
          <div class="lp-chapter-eye"><span class="L">L</span> · ORIGINAL · ${escapeHtml(m.tag)}</div>
          <h1 class="lp-h-xl">Fin du diaporama</h1>
          <div class="lp-lede">${escapeHtml(m.title)} — ${scene.total} chapitre${scene.total > 1 ? "s" : ""} parcouru${scene.total > 1 ? "s" : ""}.</div>
          <div class="lp-outro-stats">
            <div class="lp-finale-stat"><div class="lp-finale-stat-v">${m.time}<small>min</small></div><div class="lp-finale-stat-k">Durée</div></div>
            <div class="lp-finale-stat"><div class="lp-finale-stat-v">${scene.total}</div><div class="lp-finale-stat-k">Chapitres</div></div>
          </div>

          ${nextMod ? `
            <div class="lp-upnext">
              <div class="lp-upnext-eye">À suivre dans <span id="lp-upnext-c">5</span>s</div>
              <div class="lp-upnext-card art-${nextMod.color}">
                <div class="lp-upnext-meta">
                  <span class="lp-upnext-tag"><span class="L">L</span> · ORIGINAL · ${escapeHtml(nextMod.tag)}</span>
                  <span class="lp-upnext-pct">${nextMod.time} min</span>
                </div>
                <div class="lp-upnext-title">${escapeHtml(nextMod.title)}</div>
                <div class="lp-upnext-desc">${escapeHtml(nextMod.desc)}</div>
                <div class="lp-upnext-actions">
                  <button class="ld-btn ld-btn-primary" id="lp-binge-next">▸ Lancer maintenant</button>
                  <button class="ld-btn ld-btn-secondary" id="lp-binge-cancel">Arrêter le binge</button>
                </div>
              </div>
            </div>
          ` : `
            <div class="lp-outro-actions">
              <button class="ld-btn ld-btn-primary"   id="lp-restart">↻ Rejouer</button>
              <button class="ld-btn ld-btn-secondary" id="lp-detail">Voir la fiche</button>
              <button class="ld-btn ld-btn-secondary" id="lp-quiz">Quiz du module</button>
              <button class="ld-btn ld-btn-secondary" id="lp-close-2">Retour</button>
            </div>
          `}
        </div>
      `;
    }
    slot.innerHTML = html;

    // Hookup ToC jump
    slot.querySelectorAll("[data-jump]").forEach(li => {
      li.addEventListener("click", () => {
        const j = parseInt(li.dataset.jump, 10);
        if (!isNaN(j)) { S.idx = j; renderScene("right"); }
      });
    });
    slot.querySelectorAll("[data-jump-slug]").forEach(b => {
      b.addEventListener("click", () => {
        const slug = b.dataset.jumpSlug;
        const i = S.scenes.findIndex(sc => sc.type === "chapter" && sc.title === (window.DEEPDIVE || {})[slug]?.title);
        if (i >= 0) { const dir = i > S.idx ? "right" : "left"; S.idx = i; renderScene(dir); }
      });
    });

    // Outro buttons
    const restart = document.getElementById("lp-restart");
    if (restart) restart.addEventListener("click", () => { S.idx = 0; renderScene("left"); });
    const detail = document.getElementById("lp-detail");
    if (detail) detail.addEventListener("click", () => { close(true); setTimeout(() => window.LennyDetail.open(S.modId), 250); });
    const quiz = document.getElementById("lp-quiz");
    if (quiz) quiz.addEventListener("click", () => {
      close(true);
      setTimeout(() => {
        window.LennyDetail.open(S.modId);
        setTimeout(() => document.querySelector(".ld-tab[data-tab='quiz']")?.click(), 350);
      }, 250);
    });
    const close2 = document.getElementById("lp-close-2");
    if (close2) close2.addEventListener("click", close);

    // Binge "next" wiring
    const bingeNext = document.getElementById("lp-binge-next");
    if (bingeNext) bingeNext.addEventListener("click", () => {
      if (S.bingeTimer) { clearTimeout(S.bingeTimer); S.bingeTimer = null; }
      const nextId = S.bingeQueue.shift();
      if (nextId) open(nextId, { bingeContinue: true });
    });
    const bingeCancel = document.getElementById("lp-binge-cancel");
    if (bingeCancel) bingeCancel.addEventListener("click", () => {
      if (S.bingeTimer) { clearTimeout(S.bingeTimer); S.bingeTimer = null; }
      S.bingeQueue = [];
      close();
    });

    // Auto-countdown for binge
    if (scene.type === "outro" && S.bingeQueue.length) {
      let n = 5;
      const c = document.getElementById("lp-upnext-c");
      const tick = () => {
        n--;
        if (c) c.textContent = String(n);
        if (n <= 0) {
          if (S.bingeTimer) { clearTimeout(S.bingeTimer); S.bingeTimer = null; }
          const nextId = S.bingeQueue.shift();
          if (nextId) open(nextId, { bingeContinue: true });
        } else {
          S.bingeTimer = setTimeout(tick, 1000);
        }
      };
      S.bingeTimer = setTimeout(tick, 1000);
    }

    // Bottom bar — chapter in progress only
    const tagEl = document.getElementById("lp-tag");
    const titleEl = document.getElementById("lp-title");
    if (scene.type === "cover") {
      tagEl.textContent = `Ouverture · Sommaire`;
      titleEl.textContent = "";
    } else if (scene.type === "outro") {
      tagEl.textContent = `Générique`;
      titleEl.textContent = "";
    } else {
      tagEl.textContent = `Chapitre ${pad(scene.idx)} · ${pad(scene.total)}`;
      titleEl.textContent = scene.title || "";
    }

    // progress segments
    document.querySelectorAll("#lp-progress .lp-seg").forEach((s, i) => {
      s.classList.toggle("done", i < S.idx);
      s.classList.toggle("on", i === S.idx);
      s.style.setProperty("--p", i === S.idx ? "100%" : (i < S.idx ? "100%" : "0%"));
    });
    bumpCounter();

    // Nav buttons enable/disable
    document.getElementById("lp-prev").disabled = (S.idx === 0);
    document.getElementById("lp-next").disabled = (S.idx === S.scenes.length - 1);

    // relance le minuteur de lecture auto sur la nouvelle diapo
    if (S.auto) scheduleAuto();
  }

  function quickTip(scene) {
    // Pull a punchy summary from the first list item or the first body
    for (const sec of scene.sections || []) {
      if (sec.list && sec.list.length) return sec.list[0];
      if (sec.b) {
        const s = sec.b.split(/[.!?]/)[0];
        if (s.length < 140) return s.trim() + ".";
      }
    }
    return "Lis chaque section, retiens le titre.";
  }

  function next() { if (S.idx < S.scenes.length - 1) { S.idx++; renderScene("right"); } }
  function prev() { if (S.idx > 0) { S.idx--; renderScene("left"); } }

  window.LennyPlayer = { open, openBinge, close };
})();

;
/* ===== lenny-lesson.js ===== */
/* ============================================
   LENNY — Leçon (remplace le diaporama derrière « Démarrer la fiche »)
   Depends on: LENNY_MODULES (lenny-app.js), DEEPDIVE (deep-dive-data.js + lenny-*-deepdive-*.js)
   Rendu générique : une carte par entrée DEEPDIVE du module, dans l'ordre réel de déclaration.
   ============================================ */
(function () {
  const NUM_RE = /^(\d+)\s*(%|an|ans|jours?|€)\b\s*(.*)$/;
  const STATE = { modId: null, cards: [], slugIndex: {} };

  function escapeHtml(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  }

  function build() {
    if (document.getElementById("ll-modal")) return;
    const modal = document.createElement("div");
    modal.id = "ll-modal";
    modal.innerHTML = `
      <div class="ll-topbar">
        <button class="ll-exit" data-close aria-label="Fermer">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M6 6l12 12M18 6L6 18"/></svg>
        </button>
        <div class="ll-progress-track" id="ll-progress-track"><div class="ll-progress-fill" id="ll-progress-fill"></div></div>
        <div class="ll-mark" id="ll-mark">—</div>
      </div>
      <header class="ll-doc-header" id="ll-doc-header"></header>
      <main class="ll-lesson" id="ll-lesson"></main>
      <footer class="ll-lesson-end" id="ll-lesson-end" style="display:none">
        <p id="ll-end-line"></p>
        <button class="ll-btn-solid" data-close>Fermer<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
      </footer>
    `;
    document.body.appendChild(modal);
    modal.addEventListener("click", (e) => { if (e.target.closest("[data-close]")) close(); });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && modal.classList.contains("open")) close();
    });
  }

  function open(modId) {
    build();
    const modal = document.getElementById("ll-modal");
    const mod = (window.LENNY_MODULES || []).find(m => m.id === modId);
    const allDD = window.DEEPDIVE || {};
    const slugs = Object.keys(allDD).filter(k => allDD[k].mod === modId);

    if (!mod || !slugs.length) {
      alert("Pas encore de cours rédigé pour ce module.");
      return;
    }

    STATE.modId = modId;
    STATE.cards = slugs.map(slug => Object.assign({ slug }, allDD[slug]));
    STATE.slugIndex = {};
    STATE.cards.forEach((c, i) => { STATE.slugIndex[c.slug] = i; });

    const colorValue = /^#/.test(mod.color) ? mod.color : "var(--" + mod.color + ")";
    modal.style.setProperty("--mod", colorValue);

    document.getElementById("ll-doc-header").innerHTML =
      '<div class="ll-doc-id">' + escapeHtml(mod.tag) + ' · ' + escapeHtml(mod.short) + '</div>' +
      '<h1 class="ll-doc-title">' + escapeHtml(mod.title) + '</h1>' +
      '<p class="ll-doc-dek" id="ll-doc-dek"></p>' +
      '<div class="ll-doc-meta" id="ll-doc-meta"></div>';

    const n = STATE.cards.length;
    document.getElementById("ll-doc-dek").textContent = n + (n > 1 ? " notions clés à traverser." : " notion clé à traverser.");

    const lesson = document.getElementById("ll-lesson");
    let html = "";
    STATE.cards.forEach((card, i) => {
      const num = i + 1;
      const numStr = num < 10 ? "0" + num : "" + num;
      const linkedChips = (card.linked || [])
        .filter(slug => STATE.slugIndex.hasOwnProperty(slug))
        .map(slug => '<button class="ll-pill" data-jump="' + escapeHtml(slug) + '">' + escapeHtml(allDD[slug].title) + '</button>')
        .join("");

      html += '<section class="ll-chapter" id="ll-card-' + i + '" data-index="' + i + '"><span class="ll-chapnum">' + numStr + '</span>' +
        '<div class="ll-chapter-inner">' +
        '<div class="ll-chap-id">Fiche ' + numStr + ' / ' + n + '</div>' +
        '<h2 class="ll-chap-title">' + escapeHtml(card.title) + '</h2>' +
        (card.lede ? '<p class="ll-chap-lede">' + escapeHtml(card.lede) + '</p>' : '') +
        (linkedChips ? '<div class="ll-chap-links"><div class="ll-chap-links-h">Concepts liés</div>' + linkedChips + '</div>' : '') +
        '<div class="ll-items">';

      (card.sections || []).forEach(sec => {
        html += '<div class="ll-item"><div class="ll-item-label"><span class="ll-dot"></span>' + escapeHtml(sec.h) + '</div>';
        if (sec.b) html += '<p class="ll-item-body">' + escapeHtml(sec.b) + '</p>';
        if (sec.list && sec.list.length) {
          const parsed = sec.list.map(li => NUM_RE.exec(li));
          const allNumeric = parsed.every(m => m);
          if (allNumeric) {
            html += '<div class="ll-stat-grid">';
            parsed.forEach(m => {
              html += '<div class="ll-stat-badge"><span class="sv"><span class="num" data-target="' + escapeHtml(m[1]) + '">0</span> ' + escapeHtml(m[2]) + '</span>' +
                '<span class="sc">' + escapeHtml(m[3] || "") + '</span></div>';
            });
            html += '</div>';
          } else {
            html += '<ul class="ll-plain-list">' + sec.list.map(li => '<li>' + escapeHtml(li) + '</li>').join("") + '</ul>';
          }
        }
        html += '</div>';
      });

      html += '</div></div></section>';
    });
    lesson.innerHTML = html;

    document.getElementById("ll-lesson-end").style.display = "block";
    document.getElementById("ll-end-line").textContent = "Fin — " + mod.title + ", " + n + (n > 1 ? " fiches traversées." : " fiche traversée.");

    // temps de lecture réel, sur le texte effectivement rendu
    const words = lesson.querySelectorAll(".ll-item-body, .ll-plain-list li, .ll-chap-lede, .ll-doc-dek");
    let count = 0;
    words.forEach(el => { count += el.textContent.trim().split(/\s+/).filter(Boolean).length; });
    const minutes = Math.max(1, Math.round(count / 200));
    document.getElementById("ll-doc-meta").textContent = n + (n > 1 ? " fiches" : " fiche") + " · lecture ≈ " + minutes + " min";

    // liens "concepts liés" — ancre + scroll dans le même module
    lesson.querySelectorAll("[data-jump]").forEach(btn => {
      btn.addEventListener("click", () => {
        const idx = STATE.slugIndex[btn.getAttribute("data-jump")];
        const target = document.getElementById("ll-card-" + idx);
        if (target) target.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });

    // barre de progression segmentée — s'adapte au nombre réel de fiches, scroll interne au modal
    const track = document.getElementById("ll-progress-track");
    const fill = document.getElementById("ll-progress-fill");
    const mark = document.getElementById("ll-mark");
    const chapters = Array.prototype.slice.call(lesson.querySelectorAll(".ll-chapter"));
    let segPcts = [];

    function layoutSegments() {
      const max = modal.scrollHeight - modal.clientHeight;
      track.querySelectorAll(".ll-progress-seg").forEach(s => s.remove());
      segPcts = chapters.map(ch => max > 0 ? (ch.offsetTop / max) * 100 : 0);
      segPcts.slice(1).forEach(pct => {
        const seg = document.createElement("div");
        seg.className = "ll-progress-seg";
        seg.style.left = pct + "%";
        track.appendChild(seg);
      });
    }
    let ticking = false;
    function updateProgress() {
      const max = modal.scrollHeight - modal.clientHeight;
      const pct = max > 0 ? (modal.scrollTop / max) * 100 : 0;
      fill.style.width = pct + "%";
      let current = 1;
      segPcts.forEach((segPct, i) => { if (pct >= segPct - 0.5) current = i + 1; });
      mark.textContent = current + "/" + chapters.length;
      ticking = false;
    }
    modal.onscroll = function () {
      if (!ticking) { window.requestAnimationFrame(updateProgress); ticking = true; }
    };
    window.addEventListener("resize", function () { if (modal.classList.contains("open")) { layoutSegments(); updateProgress(); } });

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const items = lesson.querySelectorAll(".ll-item");
    if (reducedMotion) {
      items.forEach(el => el.classList.add("in"));
    } else {
      const cardIO = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) { entry.target.classList.add("in"); cardIO.unobserve(entry.target); }
        });
      }, { root: modal, threshold: .15, rootMargin: "0px 0px -8% 0px" });
      items.forEach(el => cardIO.observe(el));
    }

    function countUp(numEl) {
      const target = parseFloat(numEl.getAttribute("data-target"));
      if (reducedMotion || isNaN(target)) { numEl.textContent = target; return; }
      const duration = 700; let start = null;
      const ease = t => 1 - Math.pow(1 - t, 3);
      function step(ts) {
        if (start === null) start = ts;
        const p = Math.min(1, (ts - start) / duration);
        numEl.textContent = Math.round(ease(p) * target);
        if (p < 1) window.requestAnimationFrame(step); else numEl.textContent = target;
      }
      window.requestAnimationFrame(step);
    }
    const numIO = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) { countUp(entry.target); numIO.unobserve(entry.target); }
      });
    }, { root: modal, threshold: .4 });
    lesson.querySelectorAll(".num").forEach(el => numIO.observe(el));

    modal.scrollTop = 0;
    modal.classList.add("open");
    document.body.style.overflow = "hidden";
    layoutSegments();
    updateProgress();
  }

  function close() {
    const modal = document.getElementById("ll-modal");
    if (!modal) return;
    modal.classList.remove("open");
    document.body.style.overflow = "";
    if (window.LennySplash) window.LennySplash(1000);
  }

  window.LennyLesson = { open, close };
})();

;
/* ===== lenny-search.js ===== */
/* ============================================
   LENNY — Search overlay
   ============================================ */

(function () {
  const S = { open: false, query: "" };

  function buildIndex() {
    const items = [];
    // Modules
    LENNY_MODULES.forEach(m => {
      items.push({
        kind: "module",
        id: m.id, modId: m.id,
        title: m.title,
        sub: `${m.tag} · ${m.short} · ${m.time} min`,
        color: m.color,
        haystack: [m.title, m.short, m.tag, m.desc, m.quote].filter(Boolean).join(" ").toLowerCase()
      });
    });
    // Chapters (deep-dives)
    Object.entries(window.DEEPDIVE || {}).forEach(([slug, dd]) => {
      const m = LENNY_MODULES.find(x => x.id === dd.mod);
      items.push({
        kind: "chapter",
        id: slug, modId: dd.mod,
        title: dd.title,
        sub: `${m ? m.tag : ""} · Chapitre`,
        color: m ? m.color : "m11",
        lede: dd.lede,
        haystack: [dd.title, dd.lede].filter(Boolean).join(" ").toLowerCase()
      });
    });
    // Search index entries (concepts)
    (window.SEARCH_INDEX || []).forEach(entry => {
      const m = LENNY_MODULES.find(x => x.id === entry.mod);
      items.push({
        kind: "concept",
        id: entry.t, modId: entry.mod,
        title: entry.t,
        sub: `${m ? m.tag : ""} · ${entry.kind}`,
        color: m ? m.color : "m11",
        haystack: [entry.t, entry.kind].filter(Boolean).join(" ").toLowerCase()
      });
    });
    return items;
  }

  let INDEX = null;
  function getIndex() {
    if (!INDEX) INDEX = buildIndex();
    return INDEX;
  }

  function build() {
    if (document.getElementById("ls-modal")) return;
    const el = document.createElement("div");
    el.id = "ls-modal";
    el.className = "ls-modal";
    el.innerHTML = `
      <div class="ls-backdrop" data-close="1"></div>
      <div class="ls-sheet" role="dialog" aria-modal="true">
        <div class="ls-head">
          <svg class="ls-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
            <circle cx="11" cy="11" r="7"/>
            <line x1="16" y1="16" x2="22" y2="22"/>
          </svg>
          <input id="ls-input" class="ls-input" type="text" placeholder="Rechercher un module, un chapitre, une loi, un concept…" autocomplete="off" spellcheck="false" />
          <button class="ls-close" data-close="1" aria-label="Fermer">
            <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><line x1="4" y1="4" x2="14" y2="14"/><line x1="14" y1="4" x2="4" y2="14"/></svg>
          </button>
        </div>
        <div class="ls-meta">
          <span class="ls-meta-key">↑↓</span><span>naviguer</span>
          <span class="ls-meta-dot"></span>
          <span class="ls-meta-key">↵</span><span>ouvrir</span>
          <span class="ls-meta-dot"></span>
          <span class="ls-meta-key">⌘K</span><span>raccourci</span>
          <span class="ls-meta-dot"></span>
          <span class="ls-meta-key">Échap</span><span>fermer</span>
        </div>
        <div class="ls-results" id="ls-results"></div>
      </div>
    `;
    document.body.appendChild(el);

    el.addEventListener("click", (e) => { if (e.target.closest("[data-close]")) close(); });
    const input = document.getElementById("ls-input");
    input.addEventListener("input", () => { S.query = input.value; renderResults(); });
    input.addEventListener("keydown", onInputKey);

    document.addEventListener("keydown", (e) => {
      const isMeta = (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k";
      if (isMeta) { e.preventDefault(); toggle(); return; }
      if (e.key === "/" && !S.open && !e.target.matches("input,textarea")) { e.preventDefault(); open(); return; }
      if (e.key === "Escape" && S.open) { e.preventDefault(); close(); return; }
    });
  }

  function onInputKey(e) {
    const results = [...document.querySelectorAll(".ls-item")];
    const cur = document.querySelector(".ls-item.active");
    const idx = results.indexOf(cur);
    if (e.key === "ArrowDown") {
      e.preventDefault();
      const next = results[Math.min(results.length - 1, idx + 1)];
      if (cur) cur.classList.remove("active");
      if (next) { next.classList.add("active"); next.scrollIntoView({ block: "nearest" }); }
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      const prev = results[Math.max(0, idx - 1)];
      if (cur) cur.classList.remove("active");
      if (prev) { prev.classList.add("active"); prev.scrollIntoView({ block: "nearest" }); }
    } else if (e.key === "Enter") {
      e.preventDefault();
      const target = cur || results[0];
      if (target) pickResult(target);
    }
  }

  function open() {
    build();
    document.getElementById("ls-modal").classList.add("open");
    document.body.style.overflow = "hidden";
    S.open = true;
    setTimeout(() => {
      const inp = document.getElementById("ls-input");
      inp.focus();
      inp.select();
    }, 30);
    renderResults();
  }
  function close() {
    const el = document.getElementById("ls-modal");
    if (!el) return;
    el.classList.remove("open");
    document.body.style.overflow = "";
    S.open = false;
  }
  function toggle() { S.open ? close() : open(); }

  function score(item, q) {
    if (!q) return 0;
    const t = item.title.toLowerCase();
    const h = item.haystack;
    if (t.startsWith(q)) return 100;
    if (t.includes(q))   return 80;
    if (h.includes(q))   return 40;
    return 0;
  }

  function renderResults() {
    const q = S.query.trim().toLowerCase();
    const all = getIndex();
    const results = (q ? all.map(it => ({ it, s: score(it, q) })).filter(x => x.s > 0).sort((a, b) => b.s - a.s).slice(0, 50)
                       : all.filter(it => it.kind === "module").map(it => ({ it, s: 1 })));
    const grouped = { module: [], chapter: [], concept: [] };
    results.forEach(({ it }) => grouped[it.kind]?.push(it));

    const container = document.getElementById("ls-results");
    if (!results.length) {
      container.innerHTML = `
        <div class="ls-empty">
          <div class="ls-empty-h">Aucun résultat pour « ${escapeHtml(S.query)} »</div>
          <div class="ls-empty-sub">Essaye "Hoguet", "DPE", "intérêts composés", "viager", "4×20"…</div>
        </div>
      `;
      return;
    }

    container.innerHTML = `
      ${grouped.module.length ? section("Modules", grouped.module, q) : ""}
      ${grouped.chapter.length ? section("Chapitres", grouped.chapter, q) : ""}
      ${grouped.concept.length ? section("Concepts & Lois", grouped.concept, q) : ""}
    `;
    container.querySelectorAll(".ls-item").forEach((el, i) => {
      if (i === 0) el.classList.add("active");
      el.addEventListener("click", () => pickResult(el));
      el.addEventListener("mouseenter", () => {
        container.querySelectorAll(".ls-item.active").forEach(x => x.classList.remove("active"));
        el.classList.add("active");
      });
    });
  }

  function section(label, items, q) {
    return `
      <div class="ls-section">
        <div class="ls-section-h">${escapeHtml(label)}<span class="ls-section-c">${items.length}</span></div>
        <div class="ls-section-body">
          ${items.map(it => `
            <button class="ls-item" data-kind="${it.kind}" data-mod="${escapeHtml(it.modId)}" data-id="${escapeHtml(it.id)}">
              <span class="ls-thumb art-${it.color}">
                <span class="ls-thumb-L">L</span>
              </span>
              <span class="ls-text">
                <span class="ls-t">${highlight(it.title, q)}</span>
                <span class="ls-s">${highlight(it.sub, q)}${it.lede ? ` · ${escapeHtml(it.lede.slice(0, 80))}${it.lede.length > 80 ? "…" : ""}` : ""}</span>
              </span>
              <span class="ls-go">↵</span>
            </button>
          `).join("")}
        </div>
      </div>
    `;
  }

  function pickResult(el) {
    const kind = el.dataset.kind;
    const modId = el.dataset.mod;
    close();
    setTimeout(() => {
      if (kind === "module") {
        window.LennyDetail && window.LennyDetail.open(modId);
      } else if (kind === "chapter") {
        // open detail; user can hit "Démarrer la fiche"
        window.LennyDetail && window.LennyDetail.open(modId);
      } else if (kind === "concept") {
        window.LennyDetail && window.LennyDetail.open(modId);
      }
    }, 220);
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  }
  function highlight(text, q) {
    if (!q) return escapeHtml(text);
    try {
      const re = new RegExp("(" + q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + ")", "ig");
      return escapeHtml(text).replace(re, "<mark>$1</mark>");
    } catch { return escapeHtml(text); }
  }

  // Bind to nav search icon when DOM ready
  function bindSearch() {
    const navSearch = document.querySelector(".nav .icon-btn[aria-label='Rechercher']");
    if (navSearch) navSearch.addEventListener("click", () => open());
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", bindSearch);
  } else {
    bindSearch();
  }

  window.LennySearch = { open, close, toggle };
})();

;
/* ===== lenny-quiz.js ===== */
/* ============================================
   LENNY — Quiz général
   Agrège TOUTES les questions de tous les modules.
   Se réinitialise à chaque ouverture (état purement en mémoire).
   Depends on: LENNY_MODULES, window.QUIZ, window.STUDY
   ============================================ */
(function () {
  const S = { questions: [], idx: 0, answers: [] };
  const QUIZ_LENGTH = 30; // nombre de questions par session (tirage aléatoire)

  function shuffle(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  // Mélange l'ordre des réponses d'une question et recale l'index de la bonne réponse
  function shuffleOptions(q) {
    if (!q || !Array.isArray(q.c) || typeof q.r !== "number") return q;
    const order = shuffle(q.c.map((_, i) => i));
    return { ...q, c: order.map(i => q.c[i]), r: order.indexOf(q.r) };
  }

  // Build the full pool — every question from every module, no duplicates
  function buildPool() {
    const mods = (typeof LENNY_MODULES !== "undefined") ? LENNY_MODULES : [];
    const pool = [];
    mods.forEach(m => {
      const qs = (window.QUIZ && window.QUIZ[m.id])
        || (window.STUDY && window.STUDY[m.id] && window.STUDY[m.id].quiz)
        || [];
      qs.forEach(q => {
        if (q && Array.isArray(q.c) && typeof q.r === "number") {
          pool.push(shuffleOptions({ q: q.q, c: q.c, r: q.r, e: q.e || "", mod: m }));
        }
      });
    });
    return pool;
  }

  function colorVar(mod) {
    // mod.color is a token name like "m11" / "mdroit"
    return "var(--" + (mod.color || "red") + ", var(--red))";
  }

  function ensureEl() {
    let el = document.getElementById("lenny-quiz");
    if (el) return el;
    el = document.createElement("div");
    el.id = "lenny-quiz";
    el.innerHTML = '<div class="lq-shell" id="lq-shell"></div>';
    document.body.appendChild(el);
    return el;
  }

  function open() {
    // Fresh state every time → resets after each use
    S.questions = shuffle(buildPool()).slice(0, QUIZ_LENGTH);
    S.idx = 0; S.answers = [];
    if (!S.questions.length) { alert("Aucune question disponible."); return; }
    const el = ensureEl();
    el.classList.add("open");
    document.documentElement.style.overflow = "hidden";
    renderQuestion();
  }

  function close() {
    const el = document.getElementById("lenny-quiz");
    if (el) el.classList.remove("open");
    document.documentElement.style.overflow = "";
    // wipe state
    S.questions = []; S.idx = 0; S.answers = [];
  }

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  // Nombre de bonnes réponses parmi les questions déjà répondues
  function correctCount() {
    return S.questions.reduce((n, q, i) => n + (S.answers[i] != null && S.answers[i] === q.r ? 1 : 0), 0);
  }

  function correctionHtml(q, picked) {
    const correct = picked === q.r;
    const L = ["A", "B", "C", "D", "E", "F"];
    const right = `<span class="lq-correction-right">Bonne réponse : <strong>${L[q.r]} — ${esc(q.c[q.r])}</strong></span>`;
    return `
      <div class="lq-correction ${correct ? "good" : "bad"}">
        <div class="lq-correction-h">${correct ? "✓ Bonne réponse" : "✗ Mauvaise réponse"}</div>
        ${correct ? "" : right}
        ${q.e ? `<div class="lq-correction-body">${esc(q.e)}</div>` : ""}
      </div>`;
  }

  function header() {
    const total = S.questions.length;
    const pctDone = Math.round((S.idx / total) * 100);
    return `
      <div class="lq-top">
        <div class="lq-brand">Quiz général · BTS Transaction</div>
        <button class="lq-close" id="lq-close" aria-label="Fermer">
          <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><line x1="4" y1="4" x2="14" y2="14"/><line x1="14" y1="4" x2="4" y2="14"/></svg>
        </button>
      </div>
      <div class="lq-progress"><i style="width:${pctDone}%"></i></div>`;
  }

  function renderQuestion() {
    const shell = document.getElementById("lq-shell");
    const total = S.questions.length;
    const q = S.questions[S.idx];
    const mod = q.mod;
    const picked = S.answers[S.idx];
    const answered = picked != null;
    shell.style.setProperty("--mc", "");
    const letters = ["A", "B", "C", "D", "E", "F"];
    const opts = q.c.map((opt, i) => {
      let cls = "";
      if (answered) {
        if (i === q.r) cls = " right";
        else if (i === picked) cls = " wrong";
        else cls = " dimmed";
      }
      return `<button class="lq-opt${cls}" data-i="${i}"${answered ? " disabled" : ""}><span class="lq-opt-letter">${letters[i]}</span><span>${esc(opt)}</span></button>`;
    }).join("");

    shell.innerHTML = header() + `
      <div class="lq-counter">
        <span class="lq-tag"><span class="dot" style="background:${colorVar(mod)}"></span>${esc(mod.short || mod.title)}</span>
        <span>Question <span class="lq-score">${S.idx + 1}</span> / ${total} · Score ${correctCount()}</span>
      </div>
      <div class="lq-question">${esc(q.q)}</div>
      <div class="lq-options" id="lq-options">${opts}</div>
      <div id="lq-correction-slot">${answered ? correctionHtml(q, picked) : ""}</div>
      <div class="lq-foot">
        <button class="lq-back" id="lq-back"${S.idx === 0 ? " disabled" : ""}>← Précédent</button>
        <button class="lq-next" id="lq-next"${answered ? "" : " disabled"}>${S.idx + 1 === total ? "Voir le score →" : "Question suivante →"}</button>
      </div>`;

    document.getElementById("lq-close").addEventListener("click", close);
    document.getElementById("lq-next").addEventListener("click", advance);
    document.getElementById("lq-back").addEventListener("click", back);
    document.querySelectorAll(".lq-opt").forEach(btn => {
      btn.addEventListener("click", () => pick(parseInt(btn.dataset.i, 10)));
    });
    document.getElementById("lenny-quiz").scrollTop = 0;
  }

  function pick(i) {
    if (S.answers[S.idx] != null) return;
    S.answers[S.idx] = i;
    renderQuestion();
    const next = document.getElementById("lq-next");
    if (next) next.focus();
  }

  function advance() {
    if (S.answers[S.idx] == null) return;
    if (S.idx + 1 >= S.questions.length) return renderResult();
    S.idx++;
    renderQuestion();
  }

  function back() {
    if (S.idx === 0) return;
    S.idx--;
    renderQuestion();
  }

  // Regroupe les réponses par module et enregistre un résultat horodaté chacun
  function recordResults() {
    if (!window.LennyAPI) return;
    const byMod = {};
    S.questions.forEach((q, i) => {
      const id = q.mod && q.mod.id; if (!id) return;
      const a = S.answers[i];
      if (a == null) return;
      byMod[id] = byMod[id] || { correct: 0, total: 0 };
      byMod[id].total++;
      if (a === q.r) byMod[id].correct++;
    });
    Object.keys(byMod).forEach(id => {
      LennyAPI.recordQuizResult({ moduleId: id, correct: byMod[id].correct, total: byMod[id].total });
    });
  }

  function renderResult() {
    const shell = document.getElementById("lq-shell");
    const total = S.questions.length;
    const score = correctCount();
    const pct = Math.round((score / total) * 100);
    const msg = pct === 100 ? "Sans-faute. Chapeau."
      : pct >= 75 ? "Excellent — tu maîtrises l'essentiel."
      : pct >= 50 ? "Pas mal. Quelques points à revoir."
      : "À retravailler — relance un tirage.";
    const wrong = S.questions
      .map((q, i) => ({ q, picked: S.answers[i] }))
      .filter(x => x.picked != null && x.picked !== x.q.r);
    const recap = wrong.length ? `
      <div class="lq-recap">
        <div class="lq-recap-h">À revoir — ${wrong.length} question${wrong.length > 1 ? "s" : ""}</div>
        ${wrong.map(w => `
          <div class="lq-recap-row">
            <div class="lq-recap-mod">${esc(w.q.mod.short || w.q.mod.title)}</div>
            <div class="lq-recap-q">${esc(w.q.q)}</div>
            <div class="lq-recap-a"><span class="tag">Bonne réponse</span>${esc(w.q.c[w.q.r])}</div>
          </div>`).join("")}
      </div>` : "";

    shell.innerHTML = header() + `
      <div class="lq-result">
        <div class="lq-result-score">${score}<span> / ${total}</span></div>
        <div class="lq-result-pct">${pct}% de réussite</div>
        <div class="lq-result-msg">${msg}</div>
        <div class="lq-result-actions">
          <button class="lq-btn lq-btn-primary" id="lq-restart">↻ Refaire le quiz</button>
          <button class="lq-btn lq-btn-ghost" id="lq-finish">Terminer</button>
        </div>
        ${recap}
        <div id="lq-feedback-slot"></div>
      </div>`;
    // Historique horodaté par module (alimente le radar) + avis
    recordResults();
    if (window.LennyFeedback) {
      const slot = shell.querySelector("#lq-feedback-slot");
      if (slot) window.LennyFeedback.mount(slot, "quiz-general", { label: "Ce quiz était-il pertinent ?" });
    }
    // progress full
    const bar = shell.querySelector(".lq-progress i");
    if (bar) bar.style.width = "100%";
    document.getElementById("lq-close").addEventListener("click", close);
    document.getElementById("lq-restart").addEventListener("click", open); // fresh reshuffle = reset
    document.getElementById("lq-finish").addEventListener("click", close);
    document.getElementById("lenny-quiz").scrollTop = 0;
  }

  // ESC to close
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      const el = document.getElementById("lenny-quiz");
      if (el && el.classList.contains("open")) close();
    }
  });

  window.LennyQuiz = { open, close };
})();

;
/* ===== lenny-srs.js ===== */
/* ============================================
   LENNY — Révisions du jour (répétition espacée, SM-2 simplifié)
   • Chaque question a une carte : juste → revient dans 1·3·7·21·45 j ;
     faux → revient demain (et redémarre l'échelle).
   • L'écran "Révisions du jour" sert automatiquement les questions dues,
     tous modules confondus, avec un quota de nouveautés/jour.
   • Persistance locale par utilisateur (code d'accès) via localStorage.
   Dépend de : LENNY_MODULES/MODULES, window.QUIZ/STUDY, LennyAPI (optionnel)
   ============================================ */
(function () {
  const DAY = 86400000;
  const STEPS = [1, 3, 7, 21, 45];   // échelle d'intervalles (jours)
  const NEW_PER_DAY = 12;            // nouvelles questions max introduites / jour
  const SESSION_MAX = 24;            // taille max d'une session
  const DAILY_GOAL = 20;             // objectif visuel de l'anneau

  /* ---------- identité + stockage ---------- */
  function uid() { try { return (window.LennyAPI && LennyAPI.userId()) || "u_anon"; } catch (e) { return "u_anon"; } }
  const KEY = () => "lenny-srs-v1::" + uid();
  function load() { try { return JSON.parse(localStorage.getItem(KEY())) || { cards: {}, intro: {}, done: {} }; } catch (e) { return { cards: {}, intro: {}, done: {} }; } }
  function save(s) { try { localStorage.setItem(KEY(), JSON.stringify(s)); } catch (e) {} }

  function hash(str) { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return (h >>> 0).toString(36); }
  function qid(modId, q) { return modId + "#" + hash(q); }
  function todayKey() { const d = new Date(); return d.getFullYear() + "-" + (d.getMonth() + 1) + "-" + d.getDate(); }

  function shuffle(arr) { const a = [...arr]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
  function shuffleOptions(q) {
    const order = shuffle(q.c.map((_, i) => i));
    return Object.assign({}, q, { c: order.map(i => q.c[i]), r: order.indexOf(q.r) });
  }

  /* ---------- pool + construction de session ---------- */
  function mods() { return (typeof LENNY_MODULES !== "undefined" && LENNY_MODULES.length) ? LENNY_MODULES : (window.MODULES || []); }
  function buildPool() {
    const pool = [];
    mods().forEach(m => {
      const qs = (window.QUIZ && window.QUIZ[m.id]) || (window.STUDY && window.STUDY[m.id] && window.STUDY[m.id].quiz) || [];
      qs.forEach(q => {
        if (q && Array.isArray(q.c) && typeof q.r === "number") {
          pool.push({ id: qid(m.id, q.q), q: q.q, c: q.c, r: q.r, e: q.e || "", mod: m });
        }
      });
    });
    return pool;
  }

  function buildSession() {
    const s = load(); const pool = buildPool(); const now = Date.now();
    const due = [], fresh = [];
    pool.forEach(p => {
      const c = s.cards[p.id];
      if (!c) fresh.push(p);
      else if (c.due <= now) due.push({ p, c });
    });
    due.sort((a, b) => a.c.due - b.c.due);            // les plus en retard d'abord
    const introCount = (s.intro && s.intro[todayKey()]) || 0;
    const newAllowed = Math.max(0, NEW_PER_DAY - introCount);
    let session = due.map(d => d.p);
    const room = Math.max(0, SESSION_MAX - session.length);
    const freshPick = shuffle(fresh).slice(0, Math.min(newAllowed, room));
    session = session.concat(freshPick).slice(0, SESSION_MAX);
    return {
      session: shuffle(session).map(shuffleOptions),
      dueTotal: due.length,
      freshIds: freshPick.map(f => f.id),
      poolSize: pool.length,
      learned: Object.keys(s.cards).length,
    };
  }

  function dueCount() { return buildSession().session.length; }

  /* ---------- planification (cœur SM-2 simplifié) ---------- */
  function schedule(card, correct) {
    const c = card || { step: -1, ivl: 0, due: 0, streak: 0, lapses: 0, seen: 0 };
    if (correct) {
      c.step = Math.min((c.step | 0) + 1, STEPS.length - 1);
      c.streak = (c.streak | 0) + 1;
      c.ivl = STEPS[c.step];
    } else {
      c.step = 0; c.ivl = 1; c.streak = 0; c.lapses = (c.lapses | 0) + 1;
    }
    c.due = Date.now() + c.ivl * DAY;
    c.seen = (c.seen | 0) + 1;
    c.last = Date.now();
    return c;
  }

  function ivlLabel(ivl) {
    if (ivl <= 1) return "demain";
    if (ivl < 7) return "dans " + ivl + " jours";
    if (ivl < 30) return "dans " + Math.round(ivl / 7) + " semaine" + (ivl >= 14 ? "s" : "");
    return "dans " + Math.round(ivl / 30) + " mois";
  }

  /* ---------- état runtime ---------- */
  const R = { list: [], idx: 0, picked: null, correct: 0, wrong: 0, isNew: {}, byMod: {} };

  function colorVar(mod) { return "var(--" + (mod.color || "red") + ", var(--srs-gold))"; }
  function esc(s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }

  function ensureEl() {
    let el = document.getElementById("lenny-srs");
    if (el) return el;
    el = document.createElement("div");
    el.id = "lenny-srs";
    el.innerHTML = '<div class="srs-shell" id="srs-shell"></div>';
    document.body.appendChild(el);
    return el;
  }

  function open() {
    const b = buildSession();
    if (!b.session.length) { renderEmptyOverlay(); return; }
    R.list = b.session; R.idx = 0; R.picked = null; R.correct = 0; R.wrong = 0; R.byMod = {};
    R.isNew = {}; b.freshIds.forEach(id => R.isNew[id] = true);
    const el = ensureEl(); el.classList.add("open");
    document.documentElement.style.overflow = "hidden";
    renderCard();
  }

  function close() {
    const el = document.getElementById("lenny-srs");
    if (el) el.classList.remove("open");
    document.documentElement.style.overflow = "";
    R.list = []; R.idx = 0; R.picked = null;
    refreshSurfaces();
  }

  function header(pct) {
    return `
      <div class="srs-top">
        <div class="srs-brand">Révisions du jour · répétition espacée</div>
        <button class="srs-close" id="srs-close" aria-label="Fermer">
          <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><line x1="4" y1="4" x2="14" y2="14"/><line x1="14" y1="4" x2="4" y2="14"/></svg>
        </button>
      </div>
      <div class="srs-progress"><i style="width:${pct}%"></i></div>`;
  }

  function renderCard() {
    const shell = document.getElementById("srs-shell");
    const total = R.list.length;
    const q = R.list[R.idx];
    const mod = q.mod;
    const answered = R.picked != null;
    const pct = Math.round((R.idx / total) * 100);
    const letters = ["A", "B", "C", "D", "E", "F"];
    shell.style.setProperty("--mc", colorVar(mod));
    const opts = q.c.map((opt, i) => {
      let cls = "";
      if (answered) {
        if (i === q.r) cls = " right";
        else if (i === R.picked) cls = " wrong";
        else cls = " dimmed";
      }
      return `<button class="srs-opt${cls}" data-i="${i}"${answered ? " disabled" : ""}><span class="srs-opt-letter">${letters[i]}</span><span>${esc(opt)}</span></button>`;
    }).join("");

    let correction = "";
    if (answered) {
      const ok = R.picked === q.r;
      const card = schedulePreview(q, ok);
      correction = `
        <div class="srs-correction ${ok ? "good" : "bad"}">
          <div class="srs-correction-h">${ok ? "✓ Juste" : "✗ Raté"}</div>
          ${ok ? "" : `<span class="srs-correction-right">Bonne réponse : <strong>${letters[q.r]} — ${esc(q.c[q.r])}</strong></span>`}
          ${q.e ? `<div class="srs-correction-body">${esc(q.e)}</div>` : ""}
          <div class="srs-sched">
            <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="8" cy="8" r="6.4"/><path d="M8 4.6V8l2.4 1.6" stroke-linecap="round"/></svg>
            Revue ${ivlLabel(card.ivl)}
          </div>
        </div>`;
    }

    const isLast = R.idx + 1 >= total;
    shell.innerHTML = header(pct) + `
      <div class="srs-counter">
        <span class="srs-tag"><span class="dot"></span>${esc(mod.short || mod.title)}${R.isNew[q.id] ? '<span class="srs-newflag">Nouveau</span>' : ""}</span>
        <span>${R.idx + 1} / ${total} · ${R.correct} ✓</span>
      </div>
      <div class="srs-question">${esc(q.q)}</div>
      <div class="srs-options">${opts}</div>
      <div id="srs-correction-slot">${correction}</div>
      <div class="srs-foot">
        <button class="srs-next" id="srs-next"${answered ? "" : " disabled"}>${isLast ? "Terminer →" : "Suivante →"}</button>
      </div>`;

    document.getElementById("srs-close").addEventListener("click", close);
    document.getElementById("srs-next").addEventListener("click", advance);
    shell.querySelectorAll(".srs-opt").forEach(btn => btn.addEventListener("click", () => pick(parseInt(btn.dataset.i, 10))));
    document.getElementById("lenny-srs").scrollTop = 0;
  }

  // calcule l'intervalle sans muter (pour l'affichage), puis on commit dans pick()
  function schedulePreview(q, ok) {
    const s = load();
    const existing = s.cards[q.id] ? Object.assign({}, s.cards[q.id]) : null;
    return schedule(existing, ok);
  }

  function pick(i) {
    if (R.picked != null) return;
    R.picked = i;
    const q = R.list[R.idx];
    const ok = i === q.r;
    if (ok) R.correct++; else R.wrong++;
    // commit planification
    const s = load();
    s.cards[q.id] = schedule(s.cards[q.id] || null, ok);
    if (R.isNew[q.id]) {
      s.intro = s.intro || {};
      s.intro[todayKey()] = (s.intro[todayKey()] || 0) + 1;
      R.isNew[q.id] = false; // ne compte qu'une fois
    }
    save(s);
    // agrège pour le radar
    const id = q.mod && q.mod.id;
    if (id) { R.byMod[id] = R.byMod[id] || { correct: 0, total: 0 }; R.byMod[id].total++; if (ok) R.byMod[id].correct++; }
    renderCard();
    const n = document.getElementById("srs-next"); if (n) n.focus();
  }

  function advance() {
    if (R.picked == null) return;
    if (R.idx + 1 >= R.list.length) return renderDone();
    R.idx++; R.picked = null;
    renderCard();
  }

  function nextDueInfo() {
    const s = load(); const now = Date.now(); let min = Infinity;
    Object.keys(s.cards).forEach(k => { const d = s.cards[k].due; if (d > now && d < min) min = d; });
    if (min === Infinity) return "Plus rien de programmé — tu peux découvrir de nouvelles questions demain.";
    const days = Math.max(1, Math.round((min - now) / DAY));
    return "Prochaine session : " + (days <= 1 ? "demain" : "dans " + days + " jours") + ".";
  }

  function renderDone() {
    const shell = document.getElementById("srs-shell");
    const total = R.correct + R.wrong;
    const pct = total ? Math.round((R.correct / total) * 100) : 0;
    // enregistre l'historique par module (alimente le radar / progression)
    if (window.LennyAPI) {
      Object.keys(R.byMod).forEach(id => LennyAPI.recordQuizResult({ moduleId: id, correct: R.byMod[id].correct, total: R.byMod[id].total }));
    }
    // marque la session du jour comme faite
    const s = load(); s.done = s.done || {}; s.done[todayKey()] = (s.done[todayKey()] || 0) + total; save(s);

    const msg = pct >= 85 ? "Mémoire au top." : pct >= 60 ? "Bien — les cartes ratées reviennent vite." : "Les points fragiles reviendront dès demain.";
    shell.innerHTML = header(100) + `
      <div class="srs-done">
        <div class="srs-done-ico">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12.5 L9.5 18 L20 6.5"/></svg>
        </div>
        <div class="srs-done-h">Session terminée</div>
        <div class="srs-done-sub">${esc(msg)}</div>
        <div class="srs-stats">
          <div class="srs-stat"><div class="srs-stat-n">${total}</div><div class="srs-stat-l">Révisées</div></div>
          <div class="srs-stat good"><div class="srs-stat-n">${R.correct}</div><div class="srs-stat-l">Maîtrisées</div></div>
          <div class="srs-stat bad"><div class="srs-stat-n">${R.wrong}</div><div class="srs-stat-l">À revoir</div></div>
        </div>
        <div class="srs-next-info">
          <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="2.2" y="3.2" width="11.6" height="10.6" rx="1.6"/><path d="M2.2 6.2h11.6M5.5 1.8v2.6M10.5 1.8v2.6" stroke-linecap="round"/></svg>
          ${esc(nextDueInfo())}
        </div>
        <div class="srs-done-actions">
          ${dueCount() > 0 ? '<button class="srs-btn srs-btn-primary" id="srs-again">Continuer (' + dueCount() + ')</button>' : ""}
          <button class="srs-btn srs-btn-ghost" id="srs-finish">Fermer</button>
        </div>
      </div>`;
    document.getElementById("srs-close").addEventListener("click", close);
    document.getElementById("srs-finish").addEventListener("click", close);
    const again = document.getElementById("srs-again");
    if (again) again.addEventListener("click", open);
    document.getElementById("lenny-srs").scrollTop = 0;
  }

  function renderEmptyOverlay() {
    const el = ensureEl(); el.classList.add("open");
    document.documentElement.style.overflow = "hidden";
    const shell = document.getElementById("srs-shell");
    shell.innerHTML = header(100) + `
      <div class="srs-done">
        <div class="srs-done-ico" style="color:var(--green);border-color:rgba(70,211,105,.4);background:radial-gradient(circle at 50% 35%, rgba(70,211,105,.25), rgba(70,211,105,.04))">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12.5 L9.5 18 L20 6.5"/></svg>
        </div>
        <div class="srs-done-h">Tout est à jour</div>
        <div class="srs-done-sub">${esc(nextDueInfo())}</div>
        <div class="srs-done-actions">
          <button class="srs-btn srs-btn-ghost" id="srs-finish">Fermer</button>
        </div>
      </div>`;
    document.getElementById("srs-close").addEventListener("click", close);
    document.getElementById("srs-finish").addEventListener("click", close);
  }

  /* ---------- surfaces (bouton nav + bandeau accueil) ---------- */
  function buildBanner() {
    const mount = document.getElementById("progress-srs-mount");
    const home = document.getElementById("view-home");
    const host = mount || home;
    if (!host) return null;
    let sec = document.getElementById("srs-home");
    if (sec) return sec;
    sec = document.createElement("section");
    sec.className = "srs-home";
    sec.id = "srs-home";
    if (mount) { mount.appendChild(sec); return sec; }
    const cont = document.getElementById("continue");
    if (cont && cont.parentNode === home) home.insertBefore(sec, cont);
    else home.insertBefore(sec, home.firstChild);
    return sec;
  }

  function renderBanner() {
    const sec = buildBanner();
    if (!sec) return;
    const b = buildSession();
    const due = b.session.length;
    const goal = DAILY_GOAL;
    const ratio = Math.min(1, due === 0 ? 1 : Math.min(due, goal) / goal);
    const C = 2 * Math.PI * 27; // r=27
    const off = C * (1 - ratio);
    sec.classList.toggle("is-empty", due === 0);
    const ring = `
      <div class="srs-ring">
        <svg viewBox="0 0 64 64"><circle class="srs-ring-track" cx="32" cy="32" r="27" fill="none" stroke-width="6"/><circle class="srs-ring-fill" cx="32" cy="32" r="27" fill="none" stroke-width="6" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${off.toFixed(1)}"/></svg>
        <span class="srs-ring-num">${due === 0 ? "✓" : due}</span>
      </div>`;
    if (due === 0) {
      sec.innerHTML = `
        <div class="srs-card">
          ${ring}
          <div class="srs-home-txt">
            <div class="srs-kicker">Révisions du jour</div>
            <div class="srs-home-h">Tout est à jour</div>
            <div class="srs-home-sub">${esc(nextDueInfo())} Reviens demain pour consolider ta mémoire.</div>
          </div>
          <button class="srs-home-cta" id="srs-home-cta">Voir l'avancée</button>
        </div>`;
    } else {
      const learned = b.learned;
      sec.innerHTML = `
        <div class="srs-card">
          ${ring}
          <div class="srs-home-txt">
            <div class="srs-kicker">Révisions du jour</div>
            <div class="srs-home-h">${due} question${due > 1 ? "s" : ""} à revoir aujourd'hui</div>
            <div class="srs-home-sub">La répétition espacée te ressert chaque notion au bon moment.${learned ? " " + learned + " carte" + (learned > 1 ? "s" : "") + " en mémoire." : " Démarre ta toute première session."}</div>
          </div>
          <button class="srs-home-cta" id="srs-home-cta">
            <svg viewBox="0 0 18 18" fill="currentColor"><path d="M4 2 L15 9 L4 16 Z"/></svg>
            Commencer
          </button>
        </div>`;
    }
    const cta = document.getElementById("srs-home-cta");
    if (cta) cta.addEventListener("click", open);
  }

  function renderNavBadge() {
    const badge = document.getElementById("srs-badge");
    if (!badge) return;
    const due = dueCount();
    if (due > 0) { badge.textContent = due > 99 ? "99+" : String(due); badge.hidden = false; }
    else badge.hidden = true;
  }

  function refreshSurfaces() { try { renderBanner(); renderNavBadge(); } catch (e) {} }

  /* ---------- init ---------- */
  function init() {
    const btn = document.getElementById("srs-btn");
    if (btn) btn.addEventListener("click", open);
    refreshSurfaces();
  }

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") { const el = document.getElementById("lenny-srs"); if (el && el.classList.contains("open")) close(); }
  });

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", () => setTimeout(init, 60));
  else setTimeout(init, 60);

  window.LennySRS = { open, close, dueCount, refresh: refreshSurfaces };
})();

;
/* ===== lenny-calc.js ===== */
/* ============================================
   LENNY — Calculatrices interactives (BTS PI)
   Overlay live : mensualité, capacité HCSF, endettement, rendement,
   honoraires, plus-value, tantièmes (charges copro), viager.
   API : window.LennyCalc.open('pret' | ...) — sans argument => 1re calc.
   Aucune dépendance de données (tout est en interne).
   ============================================ */
(function () {
  "use strict";

  /* ---------- helpers de formatage ---------- */
  function eur(n) {
    if (!isFinite(n)) return "—";
    return Math.round(n).toLocaleString("fr-FR") + " €";
  }
  function eur2(n) {
    if (!isFinite(n)) return "—";
    return n.toLocaleString("fr-FR", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " €";
  }
  function pct(n, d) {
    if (!isFinite(n)) return "—";
    return n.toLocaleString("fr-FR", { minimumFractionDigits: d == null ? 2 : d, maximumFractionDigits: d == null ? 2 : d }) + " %";
  }
  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  // mensualité d'un prêt amortissable
  function mensualite(capital, tauxAnnuel, annees) {
    const n = annees * 12;
    const t = Math.pow(1 + tauxAnnuel / 100, 1 / 12) - 1; // 20/09/2026 : taux mensuel ÉQUIVALENT, comme le tableau financier du cours (correction de Mme Rebours du 04/09/2026). Avant : tauxAnnuel / 100 / 12 (proportionnel).
    if (t === 0) return capital / n;
    return capital * t / (1 - Math.pow(1 + t, -n));
  }
  // capital empruntable pour une mensualité donnée
  function capitalEmpruntable(mens, tauxAnnuel, annees) {
    const n = annees * 12;
    const t = Math.pow(1 + tauxAnnuel / 100, 1 / 12) - 1; // 20/09/2026 : taux mensuel ÉQUIVALENT, comme le tableau financier du cours (correction de Mme Rebours du 04/09/2026). Avant : tauxAnnuel / 100 / 12 (proportionnel).
    if (t === 0) return mens * n;
    return mens * (1 - Math.pow(1 + t, -n)) / t;
  }

  /* ---------- définition des calculatrices ----------
     Chaque calc : { id, pole, name, tag, desc, inputs[], compute(v) -> {rows[], verdict?, note?} }
     input : { k, label, suffix, def, min, max, step }
  */
  const CALCS = [
    {
      id: "pret", pole: "Financement", name: "Mensualité de prêt", tag: "Crédit",
      desc: "Mensualité, coût total et intérêts d'un prêt amortissable à taux fixe.",
      inputs: [
        { k: "capital", label: "Montant emprunté", suffix: "€", def: 200000, min: 0, step: 1000 },
        { k: "taux", label: "Taux nominal annuel", suffix: "%", def: 3.5, min: 0, step: 0.05 },
        { k: "duree", label: "Durée", suffix: "ans", def: 20, min: 1, max: 30, step: 1 },
        { k: "assur", label: "Assurance (taux annuel)", suffix: "%", def: 0.34, min: 0, step: 0.01 },
      ],
      compute(v) {
        const m = mensualite(v.capital, v.taux, v.duree);
        const assurMens = v.capital * (v.assur / 100) / 12;
        const total = (m + assurMens) * v.duree * 12;
        const interets = m * v.duree * 12 - v.capital;
        const coutAssur = assurMens * v.duree * 12;
        return {
          hero: { label: "Mensualité (avec assurance)", value: eur2(m + assurMens) },
          rows: [
            ["Mensualité hors assurance", eur2(m)],
            ["Part assurance / mois", eur2(assurMens)],
            ["Intérêts totaux", eur(interets)],
            ["Coût total de l'assurance", eur(coutAssur)],
            ["Coût total du crédit", eur(interets + coutAssur)],
            ["Total remboursé", eur(total)],
          ],
          note: "Calcul à taux fixe, échéances constantes. L'assurance est estimée sur le capital initial (méthode courante des banques).",
        };
      },
    },
    {
      id: "capacite", pole: "Financement", name: "Capacité d'emprunt (HCSF)", tag: "HCSF 35 %",
      desc: "Combien puis-je emprunter ? Plafond d'endettement HCSF de 35 % assurance comprise.",
      inputs: [
        { k: "revenus", label: "Revenus nets mensuels du foyer", suffix: "€", def: 3500, min: 0, step: 50 },
        { k: "charges", label: "Crédits / pensions en cours (/mois)", suffix: "€", def: 200, min: 0, step: 10 },
        { k: "taux", label: "Taux nominal annuel", suffix: "%", def: 3.5, min: 0, step: 0.05 },
        { k: "duree", label: "Durée", suffix: "ans", def: 25, min: 1, max: 30, step: 1 },
        { k: "apport", label: "Apport personnel", suffix: "€", def: 30000, min: 0, step: 1000 },
      ],
      compute(v) {
        const mensMax = v.revenus * 0.35 - v.charges;
        const cap = capitalEmpruntable(Math.max(0, mensMax), v.taux, v.duree);
        const budget = cap + v.apport;
        return {
          hero: { label: "Capacité d'emprunt", value: eur(Math.max(0, cap)) },
          rows: [
            ["Mensualité maximale (35 %)", eur2(Math.max(0, mensMax))],
            ["Dont déjà absorbé par vos crédits", eur2(v.charges)],
            ["+ Apport personnel", eur(v.apport)],
            ["Budget projet total", eur(budget)],
          ],
          verdict: mensMax <= 0
            ? { tone: "bad", text: "Vos charges dépassent déjà le plafond de 35 % : capacité nulle." }
            : { tone: "ok", text: "Plafond HCSF respecté (35 % d'endettement maximum, assurance comprise)." },
          note: "Le HCSF autorise jusqu'à 35 % d'endettement et 25 ans (27 avec différé). 20 % des dossiers peuvent déroger.",
        };
      },
    },
    {
      id: "endettement", pole: "Financement", name: "Taux d'endettement", tag: "Ratio",
      desc: "Part des revenus absorbée par les charges de crédit. Seuil d'alerte : 35 %.",
      inputs: [
        { k: "revenus", label: "Revenus nets mensuels", suffix: "€", def: 3500, min: 0, step: 50 },
        { k: "mensImmo", label: "Mensualité du futur crédit", suffix: "€", def: 950, min: 0, step: 10 },
        { k: "autres", label: "Autres crédits (/mois)", suffix: "€", def: 200, min: 0, step: 10 },
      ],
      compute(v) {
        const charges = v.mensImmo + v.autres;
        const taux = v.revenus > 0 ? charges / v.revenus * 100 : Infinity;
        const reste = v.revenus - charges;
        return {
          hero: { label: "Taux d'endettement", value: pct(taux, 1) },
          rows: [
            ["Total charges de crédit", eur2(charges)],
            ["Reste à vivre", eur2(reste)],
            ["Seuil HCSF", "35,0 %"],
          ],
          verdict: taux <= 35
            ? { tone: "ok", text: "Sous le seuil de 35 % — dossier dans les clous." }
            : { tone: "bad", text: "Au-dessus de 35 % — financement à risque hors dérogation." },
        };
      },
    },
    {
      id: "rendement", pole: "Transaction", name: "Rendement locatif", tag: "Investissement",
      desc: "Rentabilité brute et nette d'un investissement locatif.",
      inputs: [
        { k: "prix", label: "Prix d'achat", suffix: "€", def: 180000, min: 1, step: 1000 },
        { k: "frais", label: "Frais d'acquisition", suffix: "%", def: 8, min: 0, step: 0.5 },
        { k: "loyer", label: "Loyer mensuel (hors charges)", suffix: "€", def: 750, min: 0, step: 10 },
        { k: "chargesAn", label: "Charges non récupérables /an", suffix: "€", def: 600, min: 0, step: 50 },
        { k: "taxe", label: "Taxe foncière /an", suffix: "€", def: 900, min: 0, step: 50 },
      ],
      compute(v) {
        const loyerAn = v.loyer * 12;
        const invest = v.prix * (1 + v.frais / 100);
        const brut = v.prix > 0 ? loyerAn / v.prix * 100 : 0;
        const net = invest > 0 ? (loyerAn - v.chargesAn - v.taxe) / invest * 100 : 0;
        return {
          hero: { label: "Rentabilité nette", value: pct(net, 2) },
          rows: [
            ["Loyers annuels", eur(loyerAn)],
            ["Investissement total (frais inclus)", eur(invest)],
            ["Rentabilité brute", pct(brut, 2)],
            ["Cash-flow annuel (avant impôt/crédit)", eur(loyerAn - v.chargesAn - v.taxe)],
          ],
          note: "Net de charges et taxe foncière, hors fiscalité et financement. Une « net-net » intégrerait l'impôt.",
        };
      },
    },
    {
      id: "honoraires", pole: "Transaction", name: "Honoraires d'agence", tag: "Commission",
      desc: "Du prix FAI au net vendeur, et inversement selon le barème d'honoraires.",
      inputs: [
        { k: "fai", label: "Prix de vente FAI", suffix: "€", def: 250000, min: 0, step: 1000 },
        { k: "taux", label: "Taux d'honoraires", suffix: "%", def: 4, min: 0, step: 0.1 },
        { k: "charge", label: "Honoraires à la charge", suffix: "vendeur", def: 0, min: 0, max: 1, step: 1, seg: ["vendeur", "acquéreur"] },
      ],
      compute(v) {
        // honoraires calculés sur le net vendeur : FAI = net * (1+taux)
        const net = v.fai / (1 + v.taux / 100);
        const hono = v.fai - net;
        const chargeAcq = v.charge >= 1;
        const baseDMTO = chargeAcq ? net : v.fai;
        return {
          hero: { label: "Honoraires d'agence", value: eur(hono) },
          rows: [
            ["Prix FAI (annonce)", eur(v.fai)],
            ["Net vendeur", eur(net)],
            ["Honoraires (TTC)", eur2(hono)],
            ["À la charge de", chargeAcq ? "l'acquéreur" : "le vendeur"],
            ["Assiette des droits de mutation", eur(baseDMTO)],
          ],
          note: chargeAcq
            ? "Honoraires à charge acquéreur : les droits de mutation se calculent sur le net vendeur (hors honoraires)."
            : "Honoraires à charge vendeur : les droits de mutation portent sur le prix FAI.",
        };
      },
    },
    {
      id: "plusvalue", pole: "Transaction", name: "Plus-value immobilière", tag: "Fiscalité",
      desc: "Impôt sur la plus-value d'une résidence secondaire / locative selon la durée de détention.",
      inputs: [
        { k: "achat", label: "Prix d'acquisition", suffix: "€", def: 150000, min: 0, step: 1000 },
        { k: "vente", label: "Prix de cession", suffix: "€", def: 230000, min: 0, step: 1000 },
        { k: "annees", label: "Durée de détention", suffix: "ans", def: 12, min: 0, max: 40, step: 1 },
        { k: "forfaits", label: "Forfaits frais + travaux", suffix: "oui", def: 1, min: 0, max: 1, step: 1, seg: ["non", "oui"] },
      ],
      compute(v) {
        let acquMaj = v.achat;
        if (v.forfaits >= 1) {
          acquMaj = v.achat * 1.075; // 7,5 % frais d'acquisition
          if (v.annees >= 5) acquMaj += v.achat * 0.15; // 15 % travaux
        }
        const pv = Math.max(0, v.vente - acquMaj);
        // abattement IR : 6 %/an de la 6e à 21e, 4 % la 22e — exonéré à 22 ans
        function abatIR(a) {
          if (a >= 22) return 1;
          if (a <= 5) return 0;
          return Math.min(1, (Math.min(a, 21) - 5) * 0.06 + (a >= 22 ? 0.04 : 0));
        }
        // abattement PS : 1,65 %/an 6-21, 1,60 % la 22e, 9 %/an 23-30 — exonéré à 30 ans
        function abatPS(a) {
          if (a >= 30) return 1;
          if (a <= 5) return 0;
          let r = (Math.min(a, 21) - 5) * 0.0165;
          if (a >= 22) r += 0.016;
          if (a > 22) r += (Math.min(a, 30) - 22) * 0.09;
          return Math.min(1, r);
        }
        const baseIR = pv * (1 - abatIR(v.annees));
        const basePS = pv * (1 - abatPS(v.annees));
        const ir = baseIR * 0.19;
        const ps = basePS * 0.172;
        const total = ir + ps;
        return {
          hero: { label: "Impôt total estimé", value: eur(total) },
          rows: [
            ["Plus-value brute", eur(pv)],
            ["Abattement IR appliqué", pct(abatIR(v.annees) * 100, 0)],
            ["Impôt sur le revenu (19 %)", eur(ir)],
            ["Prélèvements sociaux (17,2 %)", eur(ps)],
            ["Net encaissé après impôt", eur(v.vente - total)],
          ],
          verdict: v.annees >= 30
            ? { tone: "ok", text: "Détention ≥ 30 ans : exonération totale (IR + prélèvements sociaux)." }
            : v.annees >= 22
              ? { tone: "ok", text: "Détention ≥ 22 ans : exonéré d'IR, reste les prélèvements sociaux." }
              : null,
          note: "Hors surtaxe sur les plus-values > 50 000 € et cas d'exonération (résidence principale notamment).",
        };
      },
    },
    {
      id: "tantiemes", pole: "Syndic", name: "Tantièmes & charges", tag: "Copropriété",
      desc: "Quote-part d'un lot dans une charge de copropriété au prorata des tantièmes.",
      inputs: [
        { k: "charge", label: "Montant de la charge", suffix: "€", def: 12000, min: 0, step: 100 },
        { k: "tantLot", label: "Tantièmes du lot", suffix: "/", def: 145, min: 0, step: 1 },
        { k: "tantTot", label: "Tantièmes totaux", suffix: "tot.", def: 1000, min: 1, step: 1 },
      ],
      compute(v) {
        const part = v.tantTot > 0 ? v.charge * (v.tantLot / v.tantTot) : 0;
        const quote = v.tantTot > 0 ? v.tantLot / v.tantTot * 100 : 0;
        return {
          hero: { label: "Quote-part du lot", value: eur2(part) },
          rows: [
            ["Quote-part en %", pct(quote, 3)],
            ["Provision trimestrielle", eur2(part / 4)],
            ["Provision mensuelle", eur2(part / 12)],
          ],
          note: "Répartition proportionnelle aux tantièmes de charges générales (art. 10 loi de 1965). Les charges spéciales suivent une clé d'utilité propre.",
        };
      },
    },
    {
      id: "viager", pole: "Syndic", name: "Viager occupé", tag: "Démembrement",
      desc: "Bouquet, rente viagère et valeur d'occupation à partir de la valeur vénale.",
      inputs: [
        { k: "valeur", label: "Valeur vénale (libre)", suffix: "€", def: 300000, min: 0, step: 1000 },
        { k: "age", label: "Âge du crédirentier", suffix: "ans", def: 75, min: 50, max: 99, step: 1 },
        { k: "bouquet", label: "Bouquet versé", suffix: "€", def: 60000, min: 0, step: 1000 },
        { k: "taux", label: "Taux de rente annuel", suffix: "%", def: 5, min: 1, step: 0.1 },
      ],
      compute(v) {
        // décote d'occupation (DUH) approchée par l'espérance de vie / barème usufruit
        const esp = Math.max(2, 90 - v.age); // espérance de vie résiduelle approchée
        // coefficient d'occupation : ~ valeur locative actualisée — barème simplifié
        const decote = Math.min(0.6, 0.025 * esp); // plus jeune => plus de décote
        const valeurOccupee = v.valeur * (1 - decote);
        const aRenter = Math.max(0, valeurOccupee - v.bouquet);
        const renteAn = aRenter * (v.taux / 100);
        return {
          hero: { label: "Rente mensuelle", value: eur2(renteAn / 12) },
          rows: [
            ["Espérance de vie retenue", esp + " ans"],
            ["Décote d'occupation (DUH)", pct(decote * 100, 0)],
            ["Valeur occupée", eur(valeurOccupee)],
            ["Capital à transformer en rente", eur(aRenter)],
            ["Rente annuelle", eur(renteAn)],
          ],
          note: "Barème d'occupation simplifié à visée pédagogique. En pratique on utilise les barèmes Daubry / fiscal et la valeur locative réelle.",
        };
      },
    },
  ];

  /* ---------- état runtime ---------- */
  const R = { id: CALCS[0].id, vals: {} };

  function calcById(id) { return CALCS.find(c => c.id === id) || CALCS[0]; }

  function defaults(calc) {
    const o = {};
    calc.inputs.forEach(i => o[i.k] = i.def);
    return o;
  }

  /* ---------- DOM ---------- */
  function ensureEl() {
    let el = document.getElementById("lenny-calc");
    if (el) return el;
    el = document.createElement("div");
    el.id = "lenny-calc";
    el.innerHTML = '<div class="lc-backdrop" data-lc-close></div><div class="lc-shell" id="lc-shell" role="dialog" aria-modal="true" aria-label="Calculatrices"></div>';
    document.body.appendChild(el);
    el.addEventListener("click", (e) => {
      if (e.target.closest("[data-lc-close]")) return close();
      const nav = e.target.closest("[data-lc-go]");
      if (nav) { selectCalc(nav.getAttribute("data-lc-go")); return; }
      if (e.target.closest("[data-lc-reset]")) { R.vals = defaults(calcById(R.id)); renderBody(); return; }
    });
    el.addEventListener("input", (e) => {
      const f = e.target.closest("[data-lc-k]");
      if (f) { R.vals[f.getAttribute("data-lc-k")] = parseFloat(f.value) || 0; renderResults(); syncRange(f); }
    });
    el.addEventListener("click", (e) => {
      const seg = e.target.closest("[data-lc-seg]");
      if (seg) {
        const k = seg.getAttribute("data-lc-seg");
        R.vals[k] = parseFloat(seg.getAttribute("data-lc-val"));
        renderBody();
      }
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && el.classList.contains("open")) close();
    });
    return el;
  }

  function railHtml() {
    const poles = [];
    CALCS.forEach(c => { if (!poles.includes(c.pole)) poles.push(c.pole); });
    return poles.map(p => {
      const items = CALCS.filter(c => c.pole === p).map(c =>
        `<button class="lc-railitem${c.id === R.id ? " on" : ""}" data-lc-go="${c.id}" type="button">
           <span class="lc-railitem-name">${esc(c.name)}</span>
           <span class="lc-railitem-tag">${esc(c.tag)}</span>
         </button>`).join("");
      return `<div class="lc-railgroup"><div class="lc-railgroup-h">${esc(p)}</div>${items}</div>`;
    }).join("");
  }

  function fieldHtml(calc, inp) {
    const val = R.vals[inp.k];
    if (inp.seg) {
      const segs = inp.seg.map((lab, i) =>
        `<button class="lc-seg${val == i ? " on" : ""}" data-lc-seg="${inp.k}" data-lc-val="${i}" type="button">${esc(lab)}</button>`).join("");
      return `<div class="lc-field"><label class="lc-label">${esc(inp.label)}</label><div class="lc-segwrap">${segs}</div></div>`;
    }
    const hasRange = inp.max != null;
    return `
      <div class="lc-field">
        <label class="lc-label">${esc(inp.label)}</label>
        <div class="lc-inputwrap">
          <input class="lc-input" type="number" inputmode="decimal" data-lc-k="${inp.k}"
                 value="${val}" ${inp.min != null ? `min="${inp.min}"` : ""} ${inp.max != null ? `max="${inp.max}"` : ""} step="${inp.step || 1}">
          <span class="lc-suffix">${esc(inp.suffix || "")}</span>
        </div>
        ${hasRange ? `<input class="lc-range" type="range" data-lc-k="${inp.k}" value="${val}" min="${inp.min || 0}" max="${inp.max}" step="${inp.step || 1}">` : ""}
      </div>`;
  }

  function syncRange(f) {
    // garde input number et range alignés
    const wrap = f.closest(".lc-field");
    if (!wrap) return;
    wrap.querySelectorAll('[data-lc-k="' + f.getAttribute("data-lc-k") + '"]').forEach(el => {
      if (el !== f) el.value = f.value;
    });
  }

  function resultsHtml(calc) {
    const out = calc.compute(R.vals);
    const rows = out.rows.map(r => `<div class="lc-row"><span class="lc-row-k">${esc(r[0])}</span><span class="lc-row-v">${r[1]}</span></div>`).join("");
    const verdict = out.verdict ? `<div class="lc-verdict ${out.verdict.tone}">${esc(out.verdict.text)}</div>` : "";
    const note = out.note ? `<div class="lc-cnote">${esc(out.note)}</div>` : "";
    return `
      <div class="lc-hero">
        <div class="lc-hero-label">${esc(out.hero.label)}</div>
        <div class="lc-hero-value">${out.hero.value}</div>
      </div>
      ${verdict}
      <div class="lc-rows">${rows}</div>
      ${note}`;
  }

  function renderResults() {
    const calc = calcById(R.id);
    const slot = document.getElementById("lc-results");
    if (slot) slot.innerHTML = resultsHtml(calc);
  }

  function renderBody() {
    const calc = calcById(R.id);
    const el = ensureEl();
    const fields = calc.inputs.map(i => fieldHtml(calc, i)).join("");
    el.querySelector("#lc-shell").innerHTML = `
      <button class="lc-close" data-lc-close aria-label="Fermer">✕</button>
      <aside class="lc-rail">
        <div class="lc-brand"><span class="lc-brand-l">L</span> Calculatrices</div>
        <div class="lc-railscroll">${railHtml()}</div>
      </aside>
      <main class="lc-main">
        <header class="lc-head">
          <div class="lc-head-tag">${esc(calc.pole)} · ${esc(calc.tag)}</div>
          <h2 class="lc-head-title">${esc(calc.name)}</h2>
          <p class="lc-head-desc">${esc(calc.desc)}</p>
        </header>
        <div class="lc-grid">
          <section class="lc-inputs">
            ${fields}
            <button class="lc-resetbtn" data-lc-reset type="button">Réinitialiser</button>
          </section>
          <section class="lc-results" id="lc-results">${resultsHtml(calc)}</section>
        </div>
      </main>`;
    const sc = el.querySelector("#lc-shell");
    if (sc) sc.scrollTop = 0;
  }

  function selectCalc(id) {
    R.id = id;
    R.vals = defaults(calcById(id));
    renderBody();
  }

  function open(id) {
    const el = ensureEl();
    selectCalc(id && calcById(id).id === id ? id : R.id || CALCS[0].id);
    el.classList.add("open");
    document.documentElement.style.overflow = "hidden";
  }
  function close() {
    const el = document.getElementById("lenny-calc");
    if (el) el.classList.remove("open");
    document.documentElement.style.overflow = "";
  }

  window.LennyCalc = { open, close };
})();

;
/* ===== lenny-exam.js ===== */
/* ============================================
   LENNY — Examen blanc E8 (chronométré)
   • Tire N questions au hasard, tous modules confondus.
   • Minuteur avec auto-soumission à 0 ; aucune correction pendant l'épreuve.
   • Navigation libre + marquage « à revoir ».
   • Bulletin final : note /20, % par module, correction détaillée.
   • Dernier résultat mémorisé par utilisateur (localStorage).
   Dépend de : LENNY_MODULES/MODULES, window.QUIZ/STUDY, LennyAPI (option)
   ============================================ */
(function () {
  "use strict";

  const PRESETS = [
    { id: "court", label: "Express", q: 20, min: 20 },
    { id: "blanc", label: "Examen blanc", q: 40, min: 45 },
    { id: "marathon", label: "Marathon", q: 60, min: 75 },
  ];

  const S = { list: [], idx: 0, answers: [], flags: {}, endAt: 0, timer: null, preset: PRESETS[1], running: false };

  /* ---------- identité + stockage ---------- */
  function uid() { try { return (window.LennyAPI && LennyAPI.userId()) || "u_anon"; } catch (e) { return "u_anon"; } }
  const KEY = () => "lenny-exam-v1::" + uid();
  function loadLast() { try { return JSON.parse(localStorage.getItem(KEY())) || null; } catch (e) { return null; } }
  function saveLast(r) { try { localStorage.setItem(KEY(), JSON.stringify(r)); } catch (e) {} }

  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }
  function mods() { return (typeof LENNY_MODULES !== "undefined" && LENNY_MODULES.length) ? LENNY_MODULES : (window.MODULES || []); }
  function shuffle(arr) { const a = [...arr]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

  function buildPool() {
    const pool = [];
    mods().forEach(m => {
      const qs = (window.QUIZ && window.QUIZ[m.id]) || (window.STUDY && window.STUDY[m.id] && window.STUDY[m.id].quiz) || [];
      qs.forEach(q => {
        if (q && Array.isArray(q.c) && typeof q.r === "number") pool.push({ q: q.q, c: q.c, r: q.r, e: q.e || "", mod: m });
      });
    });
    return pool;
  }

  function buildExam(preset) {
    const pool = shuffle(buildPool()).slice(0, preset.q);
    return pool.map(p => {
      const order = shuffle(p.c.map((_, i) => i));
      return { q: p.q, c: order.map(i => p.c[i]), r: order.indexOf(p.r), e: p.e, mod: p.mod };
    });
  }

  /* ---------- DOM ---------- */
  function ensureEl() {
    let el = document.getElementById("lenny-exam");
    if (el) return el;
    el = document.createElement("div");
    el.id = "lenny-exam";
    el.innerHTML = '<div class="ex-backdrop" data-ex-close></div><div class="ex-shell" id="ex-shell" role="dialog" aria-modal="true" aria-label="Examen blanc"></div>';
    document.body.appendChild(el);
    el.addEventListener("click", onClick);
    document.addEventListener("keydown", (e) => {
      if (!el.classList.contains("open")) return;
      if (e.key === "Escape") { e.preventDefault(); attemptClose(); }
      else if (S.running && (e.key === "ArrowRight")) { e.preventDefault(); go(1); }
      else if (S.running && (e.key === "ArrowLeft")) { e.preventDefault(); go(-1); }
    });
    return el;
  }

  function onClick(e) {
    if (e.target.closest("[data-ex-close]")) return attemptClose();
    const pr = e.target.closest("[data-ex-preset]");
    if (pr) { S.preset = PRESETS.find(p => p.id === pr.getAttribute("data-ex-preset")) || PRESETS[1]; renderIntro(); return; }
    if (e.target.closest("[data-ex-start]")) return start();
    const pick = e.target.closest("[data-ex-pick]");
    if (pick && S.running) { answer(parseInt(pick.getAttribute("data-ex-pick"), 10)); return; }
    if (e.target.closest("[data-ex-next]")) return go(1);
    if (e.target.closest("[data-ex-prev]")) return go(-1);
    if (e.target.closest("[data-ex-flag]")) { S.flags[S.idx] = !S.flags[S.idx]; renderRunning(); return; }
    const jump = e.target.closest("[data-ex-jump]");
    if (jump) { S.idx = parseInt(jump.getAttribute("data-ex-jump"), 10); renderRunning(); return; }
    if (e.target.closest("[data-ex-submit]")) return finish(false);
    if (e.target.closest("[data-ex-restart]")) return renderIntro();
    const rev = e.target.closest("[data-ex-review]");
    if (rev) { reviewIdx = parseInt(rev.getAttribute("data-ex-review"), 10); renderReview(); return; }
    if (e.target.closest("[data-ex-back-report]")) return renderReport(S.lastReport);
  }

  /* ---------- intro ---------- */
  function renderIntro() {
    const el = ensureEl();
    const last = loadLast();
    const presets = PRESETS.map(p =>
      `<button class="ex-preset${p.id === S.preset.id ? " on" : ""}" data-ex-preset="${p.id}" type="button">
         <span class="ex-preset-label">${esc(p.label)}</span>
         <span class="ex-preset-meta">${p.q} questions · ${p.min} min</span>
       </button>`).join("");
    const lastHtml = last ? `
      <div class="ex-last">
        <div class="ex-last-h">Dernière session</div>
        <div class="ex-last-row">
          <span class="ex-last-note ${last.note >= 10 ? "ok" : "bad"}">${last.note.toFixed(1)}/20</span>
          <span>${last.correct}/${last.total} bonnes · ${esc(last.dateLabel)}</span>
        </div>
      </div>` : "";
    el.querySelector("#ex-shell").innerHTML = `
      <button class="ex-close" data-ex-close aria-label="Fermer">✕</button>
      <div class="ex-intro">
        <div class="ex-intro-eye">LENNY · Épreuve blanche</div>
        <h2 class="ex-intro-title">Examen E8 chronométré</h2>
        <p class="ex-intro-sub">Conditions réelles : minuteur, questions tirées au hasard de tous les modules, aucune correction avant la fin. Note sur 20 et bulletin détaillé à l'arrivée.</p>
        <div class="ex-presets">${presets}</div>
        ${lastHtml}
        <button class="ex-startbtn" data-ex-start type="button">
          <svg viewBox="0 0 18 18" fill="currentColor"><path d="M4 2 L15 9 L4 16 Z"/></svg>
          Démarrer · ${S.preset.q} questions / ${S.preset.min} min
        </button>
        <div class="ex-intro-rules">Le minuteur ne s'arrête pas. À 0 : remise automatique de la copie.</div>
      </div>`;
  }

  /* ---------- déroulé ---------- */
  function start() {
    S.list = buildExam(S.preset);
    if (!S.list.length) { alert("Banque de questions vide."); return; }
    S.idx = 0; S.answers = new Array(S.list.length).fill(null); S.flags = {};
    S.endAt = Date.now() + S.preset.min * 60000;
    S.running = true;
    startTimer();
    renderRunning();
  }

  function startTimer() {
    stopTimer();
    S.timer = setInterval(() => {
      const left = S.endAt - Date.now();
      const t = document.getElementById("ex-timer");
      if (t) {
        const s = Math.max(0, Math.floor(left / 1000));
        t.textContent = String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
        t.classList.toggle("warn", left <= 60000);
      }
      if (left <= 0) finish(true);
    }, 250);
  }
  function stopTimer() { if (S.timer) { clearInterval(S.timer); S.timer = null; } }

  function answer(i) { S.answers[S.idx] = i; renderRunning(); }
  function go(d) {
    const n = S.idx + d;
    if (n < 0 || n >= S.list.length) return;
    S.idx = n; renderRunning();
  }

  function renderRunning() {
    const el = ensureEl();
    const q = S.list[S.idx];
    const total = S.list.length;
    const answered = S.answers.filter(a => a != null).length;
    const picked = S.answers[S.idx];
    const letters = ["A", "B", "C", "D", "E", "F"];
    const dots = S.list.map((_, i) => {
      let cls = "ex-dot";
      if (i === S.idx) cls += " cur";
      else if (S.answers[i] != null) cls += " done";
      if (S.flags[i]) cls += " flag";
      return `<button class="${cls}" data-ex-jump="${i}" type="button" title="Question ${i + 1}">${i + 1}</button>`;
    }).join("");
    const opts = q.c.map((c, i) =>
      `<button class="ex-opt${picked === i ? " sel" : ""}" data-ex-pick="${i}" type="button">
         <span class="ex-opt-l">${letters[i]}</span><span class="ex-opt-t">${esc(c)}</span>
       </button>`).join("");
    el.querySelector("#ex-shell").innerHTML = `
      <div class="ex-bar">
        <div class="ex-bar-l">
          <span class="ex-bar-eye">Examen E8</span>
          <span class="ex-bar-prog">${answered}/${total} répondues</span>
        </div>
        <div class="ex-timer" id="ex-timer">--:--</div>
        <button class="ex-submit" data-ex-submit type="button">Remettre la copie</button>
      </div>
      <div class="ex-run">
        <div class="ex-q-head">
          <span class="ex-q-tag" style="--mc:var(--${q.mod.color || "red"}, #e50914)">${esc(q.mod.short || q.mod.title)}</span>
          <span class="ex-q-count">Question ${S.idx + 1} / ${total}</span>
          <button class="ex-flagbtn${S.flags[S.idx] ? " on" : ""}" data-ex-flag type="button">
            <svg viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M3 1.5v11M3 2.2h7l-1.4 2.3L10 6.8H3" stroke-linecap="round" stroke-linejoin="round"/></svg>
            ${S.flags[S.idx] ? "Marquée" : "À revoir"}
          </button>
        </div>
        <div class="ex-q">${esc(q.q)}</div>
        <div class="ex-opts">${opts}</div>
      </div>
      <div class="ex-foot">
        <button class="ex-nav" data-ex-prev type="button" ${S.idx === 0 ? "disabled" : ""}>← Précédente</button>
        <div class="ex-dots">${dots}</div>
        ${S.idx === total - 1
          ? `<button class="ex-nav primary" data-ex-submit type="button">Terminer →</button>`
          : `<button class="ex-nav" data-ex-next type="button">Suivante →</button>`}
      </div>`;
    startTimer(); // re-bind le tick au nouveau DOM
  }

  /* ---------- correction ---------- */
  function finish(auto) {
    if (!S.running) return;
    S.running = false; stopTimer();
    let correct = 0; const byMod = {};
    S.list.forEach((q, i) => {
      const ok = S.answers[i] === q.r;
      if (ok) correct++;
      const id = q.mod.id;
      byMod[id] = byMod[id] || { mod: q.mod, correct: 0, total: 0 };
      byMod[id].total++; if (ok) byMod[id].correct++;
    });
    const total = S.list.length;
    const note = total ? Math.round(correct / total * 200) / 10 : 0;
    const now = new Date();
    const report = {
      correct, total, note, auto,
      byMod: Object.values(byMod).sort((a, b) => (b.correct / b.total) - (a.correct / a.total)),
      dateLabel: now.toLocaleDateString("fr-FR", { day: "2-digit", month: "short" }) + " · " + now.toLocaleTimeString("fr-FR", { hour: "2-digit", minute: "2-digit" }),
    };
    S.lastReport = report;
    saveLast({ note, correct, total, dateLabel: report.dateLabel });
    if (window.LennyAPI) report.byMod.forEach(b => LennyAPI.recordQuizResult({ moduleId: b.mod.id, correct: b.correct, total: b.total }));
    renderReport(report);
  }

  function renderReport(r) {
    const el = ensureEl();
    const pass = r.note >= 10;
    const mention = r.note >= 16 ? "Très bien" : r.note >= 14 ? "Bien" : r.note >= 12 ? "Assez bien" : r.note >= 10 ? "Passable" : "Insuffisant";
    const bars = r.byMod.map(b => {
      const p = Math.round(b.correct / b.total * 100);
      return `<div class="ex-modrow">
        <span class="ex-modrow-name">${esc(b.mod.short || b.mod.title)}</span>
        <span class="ex-modbar"><i style="width:${p}%;background:var(--${b.mod.color || "red"}, #d7a13c)"></i></span>
        <span class="ex-modrow-v">${b.correct}/${b.total}</span>
      </div>`;
    }).join("");
    el.querySelector("#ex-shell").innerHTML = `
      <button class="ex-close" data-ex-close aria-label="Fermer">✕</button>
      <div class="ex-report">
        <div class="ex-report-head">
          <div class="ex-grade ${pass ? "ok" : "bad"}">
            <span class="ex-grade-n">${r.note.toFixed(1)}</span><span class="ex-grade-d">/20</span>
          </div>
          <div class="ex-report-meta">
            <div class="ex-report-mention ${pass ? "ok" : "bad"}">${mention}</div>
            <div class="ex-report-line">${r.correct} bonnes réponses sur ${r.total}${r.auto ? " · temps écoulé" : ""}</div>
            <div class="ex-report-date">${esc(r.dateLabel)}</div>
          </div>
        </div>
        <div class="ex-report-sec">
          <h3 class="ex-report-h">Résultat par module</h3>
          <div class="ex-mods">${bars}</div>
        </div>
        <div class="ex-report-actions">
          <button class="ex-nav primary" data-ex-review="0" type="button">Voir la correction</button>
          <button class="ex-nav" data-ex-restart type="button">Refaire un examen</button>
          <button class="ex-nav" data-ex-close type="button">Fermer</button>
        </div>
      </div>`;
  }

  let reviewIdx = 0;
  function renderReview() {
    const el = ensureEl();
    const q = S.list[reviewIdx];
    const picked = S.answers[reviewIdx];
    const ok = picked === q.r;
    const letters = ["A", "B", "C", "D", "E", "F"];
    const opts = q.c.map((c, i) => {
      let cls = "";
      if (i === q.r) cls = " right";
      else if (i === picked) cls = " wrong";
      return `<div class="ex-rev-opt${cls}"><span class="ex-opt-l">${letters[i]}</span><span class="ex-opt-t">${esc(c)}</span></div>`;
    }).join("");
    el.querySelector("#ex-shell").innerHTML = `
      <div class="ex-bar">
        <div class="ex-bar-l"><span class="ex-bar-eye">Correction</span><span class="ex-bar-prog">${reviewIdx + 1}/${S.list.length}</span></div>
        <button class="ex-submit ghost" data-ex-back-report type="button">← Bulletin</button>
      </div>
      <div class="ex-run">
        <div class="ex-q-head">
          <span class="ex-q-tag" style="--mc:var(--${q.mod.color || "red"}, #e50914)">${esc(q.mod.short || q.mod.title)}</span>
          <span class="ex-rev-badge ${ok ? "ok" : "bad"}">${ok ? "✓ Juste" : picked == null ? "Sans réponse" : "✗ Raté"}</span>
        </div>
        <div class="ex-q">${esc(q.q)}</div>
        <div class="ex-opts">${opts}</div>
        ${q.e ? `<div class="ex-rev-expl"><strong>Explication —</strong> ${esc(q.e)}</div>` : ""}
      </div>
      <div class="ex-foot">
        <button class="ex-nav" data-ex-review="${Math.max(0, reviewIdx - 1)}" type="button" ${reviewIdx === 0 ? "disabled" : ""}>← Précédente</button>
        <span class="ex-rev-spacer"></span>
        ${reviewIdx === S.list.length - 1
          ? `<button class="ex-nav primary" data-ex-back-report type="button">Voir le bulletin</button>`
          : `<button class="ex-nav" data-ex-review="${reviewIdx + 1}" type="button">Suivante →</button>`}
      </div>`;
  }

  /* ---------- ouverture / fermeture ---------- */
  function attemptClose() {
    if (S.running) {
      if (!confirm("Quitter l'examen ? Votre copie ne sera pas notée.")) return;
      S.running = false; stopTimer();
    }
    close();
  }
  function open() {
    const el = ensureEl();
    if (!S.running) renderIntro();
    el.classList.add("open");
    document.documentElement.style.overflow = "hidden";
  }
  function close() {
    const el = document.getElementById("lenny-exam");
    if (el) el.classList.remove("open");
    document.documentElement.style.overflow = "";
  }

  window.LennyExam = { open, close };
})();

;
/* ===== lenny-xp.js ===== */
/* ============================================
   LENNY — Gamification (XP · niveaux · streak · badges)
   • Enveloppe LennyAPI.recordQuizResult → attribue de l'XP à chaque
     session de quiz / examen / révision terminée.
   • Streak quotidien, niveaux, badges à débloquer + toasts.
   • HUD compact dans la nav (flamme + niveau) → ouvre un panneau.
   Persistance locale par utilisateur (code d'accès).
   ============================================ */
(function () {
  "use strict";

  const DAY = 86400000;
  const XP_PER_CORRECT = 10;
  const XP_SESSION_BONUS = 15;
  const XP_PERFECT_BONUS = 40;
  const XP_DAILY_LOGIN = 20;

  /* ---------- stockage ---------- */
  function uid() { try { return (window.LennyAPI && LennyAPI.userId()) || "u_anon"; } catch (e) { return "u_anon"; } }
  const KEY = () => "lenny-xp-v1::" + uid();
  function fresh() { return { xp: 0, correct: 0, answered: 0, sessions: 0, perfect: 0, exams: 0, streak: 0, best: 0, last: 0, days: [], badges: [] }; }
  function load() { try { return Object.assign(fresh(), JSON.parse(localStorage.getItem(KEY())) || {}); } catch (e) { return fresh(); } }
  function save(s) { try { localStorage.setItem(KEY(), JSON.stringify(s)); } catch (e) {} }
  function dayKey(t) { const d = new Date(t); return d.getFullYear() + "-" + (d.getMonth() + 1) + "-" + d.getDate(); }

  /* ---------- niveaux ---------- */
  // XP cumulée requise pour atteindre le niveau L : 120 * L*(L-1)/2 (triangulaire)
  function xpForLevel(L) { return 120 * (L * (L - 1) / 2); }
  function levelInfo(xp) {
    let L = 1;
    while (xp >= xpForLevel(L + 1)) L++;
    const cur = xpForLevel(L), next = xpForLevel(L + 1);
    return { level: L, into: xp - cur, span: next - cur, pct: Math.min(100, Math.round((xp - cur) / (next - cur) * 100)), toNext: next - xp };
  }
  const RANKS = ["Stagiaire", "Négociateur junior", "Négociateur", "Conseiller", "Conseiller confirmé", "Expert", "Mandataire", "Directeur d'agence", "Référent BTS", "Maître des clés"];
  function rankFor(L) { return RANKS[Math.min(RANKS.length - 1, L - 1)]; }

  /* ---------- badges ---------- */
  const BADGES = [
    { id: "first", icon: "✦", name: "Première session", desc: "Terminer une première session notée.", check: s => s.sessions >= 1 },
    { id: "perfect", icon: "★", name: "Sans-faute", desc: "Un 100 % sur une session complète.", check: s => s.perfect >= 1 },
    { id: "streak3", icon: "▲", name: "Régulier", desc: "3 jours d'affilée.", check: s => s.best >= 3 },
    { id: "streak7", icon: "♦", name: "Assidu", desc: "7 jours d'affilée.", check: s => s.best >= 7 },
    { id: "streak30", icon: "◆", name: "Inarrêtable", desc: "30 jours d'affilée.", check: s => s.best >= 30 },
    { id: "exam1", icon: "▣", name: "Première copie", desc: "Passer un examen blanc.", check: s => s.exams >= 1 },
    { id: "c100", icon: "❖", name: "Centurion", desc: "100 bonnes réponses cumulées.", check: s => s.correct >= 100 },
    { id: "c500", icon: "✺", name: "Vétéran", desc: "500 bonnes réponses cumulées.", check: s => s.correct >= 500 },
    { id: "lvl5", icon: "⬠", name: "Confirmé", desc: "Atteindre le niveau 5.", check: s => levelInfo(s.xp).level >= 5 },
    { id: "lvl10", icon: "⬡", name: "Maître des clés", desc: "Atteindre le niveau 10.", check: s => levelInfo(s.xp).level >= 10 },
  ];

  /* ---------- attribution ---------- */
  function touchStreak(s) {
    const today = dayKey(Date.now());
    if (s.days.includes(today)) return false; // déjà actif aujourd'hui
    // calcul de la continuité
    const yest = dayKey(Date.now() - DAY);
    if (s.days.includes(yest) || s.streak === 0) s.streak = (s.days.includes(yest) ? s.streak : 0) + 1;
    else s.streak = 1;
    s.best = Math.max(s.best, s.streak);
    s.days.push(today);
    if (s.days.length > 400) s.days = s.days.slice(-400);
    s.last = Date.now();
    s.xp += XP_DAILY_LOGIN; // bonus de présence quotidienne
    return true;
  }

  function checkBadges(s) {
    const newly = [];
    BADGES.forEach(b => { if (!s.badges.includes(b.id) && b.check(s)) { s.badges.push(b.id); newly.push(b); } });
    return newly;
  }

  // appelé à chaque session terminée
  function awardSession(res) {
    const s = load();
    const correct = res.correct | 0, total = Math.max(0, res.total | 0);
    let gained = correct * XP_PER_CORRECT + XP_SESSION_BONUS;
    if (total > 0 && correct === total) { gained += XP_PERFECT_BONUS; s.perfect++; }
    s.xp += gained; s.correct += correct; s.answered += total; s.sessions++;
    if (res.exam) s.exams++;
    const beforeLvl = levelInfo(s.xp - gained).level;
    touchStreak(s);
    const afterLvl = levelInfo(s.xp).level;
    const newBadges = checkBadges(s);
    save(s);
    if (afterLvl > beforeLvl) toast("level", afterLvl);
    newBadges.forEach(b => toast("badge", b));
    if (gained) toast("xp", gained);
    refreshHud();
    return s;
  }

  // bonus de présence à l'ouverture (sans session)
  function dailyTouch() {
    const s = load();
    if (touchStreak(s)) {
      const nb = checkBadges(s);
      save(s);
      nb.forEach(b => toast("badge", b));
      refreshHud();
    }
  }

  /* ---------- toasts ---------- */
  function toastLayer() {
    let l = document.getElementById("xp-toasts");
    if (!l) { l = document.createElement("div"); l.id = "xp-toasts"; document.body.appendChild(l); }
    return l;
  }
  function toast(kind, data) {
    const l = toastLayer();
    const t = document.createElement("div");
    t.className = "xp-toast xp-toast-" + kind;
    if (kind === "xp") t.innerHTML = `<span class="xp-toast-ic">＋</span><span><b>+${data} XP</b></span>`;
    else if (kind === "level") t.innerHTML = `<span class="xp-toast-ic">⬆</span><span>Niveau <b>${data}</b> · ${rankFor(data)}</span>`;
    else if (kind === "badge") t.innerHTML = `<span class="xp-toast-ic">${data.icon}</span><span>Badge débloqué<br><b>${data.name}</b></span>`;
    l.appendChild(t);
    requestAnimationFrame(() => t.classList.add("in"));
    setTimeout(() => { t.classList.remove("in"); setTimeout(() => t.remove(), 400); }, kind === "xp" ? 1800 : 3200);
  }

  /* ---------- HUD (nav) ---------- */
  function ensureHud() {
    let hud = document.getElementById("xp-hud");
    if (hud) return hud;
    const navRight = document.querySelector(".nav-right");
    if (!navRight) return null;
    hud = document.createElement("button");
    hud.id = "xp-hud"; hud.type = "button"; hud.className = "xp-hud"; hud.title = "Progression";
    const avatar = navRight.querySelector(".avatar");
    if (avatar) navRight.insertBefore(hud, avatar); else navRight.appendChild(hud);
    hud.addEventListener("click", (e) => { e.stopPropagation(); openPanel(); });
    return hud;
  }
  function refreshHud() {
    const hud = ensureHud();
    if (!hud) return;
    const s = load();
    const li = levelInfo(s.xp);
    const C = 2 * Math.PI * 13;
    hud.innerHTML = `
      ${s.streak > 0 ? `<span class="xp-hud-streak"><svg viewBox="0 0 12 14" fill="currentColor"><path d="M6 0c1.6 2.4.6 3.8 0 4.8C5.2 6 4 6.8 4 8.4 4 10 5 11 6 11s2-1 2-2.6c0-.7-.2-1.2-.5-1.7C8.8 7.4 10 8.6 10 10.2 10 12.3 8.2 14 6 14s-4-1.7-4-3.8C2 6.7 5.4 5.6 6 0Z"/></svg>${s.streak}</span>` : ""}
      <span class="xp-hud-ring">
        <svg viewBox="0 0 30 30"><circle cx="15" cy="15" r="13" fill="none" stroke="rgba(255,255,255,.14)" stroke-width="3"/><circle cx="15" cy="15" r="13" fill="none" stroke="#f6c451" stroke-width="3" stroke-linecap="round" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${(C * (1 - li.pct / 100)).toFixed(1)}" transform="rotate(-90 15 15)"/></svg>
        <span class="xp-hud-lvl">${li.level}</span>
      </span>`;
  }

  /* ---------- panneau ---------- */
  function ensurePanel() {
    let el = document.getElementById("lenny-xp");
    if (el) return el;
    el = document.createElement("div");
    el.id = "lenny-xp";
    el.innerHTML = '<div class="xp-backdrop" data-xp-close></div><div class="xp-shell" id="xp-shell" role="dialog" aria-modal="true" aria-label="Progression"></div>';
    document.body.appendChild(el);
    el.addEventListener("click", (e) => { if (e.target.closest("[data-xp-close]")) closePanel(); });
    document.addEventListener("keydown", (e) => { if (e.key === "Escape" && el.classList.contains("open")) closePanel(); });
    return el;
  }
  function openPanel() {
    const el = ensurePanel();
    renderPanel();
    el.classList.add("open");
    document.documentElement.style.overflow = "hidden";
  }
  function closePanel() {
    const el = document.getElementById("lenny-xp");
    if (el) el.classList.remove("open");
    document.documentElement.style.overflow = "";
  }
  function renderPanel() {
    const s = load();
    const li = levelInfo(s.xp);
    const acc = s.answered ? Math.round(s.correct / s.answered * 100) : 0;
    // streak des 14 derniers jours
    const cells = [];
    for (let i = 13; i >= 0; i--) {
      const k = dayKey(Date.now() - i * DAY);
      const on = s.days.includes(k);
      const d = new Date(Date.now() - i * DAY);
      cells.push(`<span class="xp-day${on ? " on" : ""}" title="${d.toLocaleDateString("fr-FR")}">${d.getDate()}</span>`);
    }
    const badges = BADGES.map(b => {
      const has = s.badges.includes(b.id);
      return `<div class="xp-badge${has ? " has" : ""}" title="${b.desc}">
        <span class="xp-badge-ic">${b.icon}</span>
        <span class="xp-badge-name">${b.name}</span>
        <span class="xp-badge-desc">${b.desc}</span>
      </div>`;
    }).join("");
    ensurePanel().querySelector("#xp-shell").innerHTML = `
      <button class="xp-close" data-xp-close aria-label="Fermer">✕</button>
      <div class="xp-hero">
        <div class="xp-hero-badge">
          <svg viewBox="0 0 72 72"><circle cx="36" cy="36" r="31" fill="none" stroke="rgba(255,255,255,.12)" stroke-width="6"/><circle cx="36" cy="36" r="31" fill="none" stroke="#f6c451" stroke-width="6" stroke-linecap="round" stroke-dasharray="${(2 * Math.PI * 31).toFixed(1)}" stroke-dashoffset="${(2 * Math.PI * 31 * (1 - li.pct / 100)).toFixed(1)}" transform="rotate(-90 36 36)"/></svg>
          <span class="xp-hero-lvl">${li.level}</span>
        </div>
        <div class="xp-hero-meta">
          <div class="xp-hero-rank">${rankFor(li.level)}</div>
          <div class="xp-hero-xp">${s.xp.toLocaleString("fr-FR")} XP · encore ${li.toNext.toLocaleString("fr-FR")} pour le niveau ${li.level + 1}</div>
          <div class="xp-hero-bar"><i style="width:${li.pct}%"></i></div>
        </div>
      </div>
      <div class="xp-stats">
        <div class="xp-stat"><span class="xp-stat-n">${s.streak}</span><span class="xp-stat-l">jours d'affilée</span></div>
        <div class="xp-stat"><span class="xp-stat-n">${s.correct}</span><span class="xp-stat-l">bonnes réponses</span></div>
        <div class="xp-stat"><span class="xp-stat-n">${acc}%</span><span class="xp-stat-l">précision</span></div>
        <div class="xp-stat"><span class="xp-stat-n">${s.badges.length}/${BADGES.length}</span><span class="xp-stat-l">badges</span></div>
      </div>
      <div class="xp-sec">
        <div class="xp-sec-h">Assiduité · 14 jours <span class="xp-sec-side">Record : ${s.best} j</span></div>
        <div class="xp-days">${cells.join("")}</div>
      </div>
      <div class="xp-sec">
        <div class="xp-sec-h">Badges</div>
        <div class="xp-badges">${badges}</div>
      </div>`;
  }

  /* ---------- intégration ---------- */
  function wrapApi() {
    if (!window.LennyAPI || window.LennyAPI.__xpWrapped) return;
    const orig = window.LennyAPI.recordQuizResult;
    if (typeof orig !== "function") return;
    window.LennyAPI.recordQuizResult = function (res) {
      try { awardSession(res || {}); } catch (e) {}
      return orig.apply(this, arguments);
    };
    window.LennyAPI.__xpWrapped = true;
  }

  function init() {
    wrapApi();
    ensureHud();
    refreshHud();
    dailyTouch();
    // ré-attache le HUD si la nav est reconstruite après connexion
    document.addEventListener("lenny-auth", () => { setTimeout(() => { refreshHud(); }, 80); });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", () => setTimeout(init, 120));
  else setTimeout(init, 120);

  window.LennyXP = {
    open: openPanel, close: closePanel,
    award: (correct, total, opts) => awardSession(Object.assign({ correct, total }, opts || {})),
    refresh: refreshHud,
    state: load,
  };
})();

