/* ===== lenny-facade.js ===== */
/* ============================================
   LENNY — Façade haussmannienne (progression signature)
   Un immeuble dont chaque fenêtre = un module. La fenêtre s'allume
   quand l'élève a une activité de quiz sur ce module. Toit mansardé,
   balcons en fer forgé : repère visuel propre à LENNY.
   Dépend de : MODULES, lenny-quiz-history-v1 (LennyAPI), LennySRS (option)
   ============================================ */
(function () {
  "use strict";

  function mods() { return (window.MODULES || []).filter(m => {
    const qs = (window.QUIZ && window.QUIZ[m.id]) || (window.STUDY && window.STUDY[m.id] && window.STUDY[m.id].quiz) || [];
    return qs.length > 0;
  }); }

  function engagedSet() {
    const set = {};
    try {
      const hist = JSON.parse(localStorage.getItem("lenny-quiz-history-v1")) || [];
      hist.forEach(h => {
        // une fenêtre s'allume dès qu'un module dépasse 60 % de réussite cumulée
        const id = h.moduleId;
        set[id] = set[id] || { c: 0, t: 0 };
        set[id].c += h.correct | 0; set[id].t += h.total | 0;
      });
    } catch (e) {}
    const lit = {};
    Object.keys(set).forEach(id => { if (set[id].t > 0 && set[id].c / set[id].t >= 0.6) lit[id] = true; });
    return { lit, raw: set };
  }

  function buildSection() {
    const mount = document.getElementById("progress-facade-mount");
    if (mount) {
      let sec = document.getElementById("facade-home");
      if (sec) return sec;
      sec = document.createElement("section");
      sec.className = "facade-home";
      sec.id = "facade-home";
      mount.appendChild(sec);
      return sec;
    }
    const home = document.getElementById("view-home");
    if (!home) return null;
    let sec = document.getElementById("facade-home");
    if (sec) return sec;
    sec = document.createElement("section");
    sec.className = "facade-home";
    sec.id = "facade-home";
    // insère après le bandeau SRS s'il existe, sinon avant "Reprendre"
    const srs = document.getElementById("srs-home");
    const cont = document.getElementById("continue");
    if (srs && srs.parentNode === home) srs.after(sec);
    else if (cont && cont.parentNode === home) home.insertBefore(sec, cont);
    else home.appendChild(sec);
    return sec;
  }

  function windowsHtml(list, lit) {
    return list.map((m, i) => {
      const on = !!lit[m.id];
      return `<button class="fc-win${on ? " on" : ""}" data-fc-mod="${m.id}" title="${m.title}${on ? " · acquis" : ""}" style="--wc:${m.color || "#d7a13c"}">
        <span class="fc-win-glow"></span>
        <span class="fc-win-pane"><i></i><i></i></span>
        <span class="fc-win-rail"></span>
        <span class="fc-win-label">${m.short || m.title}</span>
      </button>`;
    }).join("");
  }

  function render() {
    const sec = buildSection();
    if (!sec) return;
    const list = mods();
    if (!list.length) { sec.remove(); return; }
    const { lit } = engagedSet();
    const litCount = list.filter(m => lit[m.id]).length;
    const pct = Math.round(litCount / list.length * 100);
    sec.innerHTML = `
      <div class="fc-wrap">
        <div class="fc-head">
          <div>
            <div class="fc-kicker">Votre progression</div>
            <h2 class="fc-h">L'immeuble se rallume à chaque module acquis</h2>
            <p class="fc-sub">${litCount} module${litCount > 1 ? "s" : ""} sur ${list.length} maîtrisé${litCount > 1 ? "s" : ""} — une fenêtre s'allume dès 60 % de réussite au quiz.</p>
          </div>
          <div class="fc-meter">
            <div class="fc-meter-pct">${pct}<small>%</small></div>
            <div class="fc-meter-bar"><i style="width:${pct}%"></i></div>
          </div>
        </div>
        <div class="fc-building">
          <div class="fc-roof"><span class="fc-chimney"></span><span class="fc-chimney c2"></span><span class="fc-dormer"></span></div>
          <div class="fc-cornice"></div>
          <div class="fc-facade">
            <div class="fc-windows">${windowsHtml(list, lit)}</div>
          </div>
          <div class="fc-ground">
            <span class="fc-door"></span>
            <span class="fc-awning"></span>
            <span class="fc-shop">LENNY · IMMOBILIER</span>
          </div>
        </div>
      </div>`;
    sec.querySelectorAll("[data-fc-mod]").forEach(b => {
      b.addEventListener("click", () => {
        const id = b.getAttribute("data-fc-mod");
        if (window.LennyDetail) window.LennyDetail.open(id);
      });
    });
  }

  function refresh() { try { render(); } catch (e) {} }

  function init() {
    refresh();
    // se met à jour quand une session de quiz est enregistrée
    if (window.LennyAPI && typeof LennyAPI.recordQuizResult === "function" && !LennyAPI.__facadeWrapped) {
      const orig = LennyAPI.recordQuizResult;
      LennyAPI.recordQuizResult = function () { const r = orig.apply(this, arguments); setTimeout(refresh, 30); return r; };
      LennyAPI.__facadeWrapped = true;
    }
    document.addEventListener("lenny-auth", () => setTimeout(refresh, 100));
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", () => setTimeout(init, 140));
  else setTimeout(init, 140);

  window.LennyFacade = { refresh };
})();

;
/* ===== lenny-navfolder.js ===== */
/* ============================================
   LENNY — Dossier d'outils dans la nav
   Regroupe les 5 boutons (Révisions, Quiz, Examen, Devoir, Calculatrices)
   sous un seul bouton « Réviser » qui ouvre un menu déroulant. Les boutons
   d'origine sont déplacés tels quels : leurs actions restent branchées.
   Ajoute un accès « Ma progression » (page immeuble + révision du jour).
   ============================================ */
(function () {
  "use strict";

  function init() {
    const navRight = document.querySelector(".nav-right");
    if (!navRight || document.getElementById("tools-folder")) return;
    const ids = ["revise-btn", "srs-btn", "quiz-general-btn", "exam-btn", "devoir-general-btn", "calc-btn"];
    const btns = ids.map(id => document.getElementById(id)).filter(Boolean);
    if (!btns.length) return;

    const folder = document.createElement("div");
    folder.className = "nav-folder";
    folder.id = "tools-folder";
    folder.innerHTML = `
      <button class="nav-folder-btn" id="tools-folder-btn" type="button" aria-haspopup="true" aria-expanded="false" title="Outils de révision">
        <svg class="nav-folder-ic" viewBox="0 0 18 18" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"><path d="M2 5.4a1 1 0 0 1 1-1h3.1l1.3 1.6H15a1 1 0 0 1 1 1V13a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1V5.4Z"/></svg>
        <span>Réviser</span>
        <span class="nav-folder-dot" id="tools-folder-dot" hidden></span>
        <svg class="nav-folder-caret" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><polyline points="3,4.5 6,7.5 9,4.5"/></svg>
      </button>
      <div class="nav-folder-menu" id="tools-folder-menu" role="menu"></div>`;
    navRight.insertBefore(folder, navRight.firstChild);

    const menu = folder.querySelector("#tools-folder-menu");
    btns.forEach(b => { b.classList.add("nav-folder-item"); menu.appendChild(b); });

    // séparateur + accès "Ma progression"
    const div = document.createElement("div");
    div.className = "nav-folder-div";
    menu.appendChild(div);
    const prog = document.createElement("button");
    prog.className = "nav-folder-item nav-folder-progress";
    prog.id = "progress-nav"; prog.type = "button";
    prog.innerHTML = `<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"><path d="M2 14V6.4L8 2l6 4.4V14"/><path d="M2 11.2h12M6 14v-3h4v3"/></svg> Ma progression`;
    menu.appendChild(prog);
    prog.addEventListener("click", () => { close(); if (window.LennyRouter) window.LennyRouter.go("progress"); });

    const tbtn = folder.querySelector("#tools-folder-btn");
    function open() { folder.classList.add("open"); tbtn.setAttribute("aria-expanded", "true"); }
    function close() { folder.classList.remove("open"); tbtn.setAttribute("aria-expanded", "false"); }
    tbtn.addEventListener("click", (e) => { e.stopPropagation(); folder.classList.contains("open") ? close() : open(); });
    menu.addEventListener("click", (e) => { if (e.target.closest(".nav-folder-item")) close(); });
    document.addEventListener("click", (e) => { if (!e.target.closest("#tools-folder")) close(); });
    document.addEventListener("keydown", (e) => { if (e.key === "Escape") close(); });

    // pastille de rappel sur le dossier, miroir du badge "Révisions"
    function syncDot() {
      const dot = document.getElementById("tools-folder-dot");
      if (!dot) return;
      const srs = document.getElementById("srs-badge");
      const mf = document.getElementById("mf-badge");
      const show = (srs && !srs.hidden) || (mf && !mf.hidden);
      dot.hidden = !show;
    }
    syncDot();
    ["srs-badge", "mf-badge"].forEach(function (id) {
      const b = document.getElementById(id);
      if (b) new MutationObserver(syncDot).observe(b, { attributes: true, childList: true, subtree: true });
    });
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", () => setTimeout(init, 220));
  else setTimeout(init, 220);
})();

